// 🌌 SKY SYSTEM SAVE/LOAD FUNCTIONS
function loadSkySettingsForLevel(levelId) {
  const storageKey = `sky_settings_${levelId}`;
  try {
    const saved = localStorage.getItem(storageKey);
    if (saved) {
      const settings = JSON.parse(saved);
      console.log(`📂 [SKY] Loaded saved settings for ${levelId}:`, settings);
      return settings;
    }
  } catch (e) {
    console.warn(`⚠️ [SKY] Failed to load saved settings for ${levelId}:`, e);
  }
  return null;
}

function getSkyConfigForLevel(levelId) {
  // Start with default config
  const defaultConfig = levelSkyConfigs[levelId];
  if (!defaultConfig) {
    console.warn("⚠️ [SKY SYSTEM] No default sky config for level:", levelId);
    return null;
  }

  // Try to load saved settings
  const savedSettings = loadSkySettingsForLevel(levelId);
  
  if (savedSettings) {
      // Merge saved settings with defaults
      const mergedConfig = {
        ...defaultConfig,
        // Override with saved settings if they exist
        ...(savedSettings.enableDayNight !== undefined && { enableDayNight: savedSettings.enableDayNight }),
        ...(savedSettings.cloudDensity !== undefined && { cloudDensity: savedSettings.cloudDensity }),
        ...(savedSettings.starCount !== undefined && { starCount: savedSettings.starCount }),
        ...(savedSettings.enableLensflare !== undefined && { enableLensflare: savedSettings.enableLensflare }),
        ...(savedSettings.timeSpeedMultiplier !== undefined && { timeSpeedMultiplier: savedSettings.timeSpeedMultiplier }),
        // Store saved time for later use (can't set timeOfDay directly, need to use setTime)
        _savedHour: savedSettings.hour,
        _savedMinute: savedSettings.minute,
        _savedTimeOfDay: savedSettings.timeOfDay, // Also store timeOfDay
        _savedTimeLoaded: true
      };
    
    console.log(`🌌 [SKY] Using merged config for ${levelId} (saved settings + defaults):`, mergedConfig);
    return mergedConfig;
  }
  
  // Return default config if no saved settings
  return defaultConfig;
}

