function getGroundConfigForLevel(levelId) {
  // Start with default config
  const defaultConfig = levelGroundConfigs[levelId];
  if (!defaultConfig) {
    console.warn("⚠️ [GROUND SYSTEM] No default ground config for level:", levelId);
    return null;
  }

  // Try to load saved settings
  const savedSettings = loadGroundSettingsForLevel(levelId);
  
  // Create a copy of the config to avoid modifying the original
  let mergedConfig = { ...defaultConfig };
  
  if (savedSettings) {
    // Merge saved settings with defaults (preserve position)
    mergedConfig = {
      ...mergedConfig,
      // Override with saved settings if they exist
      ...(savedSettings.groundType !== undefined && { groundType: savedSettings.groundType }),
      ...(savedSettings.bladeCount !== undefined && { bladeCount: savedSettings.bladeCount }),
      ...(savedSettings.bladeLengthMultiplier !== undefined && { bladeLengthMultiplier: savedSettings.bladeLengthMultiplier }), // Load blade length multiplier
      ...(savedSettings.windSpeed !== undefined && { windSpeed: savedSettings.windSpeed }),
      ...(savedSettings.windStrength !== undefined && { windStrength: savedSettings.windStrength }),
      ...(savedSettings.windDirectionAngle !== undefined && { windDirectionAngle: savedSettings.windDirectionAngle }),
      ...(savedSettings.windTurbulence !== undefined && { windTurbulence: savedSettings.windTurbulence }), // NEW: Load wind turbulence
      ...(savedSettings.windGustFrequency !== undefined && { windGustFrequency: savedSettings.windGustFrequency }), // NEW: Load wind gust frequency
      ...(savedSettings.windGustIntensity !== undefined && { windGustIntensity: savedSettings.windGustIntensity }), // NEW: Load wind gust intensity
      ...(savedSettings.useChunkedGrass !== undefined && { useChunkedGrass: savedSettings.useChunkedGrass }), // NEW: Load chunked grass setting
      ...(savedSettings.chunkSize !== undefined && { chunkSize: savedSettings.chunkSize }), // NEW: Load chunk size
      ...(savedSettings.maxBladesPerChunk !== undefined && { maxBladesPerChunk: savedSettings.maxBladesPerChunk }), // NEW: Load max blades per chunk
      ...(savedSettings.grassColor !== undefined && { grassColor: savedSettings.grassColor }),
      ...(savedSettings.groundColor !== undefined && { groundColor: savedSettings.groundColor }),
      ...(savedSettings.undergroundType !== undefined && { undergroundType: savedSettings.undergroundType }),
      ...(savedSettings.undergroundColor !== undefined && { undergroundColor: savedSettings.undergroundColor }),
      ...(savedSettings.undergroundTexturePath !== undefined && { undergroundTexturePath: savedSettings.undergroundTexturePath })
    };
    
    console.log(`🌱 [GROUND] Using merged config for ${levelId} (saved settings + defaults):`, mergedConfig);
  }
  
  // FIX: For Level 5, use detected ground level from spawn position
  // This ensures grass is positioned at the same level as the player
  if (levelId === LEVEL_IDS.LEVEL5 && level5State && level5State.spawnPosition) {
    const detectedGroundY = level5State.spawnPosition.y;
    // Always use detected ground level if available (even if it's 0)
    if (detectedGroundY !== undefined) {
      // Clone the position Vector3 and update Y to match detected ground level
      mergedConfig.position = mergedConfig.position.clone();
      mergedConfig.position.y = detectedGroundY;
      console.log(`🌱 [LEVEL 5] Using detected ground level for grass: Y=${detectedGroundY.toFixed(2)} (spawn Y: ${level5State.spawnPosition.y.toFixed(2)})`);
    } else {
      console.warn(`⚠️ [LEVEL 5] Spawn position Y not available, using default position`);
    }
  }
  
  return mergedConfig;
}

function saveGroundSettingsForLevel(levelId) {
  if (!grassSystem || !levelId) return;
  
  const currentOptions = grassSystem.getOptions();
  const settings = {
    groundType: currentOptions.groundType,
    bladeCount: currentOptions.bladeCount,
    bladeLengthMultiplier: currentOptions.bladeLengthMultiplier, // Save blade length multiplier
    windSpeed: currentOptions.windSpeed,
    windStrength: currentOptions.windStrength,
    windDirectionAngle: currentOptions.windDirectionAngle !== undefined ? currentOptions.windDirectionAngle : 0.0, // NEW: Save wind direction angle
    useChunkedGrass: currentOptions.useChunkedGrass !== undefined ? currentOptions.useChunkedGrass : false, // NEW: Save chunked grass setting
    chunkSize: currentOptions.chunkSize !== undefined ? currentOptions.chunkSize : 50, // NEW: Save chunk size
    maxBladesPerChunk: currentOptions.maxBladesPerChunk !== undefined ? currentOptions.maxBladesPerChunk : 200000, // NEW: Save max blades per chunk
    grassColor: currentOptions.grassColor,
    groundColor: currentOptions.groundColor,
    undergroundType: currentOptions.undergroundType,
    undergroundColor: currentOptions.undergroundColor,
    undergroundTexturePath: currentOptions.undergroundTexturePath
  };
  
  const storageKey = `ground_settings_${levelId}`;
  try {
    localStorage.setItem(storageKey, JSON.stringify(settings));
    console.log(`💾 [GROUND] Saved settings for ${levelId}:`, settings);
    
    // Show feedback
    if (window.showToast) {
      showToast(`🌱 Ground settings saved for ${levelId}!`, 2000);
    }
  } catch (e) {
    console.error(`❌ [GROUND] Failed to save settings for ${levelId}:`, e);
  }
}

// 🌱 GROUND SYSTEM INITIALIZATION AND MANAGEMENT
async function initializeGrassSystem(levelId) {
  // Dispose existing ground system if present
  if (grassSystem) {
    grassSystem.dispose();
    grassSystem = null;
  }
  
  // Get ground configuration for this level (with saved settings merged in)
  const groundConfig = getGroundConfigForLevel(levelId);
  if (!groundConfig) {
    console.warn("⚠️ [GROUND SYSTEM] No ground config for level:", levelId);
    return;
  }
  
  // Initialize grass system with level-specific configuration
  try {
    grassSystem = new GrassSystem(scene, groundConfig);
    console.log("🌱 [GROUND SYSTEM] Initialized for", levelId, groundConfig);
    
    // CRITICAL: Update chestSystem's grassSystem reference when grassSystem is recreated
    // This ensures exclusion zones can be registered even after level cleanup/reload
    if (chestSystem && typeof chestSystem.setGrassSystem === 'function') {
      chestSystem.setGrassSystem(grassSystem);
      console.log("🌱 [GROUND SYSTEM] Updated chestSystem's grassSystem reference");
    }
    
    // If GLTF ground type, wait for map to load
    if (groundConfig.groundType === 'gltf') {
      await grassSystem.loadGLTFMap();
      console.log("🗺️ [GROUND SYSTEM] GLTF map loaded for", levelId);
    }
  } catch (error) {
    console.error("❌ [GROUND SYSTEM] Failed to initialize:", error);
    grassSystem = null;
  }
}

// 🌌 SKY SYSTEM INITIALIZATION AND MANAGEMENT
function initializeSkySystem(levelId) {
  // Dispose existing sky system if present
  if (skySystem) {
    skySystem.dispose();
    skySystem = null;
  }
  
  // Get sky configuration for this level (with saved settings merged in)
  const skyConfig = getSkyConfigForLevel(levelId);
  if (!skyConfig) {
    console.warn("⚠️ [SKY SYSTEM] No sky config for level:", levelId);
    return;
  }
  
  // Extract saved time if available (remove from config before passing to SkySystem)
  const savedHour = skyConfig._savedHour;
  const savedMinute = skyConfig._savedMinute;
  const savedTimeOfDay = skyConfig._savedTimeOfDay;
  delete skyConfig._savedHour;
  delete skyConfig._savedMinute;
  delete skyConfig._savedTimeOfDay;
  delete skyConfig._savedTimeLoaded;
  
  // Initialize sky system with level-specific configuration
  try {
    skySystem = new SkySystem(scene, skyConfig);
    console.log("🌌 [SKY SYSTEM] Initialized for", levelId, skyConfig);
    
    // Apply saved time if available
    if (savedHour !== undefined && savedMinute !== undefined) {
      skySystem.setTime(savedHour, savedMinute);
      console.log(`🌌 [SKY SYSTEM] Applied saved time for ${levelId}: ${savedHour}:${savedMinute.toString().padStart(2, '0')}`);
    }
    
    // Apply saved timeOfDay if available (this sets the visual appearance - dawn/day/dusk/night)
    if (savedTimeOfDay) {
      skySystem.setTimeOfDay(savedTimeOfDay);
      console.log(`🌌 [SKY SYSTEM] Applied saved timeOfDay for ${levelId}: ${savedTimeOfDay}`);
    }
    
    // CRITICAL: Ensure skybox is visible
    if (skySystem && skySystem.skybox) {
      skySystem.skybox.visible = true;
      console.log("🌌 [SKY SYSTEM] Skybox visibility set to true for", levelId);
    }
    
    // CRITICAL: Force immediate initial update to set sky appearance
    // This ensures the sky displays correctly even before the first animate() frame
    // NOTE: Camera might not exist yet during initial setup, so we skip update if camera is not available
    // The sky system will be updated in the animate loop once camera is ready
    // FIX: Check if camera exists before accessing it (use try-catch to avoid TDZ errors)
    let cameraReady = false;
    try {
      cameraReady = typeof camera !== 'undefined' && camera !== null;
    } catch (e) {
      cameraReady = false;
    }
    if (skySystem && cameraReady) {
      // Get player position safely (playerCollider may not exist yet during initialization)
      let playerPosition = new THREE.Vector3(0, 1, 0); // Default position
      if (playerCollider && playerCollider.start && playerCollider.end) {
        playerPosition = new THREE.Vector3().lerpVectors(
          playerCollider.start,
          playerCollider.end,
          0.5
        );
      }
      // Force initial update with zero delta to set initial state
      skySystem.update(0, playerPosition, camera);
      console.log("🌌 [SKY SYSTEM] Initial update forced for", levelId);
      
      // Verify sky system components are in scene
      if (skySystem.skybox && scene.children.includes(skySystem.skybox)) {
        console.log("✅ [SKY SYSTEM] Skybox confirmed in scene for", levelId);
      } else {
        console.warn("⚠️ [SKY SYSTEM] Skybox NOT in scene for", levelId);
      }
      if (skySystem.skybox && skySystem.skybox.sun && scene.children.includes(skySystem.skybox.sun)) {
        console.log("✅ [SKY SYSTEM] Sun light confirmed in scene for", levelId);
      } else {
        console.warn("⚠️ [SKY SYSTEM] Sun light NOT in scene for", levelId);
      }
    } else if (skySystem && !cameraReady) {
      console.log("⏸️ [SKY SYSTEM] Skipping initial update - camera not ready yet (will update in animate loop)");
    }
  } catch (error) {
    console.error("❌ [SKY SYSTEM] Failed to initialize:", error);
    console.error("❌ [SKY SYSTEM] Error stack:", error.stack);
    skySystem = null;
  }
}

async function applyLevelEnvironment(levelId) {
  // 🌌 NEW: Use SkySystem as standard for all levels
  initializeSkySystem(levelId);
  
  // 🌱 NEW: Use GrassSystem as standard for all levels (now async for GLTF loading)
  await initializeGrassSystem(levelId);
  
  // GRASS EXCLUSION ZONE SYSTEM (Phase 2)
  // Update chest system with grass system reference for auto-registration
  if (chestSystem && grassSystem && typeof chestSystem.setGrassSystem === 'function') {
    chestSystem.setGrassSystem(grassSystem);
  }
  
  // Clear scene.background to allow skybox to render (skybox is a mesh, not scene.background)
  scene.background = null;
  
  // Legacy environment system (kept for reference, but SkySystem replaces it)
  const env = levelEnvironments[levelId];
  if (!env) {
    console.warn("⚠️ [ENVIRONMENT] No environment config for level:", levelId);
    return;
  }
  
  // CRITICAL: Clear fog when sky system is active (fog blocks skybox rendering)
  // SkySystem manages its own fog/atmosphere through shaders, so we disable scene.fog
  if (skySystem) {
    // SkySystem is active - clear fog to allow skybox to render properly
    scene.fog = null;
    console.log("🌌 [ENVIRONMENT] Fog cleared - SkySystem handles atmosphere");
  } else if (env.fog) {
    // Fallback to legacy fog only if SkySystem not available
    scene.fog = new THREE.Fog(env.fog.color, env.fog.near, env.fog.far);
    console.log("🌌 [ENVIRONMENT] Using legacy fog (SkySystem not available)");
  } else {
    scene.fog = null;
  }
  
  console.log("🌍 [ENVIRONMENT] Applied environment for", levelId, {
    skySystem: skySystem ? "enabled" : "disabled",
    sceneBackgroundCleared: true,
    fog: env.fog ? "enabled" : "disabled"
  });
  
  // Play background music for this level (only if audioListener is initialized)
  // Skip during initial setup - music will start in startGame()
  try {
    if (audioListener) {
      playBackgroundMusic(levelId);
    }
  } catch (e) {
    // audioListener not initialized yet, skip music (will start in startGame())
  }
}

applyLevelEnvironment(LEVEL_IDS.LEVEL1);

const renderer = new THREE.WebGLRenderer({
  antialias: !isMobile,
  powerPreference: "high-performance"
});
// CRITICAL: Set pixel ratio for optimal quality on full HD screens (January 4, 2026)
// Use devicePixelRatio for sharp visuals, but cap at 2.0 for performance
const pixelRatio = isMobile ? 1 : Math.min(2.0, window.devicePixelRatio || 1);
renderer.setPixelRatio(pixelRatio);
renderer.setSize(window.innerWidth, window.innerHeight);
console.log(`🖥️ [RENDERER] Pixel ratio set to: ${pixelRatio} (devicePixelRatio: ${window.devicePixelRatio || 1}, screen: ${window.innerWidth}x${window.innerHeight})`);
renderer.shadowMap.enabled = true;

// 🥽 VR/WebXR Support - Enable VR rendering
renderer.xr.enabled = true;
renderer.xr.setReferenceSpaceType('local-floor'); // Floor-level tracking for better VR experience
console.log('🥽 [VR] WebXR renderer enabled');

// VR availability detection
let vrSupported = false;
async function checkVRSupport() {
  if (navigator.xr) {
    try {
      vrSupported = await navigator.xr.isSessionSupported('immersive-vr');
      console.log(`🥽 [VR] WebXR support: ${vrSupported ? '✅ Available' : '❌ Not available'}`);
      return vrSupported;
    } catch (err) {
      console.warn('⚠️ [VR] Error checking WebXR support:', err);
      return false;
    }
  } else {
    console.log('💡 [VR] WebXR API not available in this browser');
    return false;
  }
}
// Check VR support on initialization
checkVRSupport();

// VR Session Management
let vrInputProvider = null;
let currentVRSession = null;

/**
 * Start VR Session
 */
async function startVRSession() {
  if (!navigator.xr) {
    console.error('❌ [VR] WebXR not available');
    return false;
  }
  
  if (!vrSupported) {
    console.warn('⚠️ [VR] VR not supported on this device');
    return false;
  }
  
  try {
    // Request immersive VR session
    const session = await navigator.xr.requestSession('immersive-vr', {
      requiredFeatures: ['local-floor'], // Floor-level tracking
      optionalFeatures: ['hand-tracking'] // Optional hand tracking
    });
    
    currentVRSession = session;
    
    // Enable VR in renderer
    await renderer.xr.setSession(session);
    
    // Create and register VR input provider
    vrInputProvider = new VRInputProvider(session);
    if (vrInputProvider.enable()) {
      // Register with PlayerControls
      if (playerControls) {
        playerControls.registerInputProvider(vrInputProvider);
        await playerControls.enableVR(session);
        console.log('✅ [VR] VR session started and registered with PlayerControls');
      }
    }
    
    // Handle session end
    session.addEventListener('end', () => {
      endVRSession();
    });
    
    console.log('🥽 [VR] VR session started successfully');
    return true;
  } catch (err) {
    console.error('❌ [VR] Failed to start VR session:', err);
    return false;
  }
}

/**
 * End VR Session
 */
function endVRSession() {
  if (currentVRSession) {
    currentVRSession.end();
  }
  
  if (vrInputProvider) {
    vrInputProvider.disable();
    if (playerControls) {
      playerControls.disableVR();
    }
    vrInputProvider = null;
  }
  
  currentVRSession = null;
  console.log('🖥️ [VR] VR session ended, returned to desktop mode');
}

/**
 * Check if VR session is active
 */
function isVRSessionActive() {
  return currentVRSession !== null && renderer.xr.isPresenting;
}

// CRITICAL: Use PCF shadows (faster than PCFSoft) for better performance
// PCFSoft looks better but is slower - PCF is acceptable quality with better FPS
renderer.shadowMap.type = THREE.PCFShadowMap; // Changed from PCFSoftShadowMap for better performance
document.body.style.margin = "0";
document.body.appendChild(renderer.domElement);

