function getLevel2GalleryLayout() {
  const shelfStartZ = level2Config.origin.z - 18;
  const shelfSpacing = 7;
  const leverBaseZ = shelfStartZ + LEVEL2_TOTAL_SHELF_SEGMENTS * shelfSpacing + 2;
  const galleryStartZ = leverBaseZ + LEVEL2_WEAPON_GALLERY_CONFIG.startOffsetZ;
  const leverFinalZ = galleryStartZ + 4; // keep lever within the walkable corridor
  return { shelfStartZ, shelfSpacing, leverBaseZ, galleryStartZ, leverFinalZ };
}
