/**
 * Process weapon material - brightens dark colors for visibility
 * 
 * ⚠️ CRITICAL REMINDER FOR FUTURE DEVELOPERS (December 13, 2025):
 * - FBX weapon models often have VERY DARK materials (colors like 0x1a120e, 0x0c0c0c)
 * - These dark colors are INVISIBLE in first-person view
 * - ALWAYS brighten dark colors by 3x (brightness < 0.3) or 2x (brightness < 0.6)
 * - ALWAYS add emissive glow for very dark materials (brightness < 0.3)
 * - See WEAPON_RENDERING_RULES.md for complete implementation guide
 * 
 * @param {THREE.Material|THREE.Material[]} material - Material(s) to process
 * @returns {THREE.MeshStandardMaterial|THREE.MeshStandardMaterial[]} Processed material(s)
 */
function processWeaponMaterial(material) {
  const convert = (mat) => {
    if (!mat) {
      return new THREE.MeshStandardMaterial({
        color: 0x888888, // Default visible gray
        metalness: 0.35,
        roughness: 0.45,
        side: THREE.DoubleSide
      });
    }
    
    // CRITICAL: For FBX models, materials might not have proper color or might be wrong type
    // Always extract color safely, defaulting to visible gray if missing
    let originalColor = null;
    if (mat.color) {
      if (mat.color.isColor) {
        originalColor = mat.color.clone();
      } else if (typeof mat.color === 'number') {
        originalColor = new THREE.Color(mat.color);
      } else {
        originalColor = new THREE.Color(mat.color);
      }
    } else if (mat.emissive && mat.emissive.isColor) {
      // If no color but has emissive, use emissive as base
      originalColor = mat.emissive.clone();
    } else {
      // No color at all - use default visible gray
      originalColor = new THREE.Color(0x888888);
    }
    
    // Ensure we have a valid color
    if (!originalColor || !originalColor.isColor) {
      originalColor = new THREE.Color(0x888888);
    }
    
    // CRITICAL: Brighten dark colors for visibility in first-person view
    // Dark colors (like 0x1a120e, 0x0c0c0c) are too dark to see
    // Increase brightness by at least 2x for dark colors
    const brightness = originalColor.r + originalColor.g + originalColor.b;
    let finalColor = originalColor.clone();
    
    if (brightness < 0.3) {
      // Very dark color - brighten significantly
      finalColor.r = Math.min(1.0, originalColor.r * 3.0);
      finalColor.g = Math.min(1.0, originalColor.g * 3.0);
      finalColor.b = Math.min(1.0, originalColor.b * 3.0);
      // CRITICAL: Disabled debug logging for performance (was causing FPS drops in Level 2)
      // Only log when DEBUG_SETTINGS.logWeaponMaterials is true
      if (DEBUG_SETTINGS.logWeaponMaterials) {
        console.log("🔫 [MATERIAL] Brightened dark color:", {
          original: originalColor.getHexString(),
          brightened: finalColor.getHexString(),
          brightness: brightness.toFixed(3)
        });
      }
    } else if (brightness < 0.6) {
      // Moderately dark - brighten moderately
      finalColor.r = Math.min(1.0, originalColor.r * 2.0);
      finalColor.g = Math.min(1.0, originalColor.g * 2.0);
      finalColor.b = Math.min(1.0, originalColor.b * 2.0);
    }
    
    // Always create a new MeshStandardMaterial to ensure proper texture handling
    // CRITICAL: For FBX models, always use MeshStandardMaterial (not MeshPhongMaterial, etc.)
    const newMaterial = new THREE.MeshStandardMaterial({
      color: finalColor,
      map: mat.map || null,
      normalMap: mat.normalMap || null,
      // CRITICAL: Add slight emissive for dark materials to ensure visibility
      emissive: brightness < 0.3 ? finalColor.clone().multiplyScalar(0.1) : new THREE.Color(0x000000),
      emissiveIntensity: brightness < 0.3 ? 0.2 : 0,
      metalness: 0.35,
      roughness: 0.45,
      side: THREE.DoubleSide, // CRITICAL: Ensure double-sided for visibility
      opacity: mat.opacity !== undefined && mat.opacity > 0.1 ? mat.opacity : 1.0,
      transparent: mat.transparent !== undefined ? mat.transparent : false
    });
    
    // CRITICAL: If texture exists, ensure it's properly assigned and updated
    if (mat.map) {
      newMaterial.map = mat.map; // Use original texture (don't clone, might cause issues)
      // Ensure texture is ready
      if (newMaterial.map.image && newMaterial.map.image.complete) {
        newMaterial.map.needsUpdate = true;
      }
    }
    
    // CRITICAL: Mark material as needing update to ensure textures render
    newMaterial.needsUpdate = true;
    
    // CRITICAL: Ensure material is visible (not transparent or invisible)
    if (newMaterial.opacity < 0.1) {
      newMaterial.opacity = 1.0;
      newMaterial.transparent = false;
    }
    
    // CRITICAL: Disabled debug logging for performance (was causing FPS drops in Level 2)
    // Only log when DEBUG_SETTINGS.logWeaponMaterials is true
    if (DEBUG_SETTINGS.logWeaponMaterials) {
      console.log("🔫 [MATERIAL] Processing weapon material:", {
        originalType: mat.type || 'unknown',
        hasMap: !!newMaterial.map,
        mapLoaded: newMaterial.map ? (newMaterial.map.image ? newMaterial.map.image.complete : false) : false,
        originalColor: originalColor.getHexString(),
        finalColor: finalColor.getHexString(),
        brightness: brightness.toFixed(3),
        hasEmissive: brightness < 0.3
      });
    }
    
    return newMaterial;
  };

  if (Array.isArray(material)) {
    return material.map(convert);
  }
  return convert(material);
}
