let level4HitIndicator = null;
let level4HitIndicatorTimer = 0;

function createLevel4HitIndicator() {
  if (level4HitIndicator) return level4HitIndicator;
  level4HitIndicator = document.createElement("div");
  level4HitIndicator.id = "level4HitIndicator";
  Object.assign(level4HitIndicator.style, {
    position: "fixed",
    top: "50%",
    left: "50%",
    transform: "translate(-50%, -50%)",
    width: "100vw",
    height: "100vh",
    pointerEvents: "none",
    zIndex: "9999",
    opacity: "0",
    transition: "opacity 0.1s ease-out",
    background: "radial-gradient(circle, rgba(255, 224, 102, 0.5) 0%, rgba(255, 165, 0, 0.3) 50%, transparent 100%)", // Cheese-themed yellow/orange
    display: "none"
  });
  document.body.appendChild(level4HitIndicator);
  return level4HitIndicator;
}

function showLevel4HitIndicator() {
  // Use GUI System if available
  if (guiSystem && typeof guiSystem.showLevel4HitIndicator === 'function') {
    guiSystem.showLevel4HitIndicator();
    return;
  }
  
  // Legacy fallback
  const indicator = createLevel4HitIndicator();
  indicator.style.display = "block";
  indicator.style.opacity = "0.7"; // Slightly more visible for cheese theme
  level4HitIndicatorTimer = LEVEL4_HIT_INDICATOR_DURATION;
  
  // Auto-fade out after duration
  setTimeout(() => {
    if (indicator && document.body.contains(indicator)) {
      indicator.style.opacity = "0";
      setTimeout(() => {
        if (indicator && document.body.contains(indicator)) {
          indicator.style.display = "none";
        }
      }, 100);
    }
  }, LEVEL4_HIT_INDICATOR_DURATION * 1000);
}

function updateLevel4HitIndicator(delta) {
  // Use GUI System if available (called in guiSystem.update() already, but allow direct calls)
  if (guiSystem && typeof guiSystem.updateLevel4HitIndicator === 'function') {
    guiSystem.updateLevel4HitIndicator(delta);
    return;
  }
  
  // Legacy fallback
  if (level4HitIndicatorTimer > 0) {
    level4HitIndicatorTimer -= delta;
    if (level4HitIndicatorTimer <= 0 && level4HitIndicator) {
      level4HitIndicator.style.opacity = "0";
      setTimeout(() => {
        if (level4HitIndicator && document.body.contains(level4HitIndicator)) {
          level4HitIndicator.style.display = "none";
        }
      }, 100);
    }
  }
}

// Level 4 Weapon Viewmodel System
async function loadLevel4WeaponViewmodel(weaponPath = null, slotNumber = null) {
  // Use provided path or default to current slot's weapon
  const targetPath = weaponPath || (slotNumber && LEVEL4_WEAPON_SLOTS[slotNumber] ? LEVEL4_WEAPON_SLOTS[slotNumber].path : LEVEL4_WEAPON_PATH);
  const targetSlot = slotNumber || level4State.currentWeaponSlot;
  
  // Check if this weapon slot is already cached AND is the current active weapon
  // If switching to a different slot, we need to load fresh (don't use cache)
  if (level4State.weaponSlots[targetSlot] && level4State.currentWeaponSlot === targetSlot) {
    const cachedWeapon = level4State.weaponSlots[targetSlot];
    if (camera.children.includes(cachedWeapon)) {
      // Weapon exists and is attached - ensure visibility and reapply transforms
      cachedWeapon.visible = true;
      cachedWeapon.traverse((child) => {
        if (child.isMesh) {
          child.visible = true;
        }
      });
      // Reapply transforms to ensure they're correct (in case they were changed)
      const weaponInfo = LEVEL4_WEAPON_SLOTS[targetSlot];
      const weaponType = weaponInfo?.type || "pistol";
      const transform = LEVEL4_WEAPON_TRANSFORMS[weaponType] || LEVEL4_WEAPON_TRANSFORMS.pistol;
      cachedWeapon.rotation.set(
        transform.rotationX || -0.15,
        transform.rotationY || Math.PI / 2,
        transform.rotationZ || 0.0
      );
      cachedWeapon.position.set(0.0, -0.4, -0.5);
      cachedWeapon.updateMatrixWorld(true);
      console.log("🔫 [LEVEL 4] Weapon viewmodel already loaded (slot " + targetSlot + "), ensuring visibility and transforms");
      return cachedWeapon;
    } else {
      // Weapon exists but not attached - reattach it and reapply transforms
      console.log("🔫 [LEVEL 4] Weapon viewmodel exists but not attached, reattaching...");
      camera.add(cachedWeapon);
      cachedWeapon.visible = true;
      // Reapply transforms
      const weaponInfo = LEVEL4_WEAPON_SLOTS[targetSlot];
      const weaponType = weaponInfo?.type || "pistol";
      const transform = LEVEL4_WEAPON_TRANSFORMS[weaponType] || LEVEL4_WEAPON_TRANSFORMS.pistol;
      cachedWeapon.rotation.set(
        transform.rotationX || -0.15,
        transform.rotationY || Math.PI / 2,
        transform.rotationZ || 0.0
      );
      cachedWeapon.position.set(0.0, -0.4, -0.5);
      cachedWeapon.updateMatrixWorld(true);
      return cachedWeapon;
    }
  }
  
  // Remove current weapon if switching slots
  if (level4State.weaponViewmodel && level4State.currentWeaponSlot !== targetSlot) {
    removeLevel4WeaponViewmodel();
  }
  
  try {
    console.log("🔫 [LEVEL 4] Loading weapon viewmodel (Slot " + targetSlot + "):", targetPath);
    const weaponData = await loadModel(targetPath);
    const weaponModel = weaponData.scene.clone(true);
    
    // Ensure weapon model is visible
    weaponModel.visible = true;
    
    // Process weapon materials using the same function as Level 2
    let totalVertices = 0;
    weaponModel.traverse((child) => {
      if (child.isMesh) {
        child.visible = true; // Explicitly set visible
        child.castShadow = false;
        child.receiveShadow = false;
        child.frustumCulled = false;
        child.renderOrder = 999; // Render on top of everything
        
        // Log mesh geometry info
        if (child.geometry) {
          const vertices = child.geometry.attributes?.position?.count || 0;
          totalVertices += vertices;
          const bounds = new THREE.Box3().setFromObject(child);
          const size = bounds.getSize(new THREE.Vector3());
          console.log("🔫 [LEVEL 4] Weapon mesh found:", {
            name: child.name,
            vertices: vertices,
            hasGeometry: !!child.geometry,
            geometryType: child.geometry.type,
            bounds: { min: bounds.min, max: bounds.max },
            size: { x: size.x, y: size.y, z: size.z }
          });
          
          // If mesh has no vertices or is extremely small, log warning
          if (vertices === 0) {
            console.warn("⚠️ [LEVEL 4] Weapon mesh has NO VERTICES:", child.name);
          }
          if (size.x < 0.001 && size.y < 0.001 && size.z < 0.001) {
            console.warn("⚠️ [LEVEL 4] Weapon mesh is extremely small:", child.name, size);
          }
        } else {
          console.warn("⚠️ [LEVEL 4] Weapon mesh has NO GEOMETRY:", child.name);
        }
        
        // Use the same material processing as Level 2
        child.material = processWeaponMaterial(child.material);
      }
    });
    
    console.log("🔫 [LEVEL 4] Weapon model processed:", {
      totalVertices: totalVertices,
      children: weaponModel.children.length
    });
    
    // Calculate proper scale based on weapon bounds (like Level 2 does)
    const weaponBounds = new THREE.Box3().setFromObject(weaponModel);
    const weaponSize = weaponBounds.getSize(new THREE.Vector3());
    const maxDimension = Math.max(weaponSize.x, weaponSize.y, weaponSize.z);
    console.log("🔫 [LEVEL 4] Weapon model bounds:", {
      size: { x: weaponSize.x, y: weaponSize.y, z: weaponSize.z },
      maxDimension: maxDimension,
      center: weaponBounds.getCenter(new THREE.Vector3())
    });
    
    // Get weapon type and apply appropriate transforms
    const weaponInfo = LEVEL4_WEAPON_SLOTS[targetSlot];
    const weaponType = weaponInfo?.type || "pistol";
    const transform = LEVEL4_WEAPON_TRANSFORMS[weaponType] || LEVEL4_WEAPON_TRANSFORMS.pistol;
    
    // Scale weapon to reasonable size (use transform target size)
    const targetSize = transform.targetSize || 0.3;
    const scaleFactor = maxDimension > 0 ? targetSize / maxDimension : 0.2;
    const finalScale = scaleFactor;
    
    // Position weapon in first-person view (center-bottom, pointing at crosshair)
    // Position: x (right), y (down), z (forward from camera - negative is closer)
    // Z should be negative to be in front of camera, but not too close (camera near plane is usually 0.1)
    weaponModel.position.set(0.0, -0.4, -0.5); // Center-bottom position, pointing forward
    // Rotate weapon to point at crosshair (use transform-specific rotation)
    weaponModel.rotation.set(
      transform.rotationX || -0.15,
      transform.rotationY || Math.PI / 2,
      transform.rotationZ || 0.0
    );
    weaponModel.scale.set(finalScale, finalScale, finalScale);
    
    console.log("🔫 [LEVEL 4] Weapon scaled:", {
      originalMaxDimension: maxDimension,
      targetSize: targetSize,
      scaleFactor: scaleFactor,
      finalScale: finalScale
    });
    
    // Add to camera (first-person view)
    camera.add(weaponModel);
    level4State.weaponViewmodel = weaponModel;
    level4State.currentWeaponSlot = targetSlot;
    
    // Cache the weapon model for this slot
    level4State.weaponSlots[targetSlot] = weaponModel;
    
    // Count meshes for debugging
    let meshCount = 0;
    weaponModel.traverse((child) => {
      if (child.isMesh) meshCount++;
    });
    
    const weaponName = LEVEL4_WEAPON_SLOTS[targetSlot]?.name || "Unknown";
    console.log("✅ [LEVEL 4] Weapon viewmodel loaded and attached to camera", {
      slot: targetSlot,
      name: weaponName,
      visible: weaponModel.visible,
      inCamera: camera.children.includes(weaponModel),
      position: { x: weaponModel.position.x, y: weaponModel.position.y, z: weaponModel.position.z },
      scale: { x: weaponModel.scale.x, y: weaponModel.scale.y, z: weaponModel.scale.z },
      meshCount: meshCount,
      children: weaponModel.children.length,
      totalVertices: totalVertices,
      cameraChildren: camera.children.length
    });
    
    // Update HUD to show current weapon
    updateLevel4WeaponHUD();
    
    // Update matrix to ensure proper rendering (like Level 2 does)
    weaponModel.updateMatrixWorld(true);
    return weaponModel;
  } catch (error) {
    console.error("❌ [LEVEL 4] Failed to load weapon viewmodel:", error);
    return null;
  }
}

function removeLevel4WeaponViewmodel() {
  if (level4State.weaponViewmodel && camera.children.includes(level4State.weaponViewmodel)) {
    camera.remove(level4State.weaponViewmodel);
    // Don't null the weaponViewmodel if it's cached - just remove from camera
    // level4State.weaponViewmodel = null;
  }
}

// Level 4 Weapon Switching System
async function switchLevel4WeaponSlot(slotNumber) {
  // Only allow switching in Level 4, Step 1 (cheese) or Step 2 (monster) active, and first-person view
  if (currentLevel !== LEVEL_IDS.LEVEL4 || (!level4RiddleState.step1Active && !level4RiddleState.step2Active) || !isFirstPerson()) {
    return;
  }
  
  // Validate slot number
  if (!LEVEL4_WEAPON_SLOTS[slotNumber]) {
    console.warn("⚠️ [LEVEL 4] Invalid weapon slot:", slotNumber);
    return;
  }
  
  // Don't switch if already on this slot
  if (level4State.currentWeaponSlot === slotNumber && level4State.weaponViewmodel) {
    console.log("🔫 [LEVEL 4] Already using weapon slot", slotNumber);
    return;
  }
  
  console.log("🔄 [LEVEL 4] Switching to weapon slot", slotNumber, LEVEL4_WEAPON_SLOTS[slotNumber].name);
  
  // Hide current weapon
  if (level4State.weaponViewmodel) {
    level4State.weaponViewmodel.visible = false;
  }
  
  // Load new weapon (will use cache if available)
  try {
    await loadLevel4WeaponViewmodel(null, slotNumber);
    console.log("✅ [LEVEL 4] Weapon switched to slot", slotNumber);
  } catch (error) {
    console.error("❌ [LEVEL 4] Failed to switch weapon:", error);
    // Restore previous weapon visibility if switch failed
    if (level4State.weaponViewmodel) {
      level4State.weaponViewmodel.visible = true;
    }
  }
}

function updateLevel4WeaponHUD() {
  // Update weapon slot display in HUD
  if (!level4ProgressHUD || (!level4RiddleState.step1Active && !level4RiddleState.step2Active)) return;
  
  // CRITICAL: Use weapon system's current slot if available, otherwise fallback to legacy state
  const currentSlot = weaponSystem ? weaponSystem.getCurrentSlot() : (level4State.currentWeaponSlot || 1);
  const weaponInfo = LEVEL4_WEAPON_SLOTS[currentSlot];
  const weaponName = weaponInfo ? weaponInfo.name : "Unknown";
  
  // CRITICAL: Sync legacy state with weapon system state
  if (level4State && weaponSystem) {
    level4State.currentWeaponSlot = currentSlot;
  }
  
  // Weapon slot indicator will be added to the HUD in updateLevel4ProgressHUD
  // This function is called after weapon switch to trigger HUD update
  updateLevel4ProgressHUD();
}

/**
 * Update weapon animation (bobbing and recoil)
 * 
 * ⚠️ CRITICAL REMINDER FOR FUTURE DEVELOPERS (December 13, 2025):
 * - ALWAYS check for and remove duplicate weapons before animating
 * - ALWAYS use weaponSystem.weaponViewmodel (not legacy level4State.weaponViewmodel)
 * - NEVER reset weapon position during bobbing (use relative offsets from base position)
 * - Recoil amounts: position 0.03/0.015, rotation 0.08/0.02 (reduced from original for smooth feel)
 * - See WEAPON_RENDERING_RULES.md for complete animation guide
 * 
 * @param {number} delta - Time delta in seconds
 * @param {boolean} isMoving - Whether player is currently moving
 */
function updateLevel4WeaponAnimation(delta, isMoving) {
  // CRITICAL: Use weapon system's weapon viewmodel instead of legacy level4State.weaponViewmodel
  // CRITICAL: Also ensure legacy weapon is removed if it exists (prevents double rendering)
  if (level4State.weaponViewmodel && camera.children.includes(level4State.weaponViewmodel)) {
    console.warn("⚠️ [WEAPON] Legacy weapon found in camera, removing to prevent double rendering");
    camera.remove(level4State.weaponViewmodel);
    level4State.weaponViewmodel = null;
  }
  
  const weapon = weaponSystem && weaponSystem.weaponViewmodel ? weaponSystem.weaponViewmodel : null;
  if (!weapon) return;
  
  // CRITICAL: Ensure only ONE weapon is in the camera (prevent duplicates)
  const weaponChildren = camera.children.filter(child => {
    if (child === weapon) return false; // Don't count the current weapon
    // Check if child looks like a weapon
    let hasWeaponMeshes = false;
    child.traverse((descendant) => {
      if (descendant.isMesh) {
        hasWeaponMeshes = true;
      }
    });
    return hasWeaponMeshes && !child.isLight && !child.isCamera;
  });
  
  if (weaponChildren.length > 0) {
    console.warn(`⚠️ [WEAPON] Found ${weaponChildren.length} duplicate weapon(s) in camera, removing...`);
    weaponChildren.forEach(duplicateWeapon => {
      camera.remove(duplicateWeapon);
      console.log("🔫 [WEAPON] Removed duplicate weapon from camera");
    });
  }
  
  // Weapon bobbing (when player is moving)
  const baseX = 0.0; // Base X position (center)
  const baseY = -0.4; // Base Y position (down)
  const baseZ = -0.5; // Base Z position (forward from camera)
  const baseRotationX = -0.15; // Base rotation X (downward tilt to align with crosshair)
  const baseRotationY = Math.PI / 2; // Base rotation Y (90 degrees left - rotated to match 3D environment)
  const baseRotationZ = 0.0; // Base rotation Z (no roll)
  
  if (isMoving) {
    if (!level4State.weaponBobPhase) level4State.weaponBobPhase = 0;
    level4State.weaponBobPhase += delta * 8; // Bob speed
    const bobAmount = 0.015; // Small bob amount
    const bobY = Math.sin(level4State.weaponBobPhase) * bobAmount;
    const bobX = Math.cos(level4State.weaponBobPhase * 0.5) * bobAmount * 0.5;
    const bobZ = Math.sin(level4State.weaponBobPhase * 0.7) * bobAmount * 0.3;
    weapon.position.y = baseY + bobY;
    weapon.position.x = baseX + bobX;
    weapon.position.z = baseZ + bobZ;
    
    // Slight rotation bobbing when moving
    const rotBob = Math.sin(level4State.weaponBobPhase * 0.8) * 0.02;
    weapon.rotation.z = baseRotationZ + rotBob;
  } else {
    // Smooth return to rest position
    weapon.position.y = THREE.MathUtils.lerp(weapon.position.y, baseY, delta * 5);
    weapon.position.x = THREE.MathUtils.lerp(weapon.position.x, baseX, delta * 5);
    weapon.position.z = THREE.MathUtils.lerp(weapon.position.z, baseZ, delta * 5);
    weapon.rotation.z = THREE.MathUtils.lerp(weapon.rotation.z, baseRotationZ, delta * 5);
  }
  
  // CRITICAL: Use weapon system's recoil offset if available, otherwise use legacy level4State
  const recoilOffset = (weaponSystem && weaponSystem.weaponRecoilOffset !== undefined) ? weaponSystem.weaponRecoilOffset : (level4State.weaponRecoilOffset || 0);
  
  // Recoil animation (decay over time) - REDUCED RECOIL AMOUNT
  if (recoilOffset > 0) {
    // Apply recoil (push back and up) - REDUCED from 0.08/0.04 to 0.03/0.015 for less movement
    const recoilBack = recoilOffset * 0.03; // Reduced from 0.08
    const recoilUp = recoilOffset * 0.015; // Reduced from 0.04
    weapon.position.z = baseZ - recoilBack;
    weapon.position.y = baseY + recoilUp;
    
    // Rotation for recoil effect (kick up) - REDUCED from 0.2/0.05 to 0.08/0.02 for less rotation
    weapon.rotation.x = baseRotationX - recoilOffset * 0.08; // Reduced from 0.2
    weapon.rotation.y = baseRotationY + recoilOffset * 0.02; // Reduced from 0.05
  } else {
    // Smooth return to rest rotation
    weapon.rotation.x = THREE.MathUtils.lerp(weapon.rotation.x, baseRotationX, delta * 5);
    weapon.rotation.y = THREE.MathUtils.lerp(weapon.rotation.y, baseRotationY, delta * 5);
    weapon.position.z = THREE.MathUtils.lerp(weapon.position.z, baseZ, delta * 5);
  }
}

// Create a purple SF13 bullet projectile (with glowing effect)
function createLevel4SF13Bullet(startPos, direction, targetPos) {
  // Create bullet geometry (small sphere with purple glow)
  const bulletGeometry = new THREE.SphereGeometry(LEVEL4_BULLET_SIZE, 8, 8);
  
  // Purple color from index.html: #7c3aed
  const purpleColor = new THREE.Color(0x7c3aed);
  
  // Create purple glowing bullet material
  const bulletMaterial = new THREE.MeshStandardMaterial({
    color: purpleColor,
    emissive: purpleColor, // Purple glow
    emissiveIntensity: 1.2, // Stronger glow than normal bullets
    metalness: 0.5,
    roughness: 0.3
  });
  
  const bulletMesh = new THREE.Mesh(bulletGeometry, bulletMaterial);
  bulletMesh.position.copy(startPos);
  
  // Add to scene
  scene.add(bulletMesh);
  
  // Calculate direction and distance
  const directionVec = new THREE.Vector3().subVectors(targetPos, startPos);
  const distance = directionVec.length();
  directionVec.normalize();
  
  // Create bullet object
  const bullet = {
    mesh: bulletMesh,
    material: bulletMaterial,
    direction: directionVec,
    speed: LEVEL4_BULLET_SPEED,
    distance: distance,
    traveled: 0,
    lifetime: 0,
    maxLifetime: LEVEL4_BULLET_LIFETIME,
    targetPos: targetPos.clone(),
    hit: false,
    isPurple: true // Mark as purple bullet
  };
  
  level4Bullets.push(bullet);
  return bullet;
}

// Create a cheese bullet projectile
function createLevel4CheeseBullet(startPos, direction, targetPos) {
  // Create bullet geometry (small sphere with cheese texture)
  const bulletGeometry = new THREE.SphereGeometry(LEVEL4_BULLET_SIZE, 8, 8);
  
  // Try to load cheese-bullet-small.png first, fallback to yellow-cheese.png
  const primaryTexturePath = "/textures/blocks/cheese-bullet-small.png";
  const fallbackTexturePath = "/textures/blocks/yellow-cheese.png";
  
  // Check if primary texture is already in cache and loaded
  let cheeseTexture = null;
  if (textureCache.has(primaryTexturePath)) {
    const cached = textureCache.get(primaryTexturePath);
    if (cached && cached.image && cached.image.complete && cached.image.width > 0) {
      cheeseTexture = cached;
      console.log("✅ [LEVEL 4] Using cached cheese bullet texture");
    }
  }
  
  // Load fallback texture (yellow-cheese.png) - always available
  const fallbackTexture = loadTexture(fallbackTexturePath);
  
  // Start with fallback, will update to primary when it loads
  const bulletMaterial = new THREE.MeshStandardMaterial({
    map: cheeseTexture || fallbackTexture, // Use primary if already loaded, otherwise fallback
    emissive: new THREE.Color(0xffe066), // Golden glow
    emissiveIntensity: 0.8,
    metalness: 0.3,
    roughness: 0.7
  });
  
  // If primary texture not in cache, load it asynchronously
  if (!cheeseTexture) {
    console.log("📦 [LEVEL 4] Loading cheese bullet texture:", primaryTexturePath);
    const textureLoader = new THREE.TextureLoader();
    textureLoader.load(
      primaryTexturePath,
      (texture) => {
        // Successfully loaded primary texture - update material
        if (texture && texture.image) {
          // Ensure texture is ready
          texture.needsUpdate = true;
          texture.flipY = false; // Ensure proper orientation
          
          // Update material with new texture
          bulletMaterial.map = texture;
          bulletMaterial.needsUpdate = true;
          
          // Force texture to update
          if (bulletMaterial.map) {
            bulletMaterial.map.needsUpdate = true;
          }
          
          // Update the mesh to reflect the change (use closure to access bulletMesh)
          // Find the bullet in the array and update its material
          const bullet = level4Bullets.find(b => b.material === bulletMaterial);
          if (bullet && bullet.mesh) {
            bullet.mesh.material = bulletMaterial;
            bullet.mesh.material.needsUpdate = true;
          }
          
          // Cache it for future bullets
          textureCache.set(primaryTexturePath, texture);
          
          console.log("✅ [LEVEL 4] Cheese bullet texture loaded and applied:", {
            path: primaryTexturePath,
            width: texture.image.width,
            height: texture.image.height,
            complete: texture.image.complete,
            materialHasMap: !!bulletMaterial.map,
            meshMaterialUpdated: bulletMesh ? bulletMesh.material === bulletMaterial : false
          });
        } else {
          console.warn("⚠️ [LEVEL 4] Texture loaded but has no image, using fallback");
        }
      },
      undefined,
      (error) => {
        // Failed to load primary - keep using fallback
        console.warn("⚠️ [LEVEL 4] Cheese bullet texture not found, using fallback:", {
          primaryPath: primaryTexturePath,
          fallbackPath: fallbackTexturePath,
          error: error
        });
      }
    );
  } else {
    // Texture already in cache - ensure material uses it
    bulletMaterial.map = cheeseTexture;
    bulletMaterial.needsUpdate = true;
    console.log("✅ [LEVEL 4] Using cached cheese bullet texture");
  }
  
  const bulletMesh = new THREE.Mesh(bulletGeometry, bulletMaterial);
  bulletMesh.position.copy(startPos);
  
  // Add to scene
  scene.add(bulletMesh);
  
  // Store reference to mesh in material callback scope (for async texture loading)
  const meshRef = bulletMesh;
  
  // If texture is loading asynchronously, update the callback to use meshRef
  if (!cheeseTexture) {
    // The texture loader callback was set up earlier, but we need to ensure it can access the mesh
    // We'll update the callback to use meshRef instead of bulletMesh
    // (The callback closure will capture meshRef)
  }
  
  // Calculate direction and distance
  const directionVec = new THREE.Vector3().subVectors(targetPos, startPos);
  const distance = directionVec.length();
  directionVec.normalize();
  
  // Create bullet object
  const bullet = {
    mesh: bulletMesh,
    material: bulletMaterial, // Store material reference for texture updates
    direction: directionVec,
    speed: LEVEL4_BULLET_SPEED,
    distance: distance,
    traveled: 0,
    lifetime: 0,
    maxLifetime: LEVEL4_BULLET_LIFETIME,
    targetPos: targetPos.clone(),
    hit: false,
    isPurple: false // Normal yellow cheese bullet
  };
  
  level4Bullets.push(bullet);
  return bullet;
}

// Update all active cheese bullets
function updateLevel4Bullets(delta) {
  // Only update bullets if in Level 4
  if (currentLevel !== LEVEL_IDS.LEVEL4) {
    // Clean up all bullets if not in Level 4
    level4Bullets.forEach(bullet => {
      if (bullet.mesh && bullet.mesh.parent) {
        scene.remove(bullet.mesh);
        bullet.mesh.geometry.dispose();
        bullet.mesh.material.dispose();
      }
    });
    level4Bullets.length = 0;
    return;
  }
  
  // CRITICAL: Allow bullets to continue updating even after step1Active/step2Active becomes false
  // This ensures bullets complete their flight path when portal activates (no "frozen bullets" bug)
  // Bullets will naturally expire based on their lifetime/maxDistance, so no cleanup needed here
  // Only clean up if we're not in Level 4 at all (handled above)
  
  // Update each bullet
  for (let i = level4Bullets.length - 1; i >= 0; i--) {
    const bullet = level4Bullets[i];
    
    // Update lifetime
    bullet.lifetime += delta;
    
    // Check if bullet should be removed (lifetime exceeded or hit)
    if (bullet.lifetime >= bullet.maxLifetime || bullet.hit) {
      // Remove bullet from scene
      if (bullet.mesh && bullet.mesh.parent) {
        scene.remove(bullet.mesh);
        bullet.mesh.geometry.dispose();
        bullet.mesh.material.dispose();
      }
      level4Bullets.splice(i, 1);
      continue;
    }
    
    // Move bullet forward
    const moveDistance = bullet.speed * delta;
    bullet.traveled += moveDistance;
    
    // Update position
    bullet.mesh.position.addScaledVector(bullet.direction, moveDistance);
    
    // Rotate bullet for visual effect
    bullet.mesh.rotation.x += delta * 10;
    bullet.mesh.rotation.y += delta * 8;
    
    // Check if bullet reached target or max distance
    if (bullet.traveled >= bullet.distance) {
      bullet.hit = true;
    }
    
    // Check collision with cheeses or monsters (visual confirmation only - instant hit already handled)
    // This is mainly for visual feedback when bullet reaches target
    if (!bullet.hit && bullet.traveled >= bullet.distance * 0.95) {
      // Bullet reached target position - mark as hit for visual effect
      bullet.hit = true;
    }
    
    // In Step 2: Check collision with monsters (visual confirmation only)
    if (level4RiddleState.step2Active && !bullet.hit) {
      level4State.monsters.forEach((monster) => {
        if (!monster || !monster.mesh || !monster.mesh.visible || monster.defeated) return;
        
        // Simple distance check for visual bullet collision
        const distanceToMonster = bullet.mesh.position.distanceTo(monster.mesh.position);
        if (distanceToMonster < 2.0) { // Bullet is close to monster
          bullet.hit = true;
        }
      });
    }
  }
}

// Level 4 Heat System Functions (like Space Invaders)
function addLevel4Heat(amount) {
  level4State.weaponHeat = Math.min(level4State.weaponHeat + amount, level4State.maxHeat);
  
  // Check for overheating
  if (level4State.weaponHeat >= level4State.maxHeat && !level4State.isOverheated) {
    overheatLevel4Weapon();
  }
  
  // Critical heat warning (at 80% heat)
  if (level4State.weaponHeat >= 120 && level4State.weaponHeat < level4State.maxHeat) {
    console.log('⚠️ [LEVEL 4] WARNING: Weapon heat critical! Consider cooling down...');
  }
}

function overheatLevel4Weapon() {
  level4State.isOverheated = true;
  level4State.lastOverheatTime = Date.now();
  console.log('🔥 [LEVEL 4] WEAPON OVERHEATED! Cooling down...');
}

function updateLevel4Heat(delta) {
  if (level4State.isOverheated) {
    // Check if cooldown period is over
    if (Date.now() - level4State.lastOverheatTime > level4State.overheatCooldown) {
      level4State.isOverheated = false;
      level4State.weaponHeat = 0;
      console.log('❄️ [LEVEL 4] Weapon cooled down! Ready to fire again!');
    }
  } else if (level4State.weaponHeat > 0) {
    // Natural heat decay when not shooting
    // heatDecayRate is per frame, so apply directly (delta is in seconds, but we want per-frame decay)
    // At 60 FPS, delta ≈ 0.0167 seconds per frame
    // So we apply heatDecayRate directly (it's already per-frame)
    level4State.weaponHeat = Math.max(0, level4State.weaponHeat - level4State.heatDecayRate);
  }
}

// Level 4 Shooting System
function handleLevel4Shooting() {
  // Only allow shooting in Level 4, Step 1 (cheese) or Step 2 (monster) active, and first-person view
  if (currentLevel !== LEVEL_IDS.LEVEL4) {
    if (Math.random() < 0.01) console.log("🔫 [LEVEL 4] Shooting blocked: wrong level", currentLevel);
    return;
  }
  if (!level4RiddleState.step1Active && !level4RiddleState.step2Active) {
    if (Math.random() < 0.01) console.log("🔫 [LEVEL 4] Shooting blocked: step not active", { step1: level4RiddleState.step1Active, step2: level4RiddleState.step2Active });
    return;
  }
  if (!isFirstPerson()) {
    if (Math.random() < 0.01) console.log("🔫 [LEVEL 4] Shooting blocked: not first person", { cameraMode: cameraMode });
    return;
  }
  
  // Check for overheating FIRST (before any shooting logic)
  if (level4State.isOverheated) {
    console.log('🚫 [LEVEL 4] Cannot shoot - weapon is overheated!');
    return; // Don't allow shooting when overheated
  }
  
  // Check if SF13 (slot 2) - triple shot mode
  const isSF13 = level4State.currentWeaponSlot === 2;
  
  if (isSF13) {
    // SF13: Start triple-shot burst
    if (!level4State.tripleShotActive) {
      // Start new triple-shot burst
      level4State.tripleShotActive = true;
      level4State.tripleShotBulletsRemaining = 3; // 3 bullets in burst
      level4State.tripleShotNextBulletTime = performance.now() / 1000; // Start immediately
      
      // Add heat for triple shot (3x normal heat)
      addLevel4Heat(level4State.heatPerTripleShot);
      
      // Fire first bullet immediately
      fireLevel4SingleShot(true); // true = purple bullet
      
      // Play SF13 sound (will play 3 times total)
      if (level4SF13ShootAudioReady && level4SF13ShootSound) {
        if (level4SF13ShootSound.isPlaying) {
          level4SF13ShootSound.stop();
        }
        level4SF13ShootSound.play();
      }
      
      // Update cooldown (longer cooldown for triple shot)
      level4State.lastShotTime = performance.now() / 1000;
      level4State.shotCooldown = 0.4; // 400ms cooldown between bursts
    }
    return; // Triple shot system will handle the rest
  } else {
    // Normal weapon (slot 1): Single shot
    // Check cooldown
    const currentTime = performance.now() / 1000; // Convert to seconds
    if (currentTime - level4State.lastShotTime < level4State.shotCooldown) {
      return; // Still on cooldown
    }
    
    // Fire single shot
    fireLevel4SingleShot(false); // false = yellow bullet
    
    // Add heat for single shot
    addLevel4Heat(level4State.heatPerShot);
    
    // Play shooting sound (Space Invaders normal_shoot.wav) for weapon 1
    if (level4ShootAudioReady && level4ShootSound) {
      // Ensure audio context is resumed
      resumeAudioContextIfNeeded();
      // Stop any currently playing sound and restart it (for rapid firing)
      if (level4ShootSound.isPlaying) {
        level4ShootSound.stop();
      }
      level4ShootSound.play();
      console.log("🔫 [LEVEL 4] Weapon 1 shot sound played");
    } else {
      console.warn("⚠️ [LEVEL 4] Weapon 1 sound not ready:", { level4ShootAudioReady, hasSound: !!level4ShootSound });
    }
    
    // Update cooldown
    level4State.lastShotTime = currentTime;
    level4State.shotCooldown = 0.2; // 200ms between shots
  }
}

// Fire a single shot (used by both normal and triple-shot systems)
function fireLevel4SingleShot(isPurple = false) {
  
  // Perform raycast from camera center (crosshair position)
  const raycaster = new THREE.Raycaster();
  raycaster.setFromCamera(new THREE.Vector2(0, 0), camera); // Center of screen
  raycaster.far = LEVEL4_SHOOT_RANGE;
  
  // Calculate bullet start position (from gun/weapon position)
  // Weapon is attached to camera at position (0.0, -0.4, -0.5) in camera space
  // Convert camera-relative offset to world space
  const gunOffset = new THREE.Vector3(0.0, -0.4, -0.5);
  const bulletStartPos = new THREE.Vector3();
  camera.getWorldPosition(bulletStartPos);
  
  // Apply camera rotation to offset to get world-space position
  const forward = new THREE.Vector3(0, 0, -1).applyQuaternion(camera.quaternion);
  const right = new THREE.Vector3(1, 0, 0).applyQuaternion(camera.quaternion);
  const up = new THREE.Vector3(0, 1, 0).applyQuaternion(camera.quaternion);
  
  bulletStartPos.addScaledVector(right, gunOffset.x);
  bulletStartPos.addScaledVector(up, gunOffset.y);
  bulletStartPos.addScaledVector(forward, -gunOffset.z); // Negative because gun is in front
  
  // Calculate target position (where raycast hits or max range)
  let targetPos = new THREE.Vector3();
  const rayDirection = raycaster.ray.direction.clone(); // Get ray direction from raycaster
  targetPos.copy(bulletStartPos).addScaledVector(rayDirection, LEVEL4_SHOOT_RANGE);
  
  // Check for hits - prioritize based on active step
  let hitCheese = null;
  let hitMonster = null;
  let hitDistance = Infinity;
  let hitIndex = -1;
  let monsterHitIndex = -1;
  
  // Step 2 (monsters) takes priority over Step 1 (cheese) - check monsters first
  if (level4RiddleState.step2Active) {
    // Debug: Log raycast setup
    const cameraPos = camera.position.clone();
    const rayDir = raycaster.ray.direction.clone();
    
    level4State.monsters.forEach((monster, index) => {
      if (!monster || !monster.mesh || !monster.mesh.visible || monster.defeated) return;
      
      // Get monster world position
      const monsterWorldPos = new THREE.Vector3();
      monster.mesh.getWorldPosition(monsterWorldPos);
      
      // Calculate distance from camera to monster
      const distToMonster = cameraPos.distanceTo(monsterWorldPos);
      
      // Raycast against monster mesh (recursive=true to check all nested meshes in GLTF)
      const intersects = raycaster.intersectObject(monster.mesh, true);
      
      // Debug: Log raycast results occasionally
      if (Math.random() < 0.05 && intersects.length === 0) {
        console.log(`🔍 [LEVEL 4] Raycast miss - Monster ${index}:`, {
          monsterPos: monsterWorldPos.toArray().map(n => n.toFixed(2)),
          cameraPos: cameraPos.toArray().map(n => n.toFixed(2)),
          distance: distToMonster.toFixed(2),
          rayDir: rayDir.toArray().map(n => n.toFixed(2)),
          meshVisible: monster.mesh.visible,
          meshInScene: level4State.group.children.includes(monster.mesh),
          meshChildren: monster.mesh.children.length
        });
      }
      
      if (intersects.length > 0) {
        const distance = intersects[0].distance;
        if (distance < hitDistance) {
          hitDistance = distance;
          hitMonster = monster; // Store monster reference
          hitCheese = null; // Clear cheese hit if monster is closer
          hitIndex = -1;
          monsterHitIndex = index; // Keep index for logging, but we'll use monster reference
          targetPos.copy(intersects[0].point); // Use actual hit point
          console.log(`🎯 [LEVEL 4] Monster ${index} HIT! Distance: ${distance.toFixed(2)}, Name: ${monster.path.split('/').pop()}`);
        }
      }
    });
  }
  
  // Check for cheese hits (Step 1) only if no monster hit found
  if (level4RiddleState.step1Active && !hitMonster) {
    level4State.cheeses.forEach((cheese, index) => {
      if (!cheese || !cheese.mesh || !cheese.mesh.visible) return;
      
      // Raycast against cheese mesh
      const intersects = raycaster.intersectObject(cheese.mesh, false);
      if (intersects.length > 0) {
        const distance = intersects[0].distance;
        if (distance < hitDistance) {
          hitDistance = distance;
          hitCheese = cheese;
          hitIndex = index;
          targetPos.copy(intersects[0].point); // Use actual hit point
        }
      }
    });
  }
  
  // Create visible bullet (purple for SF13, yellow for normal)
  if (isPurple) {
    createLevel4SF13Bullet(bulletStartPos, rayDirection, targetPos);
  } else {
    createLevel4CheeseBullet(bulletStartPos, rayDirection, targetPos);
  }
  
  // Instant hit detection (for responsive gameplay)
  if (hitMonster && monsterHitIndex >= 0) {
    // Monster hit (Step 2 takes priority)
    // CRITICAL: Use monster reference to find current index (array might have shifted)
    const currentIndex = level4State.monsters.indexOf(hitMonster);
    if (currentIndex >= 0) {
      console.log("🎯 [LEVEL 4] Monster hit! Index:", currentIndex, "Monster:", hitMonster.path.split('/').pop(), "Distance:", hitDistance.toFixed(2));
      defeatLevel4Monster(currentIndex); // Use current index, not stale one
    } else {
      console.warn(`⚠️ [LEVEL 4] Hit monster not found in array (was already removed?)`);
    }
    showLevel4HitIndicator();
  } else if (hitCheese && hitIndex >= 0) {
    // Cheese hit (Step 1)
    console.log("🎯 [LEVEL 4] Cheese hit! Index:", hitIndex);
    captureLevel4Cheese(hitIndex);
    showLevel4HitIndicator();
  } else if (level4RiddleState.step2Active && level4State.monsters.length > 0) {
    // Debug: Log if we shot but didn't hit anything in monster waves (only occasionally to avoid spam)
    if (Math.random() < 0.05) { // Log 5% of missed shots
      console.log("🔫 [LEVEL 4] Shot fired but no monster hit. Active monsters:", level4State.monsters.length, "Step2Active:", level4RiddleState.step2Active);
      // Log monster positions for debugging
      level4State.monsters.forEach((m, i) => {
        console.log(`  Monster ${i}: visible=${m.mesh?.visible}, defeated=${m.defeated}, pos=(${m.mesh?.position.x.toFixed(2)}, ${m.mesh?.position.y.toFixed(2)}, ${m.mesh?.position.z.toFixed(2)})`);
      });
    }
  }
  
  // Apply recoil animation
  level4State.weaponRecoilOffset = 1.0; // Full recoil
  // CRITICAL: Sync with weapon system's recoil offset if available
  if (weaponSystem) {
    weaponSystem.weaponRecoilOffset = 1.0;
  }
}

// Update triple-shot system (called every frame)
function updateLevel4TripleShot(delta) {
  if (!level4State.tripleShotActive || level4State.tripleShotBulletsRemaining <= 0) {
    level4State.tripleShotActive = false;
    return;
  }
  
  const currentTime = performance.now() / 1000;
  
  // Check if it's time for next bullet (100-120ms between shots - typical FPS burst timing)
  const burstDelay = 0.11; // 110ms between shots (balanced FPS burst timing)
  
  if (currentTime >= level4State.tripleShotNextBulletTime && level4State.tripleShotBulletsRemaining > 0) {
    // Fire next bullet in burst
    level4State.tripleShotBulletsRemaining--;
    level4State.tripleShotNextBulletTime = currentTime + burstDelay;
    
    // Fire bullet
    fireLevel4SingleShot(true); // Purple bullet
    
    // Play SF13 sound (once per bullet = 3 times total)
    if (level4SF13ShootAudioReady && level4SF13ShootSound) {
      if (level4SF13ShootSound.isPlaying) {
        level4SF13ShootSound.stop();
      }
      level4SF13ShootSound.play();
    }
    
    // If all bullets fired, end burst
    if (level4State.tripleShotBulletsRemaining <= 0) {
      level4State.tripleShotActive = false;
    }
  }
}

// FIX: Improved click handler for pointer lock (handles pause/resume and level loading)
document.addEventListener("click", (event) => {
  // Don't lock pointer if options menu is open, game is paused, or clicking on UI elements
  if (window.optionsMenuOpen || isGamePaused) {
    return;
  }
  
  // Don't lock if clicking on pause menu, options menu, or other UI elements
  const target = event.target;
  if (target.closest('.pause-menu') || target.closest('.options-menu') || target.closest('button')) {
    return;
  }
  
  // CRITICAL: Request pointer lock after level loads (January 4, 2026)
  // This handles the case where pointer lock wasn't acquired during async loading
  if (window.needsPointerLockAfterLoad && !isGamePaused && !window.optionsMenuOpen && !isJoystickView() && playerControls) {
    const currentCameraMode = typeof getCameraMode === 'function' ? getCameraMode() : (typeof cameraMode !== 'undefined' ? cameraMode : 0);
    if (currentCameraMode === 0) { // Only request for first-person view
      try {
        playerControls.getPointerLockControls().lock();
        window.needsPointerLockAfterLoad = false; // Clear flag
        console.log("✅ [GAME START] Pointer lock requested after level load (user click)");
      } catch (e) {
        console.log("⚠️ [GAME START] Pointer lock failed on click:", e);
      }
      return; // Don't continue to other pointer lock requests
    }
  }
  
  // FIX: Re-request pointer lock after pause (if needed)
  if (window.needsPointerLockAfterPause && !isGamePaused && !window.optionsMenuOpen && !isJoystickView() && playerControls) {
    try {
      playerControls.getPointerLockControls().lock();
      // Flag will be cleared in pointerlockchange event
      console.log("🎮 [PAUSE] Pointer lock re-requested after resume");
    } catch (e) {
      console.log("🎮 [PAUSE] Pointer lock failed - user may need to click again:", e);
    }
    return; // Don't lock again below
  }
  
  // Normal pointer lock (if not in joystick view)
  if (!isJoystickView() && playerControls && !playerControls.getPointerLockControls().isLocked) {
    playerControls.getPointerLockControls().lock(); // Lock pointer for both modes
  }
});

// Level 4 Shooting - Use mousedown event (separate from click for pointer lock)
document.addEventListener("mousedown", (event) => {
  // CRITICAL: Request pointer lock after level loads (January 4, 2026)
  // This handles the case where pointer lock wasn't acquired during async loading
  // Must check this FIRST, before pause check
  if (window.needsPointerLockAfterLoad && !isGamePaused && !window.optionsMenuOpen && !isJoystickView() && playerControls) {
    const currentCameraMode = typeof getCameraMode === 'function' ? getCameraMode() : (typeof cameraMode !== 'undefined' ? cameraMode : 0);
    if (currentCameraMode === 0 && !playerControls.getPointerLockControls().isLocked) { // Only request for first-person view
      try {
        playerControls.getPointerLockControls().lock();
        window.needsPointerLockAfterLoad = false; // Clear flag
        console.log("✅ [GAME START] Pointer lock requested after level load (mousedown)");
      } catch (e) {
        console.log("⚠️ [GAME START] Pointer lock failed on mousedown:", e);
      }
      return; // Exit early - don't continue to other handlers
    }
  }
  
  // CRITICAL: Check if we need to restore pointer lock after pause
  // This must happen AFTER level load check
  if (window.needsPointerLockAfterPause && !isGamePaused && !window.optionsMenuOpen && !isJoystickView() && playerControls && !playerControls.getPointerLockControls().isLocked) {
    try {
      playerControls.getPointerLockControls().lock();
      console.log("🎮 [PAUSE] Pointer lock restored via mousedown after resume");
      // Flag will be cleared in pointerlockchange event
    } catch (e) {
      console.log("🎮 [PAUSE] Pointer lock failed on mousedown:", e);
    }
    // Continue to allow other handlers to run
  }
  
  // Only handle shooting in Level 4 (Step 1 or Step 2 active), Level 5, or Level 6, first-person, and pointer locked
  const isLevel4WithActiveStep = currentLevel === LEVEL_IDS.LEVEL4 && (level4RiddleState.step1Active || level4RiddleState.step2Active);
  const isLevel5 = currentLevel === LEVEL_IDS.LEVEL5;
  const isLevel6 = currentLevel === LEVEL_IDS.LEVEL6;
  const canShoot = (isLevel4WithActiveStep || isLevel5 || isLevel6) && 
      isFirstPerson() && 
      playerControls && playerControls.getPointerLockControls().isLocked && 
                   event.button === 0;
  
  if (canShoot) {
    // Use Weapon System if available, otherwise fallback to legacy function
    if (weaponSystem && typeof weaponSystem.fire === 'function') {
      // CRITICAL: Ensure weapon is loaded before firing
      if (!weaponSystem.weaponViewmodel || !weaponSystem.camera.children.includes(weaponSystem.weaponViewmodel)) {
        console.warn("⚠️ [WEAPON] Weapon not loaded, attempting to load...");
        const currentSlot = weaponSystem.getCurrentSlot() || 1;
        weaponSystem.loadWeapon(currentSlot).then(() => {
      weaponSystem.fire();
        }).catch(err => {
          console.error("❌ [WEAPON] Failed to load weapon for shooting:", err);
        });
      } else {
        weaponSystem.fire();
      }
    } else if (typeof handleLevel4Shooting === 'function') {
      handleLevel4Shooting(); // Legacy fallback
    }
    event.preventDefault(); // Prevent default behavior
  } else if (((currentLevel === LEVEL_IDS.LEVEL4 && 
               (level4RiddleState.step1Active || level4RiddleState.step2Active)) || 
               currentLevel === LEVEL_IDS.LEVEL5 ||
               currentLevel === LEVEL_IDS.LEVEL6) && 
               event.button === 0) {
    // Debug: Log why shooting is blocked (only occasionally to avoid spam)
    if (Math.random() < 0.1) {
      console.log("🔫 [WEAPON] Shooting blocked:", {
        level: currentLevel,
        firstPerson: isFirstPerson(),
        pointerLocked: playerControls ? playerControls.getPointerLockControls().isLocked : false,
        step1Active: level4RiddleState.step1Active,
        step2Active: level4RiddleState.step2Active,
        weaponLoaded: weaponSystem ? (weaponSystem.weaponViewmodel !== null) : false
      });
    }
  }
});

// Mouse movement is now handled by PlayerControls module
