const textureLoader = new THREE.TextureLoader();
const gltfLoader = new GLTFLoader();
const fbxLoader = new FBXLoader();
const textureCache = new Map();
const modelCache = new Map();

function loadTexture(path) {
  // FIXED (January 6, 2026): Resolve path correctly for production
  const resolvedPath = resolveAssetPath(path);
  
  if (textureCache.has(resolvedPath)) {
    const cached = textureCache.get(resolvedPath);
    // Verify cached texture is still valid
    if (cached && cached.image && cached.image.complete && cached.image.width > 0) {
      return cached;
    }
  }
  
  console.log(`📦 [TEXTURE] Loading texture: ${path} -> ${resolvedPath}`);
  
  // For Three.js TextureLoader, use resolvedPath directly
  // - Production: resolvedPath is full URL (http://...)
  // - Local: resolvedPath is relative path (./public/...) which resolves from HTML location
  // Three.js will handle the path resolution correctly
  const texture = textureLoader.load(
    resolvedPath,
    (loadedTexture) => {
      console.log(`✅ [TEXTURE] Successfully loaded: ${path}`, {
        width: loadedTexture.image?.width,
        height: loadedTexture.image?.height,
        image: loadedTexture.image ? "✅ Has image" : "❌ No image",
        resolvedPath: resolvedPath
      });
      loadedTexture.needsUpdate = true;
    },
    (progress) => {
      // Progress callback (optional)
      if (progress && progress.lengthComputable) {
        const percentComplete = (progress.loaded / progress.total) * 100;
        console.log(`📦 [TEXTURE] Loading ${path}: ${percentComplete.toFixed(1)}%`);
      }
    },
    (error) => {
      console.error(`❌ [TEXTURE] Failed to load texture: ${path}`, error);
      console.error(`❌ [TEXTURE] Resolved path: ${resolvedPath}`);
      console.error(`❌ [TEXTURE] HTML location: ${window.location.href}`);
      if (error && error.message) {
        console.error(`❌ [TEXTURE] Error message: ${error.message}`);
      } else if (error && typeof error === 'object') {
        console.error(`❌ [TEXTURE] Error details:`, error);
      } else {
        console.error(`❌ [TEXTURE] Error:`, String(error));
      }
      
      // Create a fallback colored texture so materials don't break
      const fallbackTexture = new THREE.DataTexture(
        new Uint8Array([255, 200, 0, 255]), // Yellow color (visible fallback)
        1, 1,
        THREE.RGBAFormat
      );
      fallbackTexture.wrapS = fallbackTexture.wrapT = THREE.RepeatWrapping;
      fallbackTexture.magFilter = THREE.NearestFilter;
      fallbackTexture.minFilter = THREE.NearestFilter;
      fallbackTexture.needsUpdate = true;
      
      // Replace in cache with fallback
      textureCache.set(resolvedPath, fallbackTexture);
      
      // Update the texture object that was already created
      if (texture) {
        try {
          texture.image = fallbackTexture.image;
          texture.needsUpdate = true;
          console.warn(`⚠️ [TEXTURE] Using fallback texture for: ${path} (resolved: ${resolvedPath})`);
        } catch (e) {
          console.error(`❌ [TEXTURE] Failed to set fallback:`, e);
        }
      }
    }
  );
  
  texture.wrapS = texture.wrapT = THREE.RepeatWrapping;
  texture.magFilter = THREE.NearestFilter;
  texture.minFilter = THREE.NearestFilter;
  // FIXED: Cache using resolvedPath, not original path
  textureCache.set(resolvedPath, texture);
  
  // Verify texture after a delay to catch loading issues
  setTimeout(() => {
    const cached = textureCache.get(resolvedPath);
    if (cached && cached.image && cached.image.complete && cached.image.width > 0) {
      console.log(`✅ [TEXTURE] Texture verified loaded: ${path} (${cached.image.width}x${cached.image.height})`);
    } else {
      console.warn(`⚠️ [TEXTURE] Texture may not be loaded yet: ${path}`, {
        hasImage: cached?.image ? true : false,
        complete: cached?.image?.complete,
        width: cached?.image?.width,
        height: cached?.image?.height,
        resolvedPath: resolvedPath
      });
    }
  }, 1000);
  
  return texture;
}

// Load GLTF/GLB model
function loadModel(path) {
  // FIXED (January 6, 2026): Resolve path correctly for production
  const resolvedPath = resolveAssetPath(path);
  const lowerPath = resolvedPath.toLowerCase();
  const isFBX = lowerPath.endsWith(".fbx");
  return new Promise((resolve, reject) => {
    if (modelCache.has(resolvedPath)) {
      const cached = modelCache.get(resolvedPath);
      if (cached.isFBX) {
        const clonedScene = cached.scene.clone(true);
        resolve({
          scene: clonedScene,
          animations: cached.animations || [],
          isFBX: true
        });
        return;
      }
      const cloned = cached.scene.clone(true);
      resolve({
        scene: cloned,
        animations: cached.animations,
        asset: cached.asset,
        parser: cached.parser,
        userData: cached.userData
      });
      return;
    }

    const onProgress = (progress) => {
      if (progress.lengthComputable) {
        const percentComplete = (progress.loaded / progress.total) * 100;
        console.log("📦 [MODEL] Loading:", path, `-> ${resolvedPath}`, `${percentComplete.toFixed(1)}%`);
      }
    };

    if (isFBX) {
      fbxLoader.load(
        resolvedPath,
        (fbx) => {
          console.log("✅ [MODEL] FBX loaded:", path, `-> ${resolvedPath}`, {
            children: fbx.children.length
          });
          const payload = { scene: fbx, animations: fbx.animations || [], isFBX: true };
          modelCache.set(resolvedPath, payload);
          resolve(payload);
        },
        onProgress,
        (error) => {
          console.error("❌ [MODEL] Error loading FBX:", path, `-> ${resolvedPath}`, error);
          reject(error);
        }
      );
      return;
    }
    
    gltfLoader.load(
      resolvedPath,
      (gltf) => {
        console.log("✅ [MODEL] Model loaded:", path, `-> ${resolvedPath}`, {
          scene: gltf.scene,
          animations: gltf.animations?.length || 0,
          meshes: gltf.scene.children.length
        });
        modelCache.set(resolvedPath, gltf);
        resolve(gltf);
      },
      onProgress,
      (error) => {
        console.error("❌ [MODEL] Error loading model:", path, `-> ${resolvedPath}`, error);
        reject(error);
      }
    );
  });
}

// Character model system (GLTF/GLB models)
// LEGACY: Keep these for backward compatibility during migration
let playerCharacterModel = null; // Will be managed by PlayerModel module
let playerCharacterMixer = null; // Will be managed by PlayerModel module
let playerCharacterAnimations = {}; // Will be managed by PlayerModel module
let playerCharacterClock = new THREE.Clock();
let useGLTFCharacter = false; // Flag to use GLTF character instead of simple playerModel
let selectedCharacterPath = null; // Store selected character path
let characterSelectionMenu = null; // Character selection menu

// NEW: PlayerModel module instance
let playerModelModule = null;

// Character options configuration
const CHARACTER_OPTIONS = {
  2: {
    name: "Mouse",
    path: "/textures/3d models/Mouse/glb/glb/character/character.glb",
    description: "Mouse Character"
  },
  3: {
    name: "Animation Library",
    path: "/textures/3d models/Animation Libary/Animation Library[Standard]/Godot/AnimationLibrary_Godot_Standard.glb",
    description: "Animation Library [Standard]"
  }
};

// Load and display player character model from GLTF/GLB file (for third-person view)
async function loadPlayerCharacter(modelPath = null) {
  // Use selected character path if provided, otherwise use default
  const pathToLoad = modelPath || selectedCharacterPath || CHARACTER_OPTIONS[3].path;
  try {
    console.log("🎮 [CHARACTER] Loading player character model:", pathToLoad);
    const gltf = await loadModel(pathToLoad);
    
    // CRITICAL FIX: Don't clone - use the original scene directly
    // Cloning can break material references and texture loading
    // We'll add it to scene and handle visibility manually
    playerCharacterModel = gltf.scene;
    playerCharacterModel.name = "PlayerCharacter";
    
    // If we need multiple instances, we can clone later, but for now use original
    // playerCharacterModel = gltf.scene.clone(true);
    
    // CRITICAL FIX: Configure meshes and materials from original GLB
    // Use original materials from GLB (they're already properly set up by GLTFLoader)
    let meshCount = 0;
    let materialCount = 0;
    playerCharacterModel.traverse((child) => {
      if (child.isMesh) {
        meshCount++;
        child.castShadow = true;
        child.receiveShadow = true;
        child.frustumCulled = false; // Disable frustum culling for visibility
        child.visible = true;
        // CRITICAL: Set render order ONCE to prevent z-fighting and double rendering
        // Use a consistent render order that's higher than level objects
        if (!child.userData || child.userData.renderOrderSet !== true) {
          child.renderOrder = 100; // Higher render order ensures character renders on top
          if (!child.userData) child.userData = {};
          child.userData.renderOrderSet = true; // Mark as set - don't update again
        }
        
        // CRITICAL: Use original GLB materials - don't modify them extensively
        // Just ensure they're visible and properly configured
        if (child.material) {
          const hasMaterialArray = Array.isArray(child.material);
          const materialsToProcess = hasMaterialArray ? child.material : [child.material];
          
          materialsToProcess.forEach((material, idx) => {
            if (material) {
              materialCount++;
              
              // Preserve original material from GLB - minimal modifications
              // GLTFLoader already sets up materials correctly from GLB
              
              // Only ensure visibility properties (don't override material type or properties)
              material.transparent = false;
              material.opacity = 1.0;
              material.visible = true;
              
              // Ensure textures are loaded if present
              if (material.map && material.map instanceof THREE.Texture) {
                material.map.needsUpdate = true;
                // Ensure texture image is loaded
                if (material.map.image) {
                  material.map.needsUpdate = true;
                }
              }
              
              // Force material update (ensures WebGL state is updated)
              material.needsUpdate = true;
              
              // Log material details for first mesh only
              if (meshCount === 1 && idx === 0) {
                console.log("🎭 [CHARACTER] Material from GLB (original):", {
                  meshName: child.name || 'unnamed',
                  materialType: material.type,
                  hasColor: !!material.color,
                  hasMap: !!material.map,
                  color: material.color ? material.color.getHexString() : 'none',
                  transparent: material.transparent,
                  opacity: material.opacity,
                  visible: material.visible,
                  side: material.side,
                  note: "Using original GLB material (not cloned)"
                });
              }
            } else {
              console.warn("⚠️ [CHARACTER] Null material at index:", idx, "for mesh:", child.name);
            }
          });
        } else {
          // No material - create visible debug material
          console.error("❌ [CHARACTER] Mesh has no material:", child.name);
          child.material = new THREE.MeshStandardMaterial({
            color: 0xff0000, // Bright red for debugging
            emissive: 0xff0000,
            emissiveIntensity: 2.0,
            side: THREE.DoubleSide,
            visible: true
          });
          materialCount++;
        }
      }
    });
    
    console.log("🎭 [CHARACTER] Material setup:", {
      totalMeshes: meshCount,
      totalMaterials: materialCount,
      note: "Using original GLB materials (preserved from model file)"
    });
    
    // CRITICAL: Update world matrices after all transformations
    playerCharacterModel.updateMatrixWorld(true);
    
    // Calculate scale based on model size (simplified approach)
    const originalBox = new THREE.Box3().setFromObject(playerCharacterModel);
    const originalSize = originalBox.getSize(new THREE.Vector3());
    console.log("🎭 [CHARACTER] Original model size:", {
      x: originalSize.x.toFixed(2),
      y: originalSize.y.toFixed(2),
      z: originalSize.z.toFixed(2)
    });
    
    // Scale to match player height (1.8 units target)
    const targetHeight = 1.8;
    const scale = targetHeight / originalSize.y;
    playerCharacterModel.scale.set(scale, scale, scale);
    console.log("🎭 [CHARACTER] Scale applied:", {
      originalHeight: originalSize.y.toFixed(2),
      targetHeight: targetHeight.toFixed(2),
      scale: scale.toFixed(4)
    });
    
    // Position character at player spawn
    // CRITICAL: Use feet position (playerCollider.start) to ensure model is on ground
    // The feet position is the actual ground level where the player spawns
    const initialPlayerFeetPos = playerCollider.start.clone();
    
    // CRITICAL: Detect Mouse character BEFORE using it (must be declared before use!)
    // Mouse character has different default orientation and height offset needs
    const isMouseCharacterModel = pathToLoad && pathToLoad.includes('Mouse');
    playerCharacterModel.userData.isMouseCharacter = isMouseCharacterModel;
    
    // CRITICAL: heightOffset aligns model's feet with player's feet position
    // Subtract heightOffset from feet position to position model correctly
    // Mouse character: model pivot is at feet, need to lower character to align feet with ground
    // Animation Library: model pivot is at center, need to lower character to align feet with ground
    let heightOffset = 0.85 * scale; // Default for Animation Library (subtract to lower)
    if (isMouseCharacterModel) {
      // Mouse character: additional downward offset so feet rest exactly on ground
      heightOffset = 0.95;
      console.log("🐭 [CHARACTER] Mouse character height offset: 0.95 (feet aligned with ground)");
    }
    
    // Position model so feet align with player feet position (ground level)
    playerCharacterModel.position.set(
      initialPlayerFeetPos.x, 
      initialPlayerFeetPos.y - heightOffset, // Subtract offset to align feet with ground
      initialPlayerFeetPos.z
    );
    
    // CRITICAL: Mouse character has different default orientation
    // Based on user feedback: W moves left, D moves right correctly
    // This suggests Mouse character's forward might be along -X or +Y axis
    // Try +90 degree rotation first (rotate from -X to +Z)
    if (isMouseCharacterModel) {
      // Mouse character rotation will be handled in updatePlayerCharacter
      // Start with 0 rotation, then apply offset during movement rotation calculation
      playerCharacterModel.rotation.y = 0; // Start at 0, offset applied during movement
      console.log("🐭 [CHARACTER] Mouse character initial rotation: 0 (offset applied during movement)");
    } else {
      playerCharacterModel.rotation.y = 0; // Animation Library character uses standard +Z forward
    }
    
    playerCharacterModel.visible = !isFirstPerson(); // Visible in 3rd person only
    
    // CRITICAL: Update world matrices after positioning
    playerCharacterModel.updateMatrixWorld(true);
    
    // Hide existing simple playerModel if it exists
    if (playerModel) {
      playerModel.visible = false;
      console.log("🎮 [CHARACTER] Hiding simple playerModel, using GLTF character instead");
    }
    
    // Set flag to use GLTF character
    useGLTFCharacter = true;
    
    // Add character to scene
    scene.add(playerCharacterModel);
    
    // CRITICAL: Final matrix update after adding to scene
    playerCharacterModel.updateMatrixWorld(true);
    
    // Verify character is properly set up (reuse variables from above)
    let verifiedMeshCount = 0;
    let verifiedMaterialCount = 0;
    playerCharacterModel.traverse((child) => {
      if (child.isMesh) {
        verifiedMeshCount++;
        if (child.material) {
          const hasMaterialArray = Array.isArray(child.material);
          verifiedMaterialCount += hasMaterialArray ? child.material.length : 1;
        }
      }
    });
    
    console.log("🎭 [CHARACTER] Character added to scene at position:", {
      x: playerCharacterModel.position.x.toFixed(2),
      y: playerCharacterModel.position.y.toFixed(2),
      z: playerCharacterModel.position.z.toFixed(2),
      scale: scale.toFixed(4),
      meshCount: verifiedMeshCount,
      materialCount: verifiedMaterialCount,
      inScene: scene.children.includes(playerCharacterModel),
      visible: playerCharacterModel.visible
    });
    
    // Set up animations - Check if Mouse character (separate animation files) or embedded animations
    const isMouseCharacter = pathToLoad.includes('Mouse') && pathToLoad.includes('character');
    
    if (gltf.animations && gltf.animations.length > 0) {
      // Character has embedded animations (Animation Library model)
      playerCharacterMixer = new THREE.AnimationMixer(playerCharacterModel);
      
      // Store all animations and configure them properly
      gltf.animations.forEach((clip) => {
        const action = playerCharacterMixer.clipAction(clip);
        
        // CRITICAL: Ensure animations loop properly
        // Loop animations (Idle, Walk, Sprint, etc.) should repeat
        const isLoopAnimation = clip.name.includes('Loop') || 
                               clip.name.includes('Idle') || 
                               clip.name.includes('Walk') || 
                               clip.name.includes('Sprint') || 
                               clip.name.includes('Jog') ||
                               clip.name.includes('Run');
        
        if (isLoopAnimation) {
          action.setLoop(THREE.LoopRepeat, Infinity); // Loop forever
        } else {
          action.setLoop(THREE.LoopOnce, 1); // Play once for non-loop animations
        }
        
        // Set proper time scale and initial weight
        action.setEffectiveTimeScale(1.0);
        action.setEffectiveWeight(0.0); // Start at 0 weight (will fade in when needed)
        
        playerCharacterAnimations[clip.name] = action;
        console.log("🎬 [CHARACTER] Animation loaded:", clip.name, {
          duration: clip.duration.toFixed(2) + "s",
          loop: isLoopAnimation ? "Repeat" : "Once",
          clipLoop: clip.loopMode || "default"
        });
      });
      
      // Play default animation (idle, walk, etc.)
      const defaultAnimations = [
        'Idle_Loop', 'Idle', 'idle', 
        'Walk_Loop', 'Walk', 'walk', 
        'Jog_Fwd_Loop', 'Run', 'Running', 'running', 'run'
      ];
      let playedAnimation = false;
      
      for (const animName of defaultAnimations) {
        if (playerCharacterAnimations[animName]) {
          const action = playerCharacterAnimations[animName];
          action.reset();
          action.setEffectiveTimeScale(1.0);
          action.setLoop(THREE.LoopRepeat, Infinity);
          action.clampWhenFinished = false;
          action.enabled = true;
          action.setEffectiveWeight(1.0);
          action.play();
          window.currentCharacterAnimation = animName;
          console.log("🎬 [CHARACTER] Playing default animation:", animName, {
            enabled: action.enabled,
            weight: action.getEffectiveWeight(),
            loop: "Repeat"
          });
          playedAnimation = true;
          break;
        }
      }
      
      if (!playedAnimation && gltf.animations.length > 0) {
        const firstAction = playerCharacterMixer.clipAction(gltf.animations[0]);
        firstAction.reset();
        firstAction.setEffectiveTimeScale(1.0);
        firstAction.setLoop(THREE.LoopRepeat, Infinity);
        firstAction.clampWhenFinished = false;
        firstAction.enabled = true;
        firstAction.setEffectiveWeight(1.0);
        firstAction.play();
        window.currentCharacterAnimation = gltf.animations[0].name;
        console.log("🎬 [CHARACTER] Playing first animation:", gltf.animations[0].name);
      }
    } else if (isMouseCharacter) {
      // Mouse character: Load animations from separate GLB files
      console.log("🐭 [CHARACTER] Mouse character detected - loading animations from separate files...");
      await loadMouseCharacterAnimations();
    } else {
      console.log("⚠️ [CHARACTER] No animations found in model");
    }
    
    console.log("✅ [CHARACTER] Player character model loaded and added to scene")
    
    return playerCharacterModel;
    
  } catch (error) {
    console.error("❌ [CHARACTER] Error loading player character model:", error);
    console.error("❌ [CHARACTER] Model path:", modelPath);
    console.error("❌ [CHARACTER] Make sure the model file exists and is in GLTF/GLB format");
    useGLTFCharacter = false;
    return null;
  }
}

// Load Mouse character animations from separate GLB files
async function loadMouseCharacterAnimations() {
  try {
    console.log("🐭 [CHARACTER] Loading Mouse character animations...");
    
    // Mouse animation files mapping
    const mouseAnimations = {
      'idle': '/textures/3d models/Mouse/glb/glb/animation/idle.glb',
      'run': '/textures/3d models/Mouse/glb/glb/animation/run.glb',
      'jump': '/textures/3d models/Mouse/glb/glb/animation/jump.glb',
      'climb': '/textures/3d models/Mouse/glb/glb/animation/climb.glb',
      'death': '/textures/3d models/Mouse/glb/glb/animation/death.glb',
      'somersoult': '/textures/3d models/Mouse/glb/glb/animation/somersoult.glb'
    };
    
    // Create mixer for Mouse character
    if (!playerCharacterMixer) {
      playerCharacterMixer = new THREE.AnimationMixer(playerCharacterModel);
    }
    
    // Load each animation file
    const animationPromises = Object.keys(mouseAnimations).map(async (animName) => {
      try {
        const animPath = mouseAnimations[animName];
        console.log(`🐭 [CHARACTER] Loading animation: ${animName} from ${animPath}`);
        const animGltf = await loadModel(animPath);
        
        // Extract animations from the loaded GLB
        if (animGltf.animations && animGltf.animations.length > 0) {
          // Use the first animation from the file (each file typically contains one animation)
          const clip = animGltf.animations[0];
          
          // Create animation action using the character model as the target
          const action = playerCharacterMixer.clipAction(clip, playerCharacterModel);
          
          // Determine if this is a loop animation
          // Mouse animations: idle, run are loops; jump, death, climb, somersoult are one-time
          const isLoopAnimation = animName === 'idle' || animName === 'run' || animName === 'climb';
          
          if (isLoopAnimation) {
            action.setLoop(THREE.LoopRepeat, Infinity);
            action.clampWhenFinished = false;
          } else {
            action.setLoop(THREE.LoopOnce, 1);
            action.clampWhenFinished = true;
          }
          
          // Store animation with lowercase name (matches Mouse format)
          action.setEffectiveTimeScale(1.0);
          action.setEffectiveWeight(0.0); // Start at 0 weight
          playerCharacterAnimations[animName] = action;
          
          console.log(`✅ [CHARACTER] Animation loaded: ${animName}`, {
            duration: clip.duration.toFixed(2) + "s",
            loop: isLoopAnimation ? "Repeat" : "Once",
            frames: clip.tracks ? clip.tracks.length : 0
          });
          
          return { name: animName, action, success: true };
        } else {
          console.warn(`⚠️ [CHARACTER] No animations found in ${animPath}`);
          return { name: animName, success: false };
        }
      } catch (error) {
        console.error(`❌ [CHARACTER] Error loading animation ${animName}:`, error);
        return { name: animName, success: false, error };
      }
    });
    
    // Wait for all animations to load
    const results = await Promise.all(animationPromises);
    const successful = results.filter(r => r.success);
    const failed = results.filter(r => !r.success);
    
    console.log(`🐭 [CHARACTER] Animation loading complete: ${successful.length} loaded, ${failed.length} failed`);
    
    // Play default idle animation
    if (playerCharacterAnimations['idle']) {
      const idleAction = playerCharacterAnimations['idle'];
      idleAction.reset();
      idleAction.setEffectiveTimeScale(1.0);
      idleAction.setLoop(THREE.LoopRepeat, Infinity);
      idleAction.clampWhenFinished = false;
      idleAction.enabled = true;
      idleAction.setEffectiveWeight(1.0);
      idleAction.play();
      window.currentCharacterAnimation = 'idle';
      console.log("🎬 [CHARACTER] Playing default animation: idle", {
        enabled: idleAction.enabled,
        weight: idleAction.getEffectiveWeight(),
        loop: "Repeat"
      });
    } else {
      console.warn("⚠️ [CHARACTER] No idle animation found - character will be static");
    }
    
  } catch (error) {
    console.error("❌ [CHARACTER] Error loading Mouse character animations:", error);
  }
}

