function hideCharacterSelectionMenu() {
  console.log("🎭 [CHARACTER] Hiding character selection menu...");
  
  // Use GUI System if available
  if (guiSystem && typeof guiSystem.hideCharacterSelectionMenu === 'function') {
    guiSystem.hideCharacterSelectionMenu();
    console.log("🎭 [CHARACTER] GUI System hideCharacterSelectionMenu called");
  }
  
  // Legacy fallback - also ensure it's removed
  if (characterSelectionMenu) {
    characterSelectionMenu.style.display = "none";
    characterSelectionMenu.style.pointerEvents = "none"; // Disable pointer events
    characterSelectionMenu.style.zIndex = "-1"; // Move behind everything
    characterSelectionMenu.style.visibility = "hidden"; // Also hide with visibility
    characterSelectionMenu.style.opacity = "0"; // Make it transparent
    if (characterSelectionMenu.parentNode && document.body.contains(characterSelectionMenu)) {
      document.body.removeChild(characterSelectionMenu);
      console.log("🧹 [CHARACTER] Legacy menu removed from DOM");
    }
    characterSelectionMenu = null;
  }
  
  // Also check for any character selection menus in the DOM and remove them
  // This handles cases where the menu might exist but the reference is lost
  const allCharacterMenus = document.querySelectorAll('[style*="z-index: 1003"], [style*="zIndex: 1003"], [style*="Select Character"]');
  allCharacterMenus.forEach((menu) => {
    // Check if it looks like a character selection menu (has "Select Character" text)
    if (menu.textContent && menu.textContent.includes("Select Character")) {
      menu.style.display = "none";
      menu.style.pointerEvents = "none";
      menu.style.zIndex = "-1";
      menu.style.visibility = "hidden";
      menu.style.opacity = "0";
      if (menu.parentNode) {
        menu.parentNode.removeChild(menu);
      }
      console.log("🧹 [CHARACTER] Removed orphaned character selection menu from DOM");
    }
  });
  
  // Force remove any menus with the character selection background color
  const menusWithBackground = document.querySelectorAll('[style*="rgba(5, 7, 16, 0.95)"]');
  menusWithBackground.forEach((menu) => {
    if (menu.textContent && (menu.textContent.includes("Select Character") || menu.textContent.includes("Choose your character"))) {
      menu.style.display = "none";
      menu.style.pointerEvents = "none";
      menu.style.zIndex = "-1";
      menu.style.visibility = "hidden";
      menu.style.opacity = "0";
      if (menu.parentNode) {
        menu.parentNode.removeChild(menu);
      }
      console.log("🧹 [CHARACTER] Removed character selection menu by background detection");
    }
  });
  
  // Also check for any div with "Select Character" in text content (more aggressive search)
  const allDivs = document.querySelectorAll('div');
  allDivs.forEach((div) => {
    if (div.textContent && div.textContent.includes("Select Character") && 
        (div.style.display !== 'none' || div.style.visibility !== 'hidden')) {
      // Check if it looks like a character menu (has buttons or character options)
      if (div.querySelector('button') || div.textContent.includes("Mouse") || div.textContent.includes("Animation Library")) {
        div.style.display = "none";
        div.style.pointerEvents = "none";
        div.style.zIndex = "-1";
        div.style.visibility = "hidden";
        div.style.opacity = "0";
        console.log("🧹 [CHARACTER] Removed character selection menu by text content search");
      }
    }
  });
  
  console.log("🎭 [CHARACTER] Character selection menu hidden");
}

function styleCharacterButton(button, primary) {
  Object.assign(button.style, {
    padding: "16px 24px",
    borderRadius: "10px",
    border: "1px solid rgba(255, 224, 102, 0.3)",
    fontSize: "15px",
    fontWeight: "600",
    cursor: "pointer",
    color: "#ffe066",
    background: primary
      ? "linear-gradient(135deg, rgba(255, 224, 102, 0.2), rgba(255, 224, 102, 0.1))"
      : "linear-gradient(135deg, rgba(15, 23, 42, 0.92), rgba(15, 23, 42, 0.7))",
    boxShadow: primary
      ? "0 10px 30px rgba(250, 204, 21, 0.35)"
      : "0 6px 20px rgba(15, 23, 42, 0.4)",
    transition: "transform 0.15s ease, box-shadow 0.15s ease, border-color 0.15s ease",
    width: "100%",
    textAlign: "center"
  });
  button.addEventListener("mouseenter", () => {
    button.style.transform = "translateY(-2px)";
    button.style.boxShadow = "0 12px 34px rgba(250, 204, 21, 0.45)";
    button.style.borderColor = "rgba(255, 224, 102, 0.6)";
  });
  button.addEventListener("mouseleave", () => {
    button.style.transform = "translateY(0)";
    button.style.boxShadow = primary
      ? "0 10px 30px rgba(250, 204, 21, 0.35)"
      : "0 6px 20px rgba(15, 23, 42, 0.4)";
    button.style.borderColor = "rgba(255, 224, 102, 0.3)";
  });
}

/**
 * Yield control to browser to prevent blocking
 * Uses requestAnimationFrame + setTimeout to allow browser to process events
 */
function yieldToBrowser() {
  return new Promise(resolve => {
    if (typeof requestAnimationFrame !== 'undefined') {
      requestAnimationFrame(() => {
        setTimeout(resolve, 0);
      });
    } else {
      setTimeout(resolve, 0);
    }
  });
}

/**
 * Warp to level with loading screen and progress updates
 * @param {string} levelId - Level identifier (e.g., "LEVEL1")
 * @param {string} levelName - Display name (e.g., "Level 1")
 * @param {Function} warpFunction - Function that performs the actual warp
 */
async function warpToLevelWithLoading(levelId, levelName, warpFunction) {
  try {
    // Phase 1: Preparation (5%)
    if (guiSystem) {
      guiSystem.showLoadingScreen(`Loading ${levelName}...`);
      guiSystem.updateLoadingProgress(5);
    }
    await yieldToBrowser();
    
    // Phase 2: Cleanup (15%)
    if (guiSystem) {
      guiSystem.updateLoadingProgress(15);
    }
    await yieldToBrowser();
    
    // Phase 3: Loading textures and building level (25-75%)
    if (guiSystem) {
      guiSystem.updateLoadingProgress(25);
    }
    
    // Execute warp function with progress updates
    const progressInterval = setInterval(() => {
      if (guiSystem) {
        const current = parseInt(guiSystem.loadingProgressText?.textContent || '25');
        if (current < 75) {
          guiSystem.updateLoadingProgress(current + 5);
        }
      }
    }, 100);
    
    await yieldToBrowser();
    
    // CRITICAL: Execute warp function with timeout protection to prevent infinite hanging
    // Increased timeout to 60 seconds - grass generation with 2M blades can take 30-40 seconds
    // If warpFunction takes too long or blocks, timeout will allow loading to continue
    // NOTE: This timeout is a safety feature, not an error - grass generation is heavy and may take time
    const timeoutPromise = new Promise(resolve => {
      setTimeout(() => {
        console.warn("⏱️ [WARP] Safety timeout reached (60s) - continuing to allow gameplay (grass generation may continue in background)");
        resolve();
      }, 60000); // 60 second timeout (increased from 10s for large grass generation)
    });
    
    // Execute the actual warp function with timeout protection
    try {
      if (typeof warpFunction === 'function') {
        // Wrap warpFunction in Promise.race to add timeout protection
        // This ensures that even if warpFunction blocks or hangs, we continue after 10s
        const warpPromise = Promise.resolve().then(() => {
          const result = warpFunction();
          // If warpFunction returns a Promise, return it; otherwise wrap it
          return result && typeof result.then === 'function' ? result : Promise.resolve(result);
        });
        
        // Race between warp function and timeout
        await Promise.race([warpPromise, timeoutPromise]);
      } else {
        // If not a function, just execute it (shouldn't happen, but safe)
        warpFunction();
      }
    } catch (error) {
      console.error("❌ [WARP] Error in warp function:", error);
      // Continue anyway - don't block loading
    }
    
    clearInterval(progressInterval);
    
    // Phase 4: Finalization - Wait for all systems to fully initialize (80-100%)
    if (guiSystem) {
      guiSystem.updateLoadingProgress(80);
    }
    await yieldToBrowser();
    
    // CRITICAL: Wait for async operations to complete (grass generation, chests, items, etc.)
    // Give additional time for all systems to fully initialize and render
    await new Promise(resolve => setTimeout(resolve, 500)); // Reduced delay - character loads in warp function now
    
    if (guiSystem) {
      guiSystem.updateLoadingProgress(95);
    }
    await yieldToBrowser();
    
    if (guiSystem) {
      guiSystem.updateLoadingProgress(100);
    }
    await yieldToBrowser();
    
    // CRITICAL: Additional delay to ensure all systems are fully rendered and ready
    await new Promise(resolve => setTimeout(resolve, 300));
    
    // Hide loading screen and ensure game is playable
    console.log("🎮 [LOADING] All systems ready - hiding loading screen");
    if (guiSystem) {
      guiSystem.hideLoadingScreen();
    }
    
    // Ensure character selection menu is completely hidden
    hideCharacterSelectionMenu();
    
    // CRITICAL: Restore game state (unpause, enable controls, etc.)
    // Ensure game is not paused
    if (window.isGamePaused) {
      window.isGamePaused = false;
      if (typeof togglePause === 'function') {
        togglePause(false);
      }
    }
    
    // CRITICAL: Ensure playerControls is initialized before enabling
    if (!playerControls && typeof initializePlayerControls === 'function') {
      try {
        initializePlayerControls();
        console.log("✅ [GAME START] Player controls initialized");
      } catch (error) {
        console.error("❌ [GAME START] Failed to initialize player controls:", error);
      }
    }
    
    // Enable player controls
    if (playerControls && typeof playerControls.setEnabled === 'function') {
      playerControls.setEnabled(true);
      console.log("✅ [GAME START] Player controls enabled");
    } else {
      console.error("❌ [GAME START] Player controls not available or setEnabled not found:", {
        playerControls: !!playerControls,
        hasSetEnabled: playerControls && typeof playerControls.setEnabled === 'function'
      });
    }
    
    // Request pointer lock for first-person controls
    // CRITICAL: Set flag to request pointer lock on next user interaction (browser security requires user gesture)
    // Browser blocks pointer lock requests after async delays, so we request it on next click/mousedown
    const currentCameraMode = typeof getCameraMode === 'function' ? getCameraMode() : (typeof cameraMode !== 'undefined' ? cameraMode : 0);
    if (currentCameraMode === 0 && playerControls && playerControls.getPointerLockControls) {
      const pointerLockControls = playerControls.getPointerLockControls();
      if (pointerLockControls && !pointerLockControls.isLocked) {
        // Set flag to request pointer lock on next user interaction (click/mousedown)
        window.needsPointerLockAfterLoad = true;
        console.log("✅ [GAME START] Pointer lock flag set - will request on next user interaction");
        
        // Also try to request immediately (might work if triggered from user gesture)
        setTimeout(() => {
          try {
            pointerLockControls.lock();
            console.log("✅ [GAME START] Pointer lock requested immediately");
          } catch (err) {
            // Expected to fail - browser requires user gesture, so we use the flag instead
            console.log("ℹ️ [GAME START] Pointer lock will be requested on next click (browser security requirement)");
          }
        }, 200);
      } else {
        console.log("✅ [GAME START] Pointer lock already active");
        window.needsPointerLockAfterLoad = false; // Clear flag if already locked
      }
    } else {
      console.warn("⚠️ [GAME START] Cannot request pointer lock:", {
        currentCameraMode: currentCameraMode,
        hasPlayerControls: !!playerControls,
        hasGetPointerLockControls: playerControls && typeof playerControls.getPointerLockControls === 'function'
      });
      window.needsPointerLockAfterLoad = false; // Clear flag if conditions not met
    }
    
    // Ensure camera is visible and scene is rendered
    if (camera) {
      camera.visible = true;
    }
    if (renderer && scene) {
      renderer.render(scene, camera);
    }
    
    console.log("✅ [GAME START] Game is now playable - all modules loaded");
    
  } catch (error) {
    console.error(`❌ [WARP] Error warping to ${levelName}:`, error);
    
    if (guiSystem) {
      guiSystem.hideLoadingScreen();
    }
    
    // Fix: Handle error object properly - error might not be an Error instance
    const errorMessage = error instanceof Error ? error.message : (typeof error === 'string' ? error : String(error));
    alert(`Failed to load ${levelName}. Please try again.\n\nError: ${errorMessage}`);
    throw error;
  }
}

// Flag to track if game start is pending (waiting for level selection when GOD MODE is ON)
let gameStartPendingLevel = null; // null = not pending, level ID = pending with specific level

function startGame(startLevelId = null) {
  // Use provided level ID or default to Level 1
  const targetLevelId = startLevelId || LEVEL_IDS.LEVEL1;
  const targetLevelName = startLevelId 
    ? `Level ${Object.keys(LEVEL_IDS).find(key => LEVEL_IDS[key] === startLevelId)?.replace('LEVEL', '') || '1'}`
    : "Level 1";
  
  console.log(`🚀 [GAME START] Starting game with ${targetLevelName} (${targetLevelId})`);
  
  // Clear pending flag if it was set
  gameStartPendingLevel = null;
  
  // CRITICAL: Show canvas when game starts (it was hidden initially)
  // This ensures users don't see level preview before main menu
  if (renderer && renderer.domElement) {
    renderer.domElement.style.display = "block";
    console.log("✅ [GAME START] Canvas shown - game is starting");
  }
  
  // Show HUD elements when game starts (they were hidden during loading screen)
  if (stats && stats.dom) {
    stats.dom.style.display = "block";
  }
  if (cheeseHud) {
    cheeseHud.style.display = "block";
  }
  if (debugOverlay) {
    debugOverlay.style.display = "block";
  }
  
  // Initialize debug helpers menu (January 4, 2026)
  if (!debugHelpersMenu) {
    createDebugHelpersMenu();
    console.log("✅ [DEBUG] Debug helpers menu initialized");
  }
  
  console.log("✅ [GAME START] HUD elements shown (FPS counter, cheese HUD, debug overlay)");
  
  // Ensure character selection menu is hidden before starting game
  hideCharacterSelectionMenu();
  
  // Determine which level loading function to use based on target level
  // If a specific level is requested (GOD MODE), use the appropriate warp function
  // Otherwise, use the default Level 1 loading logic
  if (targetLevelId && targetLevelId !== LEVEL_IDS.LEVEL1) {
    // GOD MODE: Start game and immediately warp to selected level
    console.log(`🎮 [GOD MODE] Starting game and warping to ${targetLevelName}`);
    
    // First do minimal setup to get game ready
    // Then call the appropriate warp function
    const warpFnMap = {
      [LEVEL_IDS.LEVEL2]: () => warpToLevel2(),
      [LEVEL_IDS.LEVEL3]: () => warpToLevel3(),
      [LEVEL_IDS.LEVEL4]: () => warpToLevel4(),
      [LEVEL_IDS.LEVEL5]: () => warpToLevel5(),
      [LEVEL_IDS.LEVEL6]: () => warpToLevel6()
    };
    
    const warpFn = warpFnMap[targetLevelId];
    if (warpFn) {
      // Use loading screen for the warp
      warpToLevelWithLoading(targetLevelId, targetLevelName, async () => {
        // First ensure game is in a ready state (minimal Level 1 setup)
        // Load Level 1 data quickly, then immediately warp to target level
        try {
          // Phase 1: Minimal cleanup and setup
          cleanupAllLevels();
          await yieldToBrowser();
          
          // Phase 2: Load Level 1 temporarily (required for game state)
          const level1Data = await fetch(resolveAssetPath("/public/models/cheese-temple/level1.json")).then(res => res.json());
          buildLevel(level1Data);
          await yieldToBrowser();
          
          // Phase 3: Initialize player character (required before warping)
          await loadPlayerCharacter();
          console.log("✅ [GAME START] Player character loaded - ready for warp");
          
          // Phase 4: Now warp to target level
          await warpFn();
          
        } catch (error) {
          console.error(`❌ [GAME START] Error starting game for ${targetLevelName}:`, error);
          // Fallback to Level 1
          console.log("⚠️ [GAME START] Falling back to Level 1");
          const level1Data = await fetch(resolveAssetPath("/public/models/cheese-temple/level1.json")).then(res => res.json());
          buildLevel(level1Data);
          await applyLevelEnvironment(LEVEL_IDS.LEVEL1);
          await loadPlayerCharacter();
        }
      });
      return; // Exit early - don't execute Level 1 loading
    } else {
      console.error(`❌ [GAME START] Unknown level ID: ${targetLevelId}, defaulting to Level 1`);
      // Fall through to Level 1 loading by setting targetLevelId
      targetLevelId = LEVEL_IDS.LEVEL1;
    }
  }
  
  // Default Level 1 loading (or fallback from unknown level)
  if (targetLevelId === LEVEL_IDS.LEVEL1) {
    // Wrap Level 1 loading with loading screen
    warpToLevelWithLoading(LEVEL_IDS.LEVEL1, "Level 1", async () => {
    return new Promise((resolve, reject) => {
  // Load level after character selection
  console.log("🚀 [DEBUG] Starting game, fetching level1.json from /public/models/cheese-temple/level1.json");
  fetch(resolveAssetPath("/public/models/cheese-temple/level1.json"))
    .then((res) => {
      if (!res.ok) {
        console.error(`❌ [ERROR] Failed to fetch level1.json: HTTP ${res.status} ${res.statusText}`);
        throw new Error(`HTTP ${res.status}: ${res.statusText}`);
      }
      console.log("✅ [DEBUG] level1.json fetched successfully");
      return res.json();
    })
    .catch((error) => {
      console.error("❌ [ERROR] Failed to load level1.json:", error);
      console.error("🔍 [DEBUG] Error details:", {
        message: error.message,
        stack: error.stack,
        url: "/public/models/cheese-temple/level1.json",
        hostname: window.location.hostname,
        port: window.location.port,
        protocol: window.location.protocol
      });
      alert(`Failed to load level data. Please ensure the Vite dev server is running on port 5173.\n\nError: ${error.message}\n\nCheck the console for details.`);
          reject(error);
    })
    .then(async (mapData) => {
      // CRITICAL: Wait for ALL operations to complete before resolving
      // This ensures loading screen shows 100% only when everything is actually loaded
      try {
        // Phase 1: Cleanup
        cleanupAllLevels();
        await yieldToBrowser();
        
        // Phase 2: Build level
        buildLevel(mapData);
        await yieldToBrowser();
        
        // Phase 3: Initialize environment (grass + sky systems) - WAIT for completion
        // applyLevelEnvironment is async and awaits grass system initialization
        // This includes: grass generation, sky system, chest exclusion zone registration
        await applyLevelEnvironment(LEVEL_IDS.LEVEL1);
        await yieldToBrowser();
        
        // CRITICAL: Initialize shadow camera helper if enabled (January 4, 2026)
        setTimeout(() => {
          initializeShadowCameraHelperAtLevelStart();
        }, 100);
        
        // Phase 4: Additional delay to ensure grass generation and chests are fully rendered
        // Grass generation happens asynchronously, so we wait a bit for it to complete
        await new Promise(resolve => setTimeout(resolve, 500)); // 500ms for async operations
        await yieldToBrowser();
        
        // Phase 5: Final setup
        setCameraMode(0); // 0 = first-person
        hideCharacterSelectionMenu();
        
        // Start background music for Level 1
        if (backgroundMusicEnabled) {
          playBackgroundMusic(LEVEL_IDS.LEVEL1);
        }
        
        // Phase 6: Load player character model - WAIT for completion (including animations)
        // CRITICAL: Wait for character to load before resolving, so loading screen doesn't hide too early
        try {
          await loadPlayerCharacter();
          console.log("✅ [GAME START] Player character loaded and ready (all animations loaded)");
        } catch (error) {
          console.error("❌ [GAME START] Error loading player character:", error);
          // Continue anyway - don't block game start if character fails
        }
        
        // CRITICAL: Only resolve after everything is loaded (grass, sky, level built, items rendered, character loaded)
        resolve();
      } catch (error) {
        console.error("❌ [GAME START] Error during level loading:", error);
        // Still resolve to prevent hanging, but log the error
        resolve();
      }
      
      // CRITICAL: Character loading moved to Phase 6 in warp function above
      // This legacy code is now obsolete - character loads before promise resolves
      // Keeping for reference but character is already loaded
      // DO NOT load character here - it's already loaded in the warp function
      if (false) { // Disabled - character loads in warp function now
      setTimeout(() => {
        loadPlayerCharacter()
        .then((character) => {
          // Character loaded successfully
          console.log("✅ [GAME START] Player character loaded, game ready (LEGACY - should not execute)");
          
          // Final check: Ensure character selection menu is hidden
          hideCharacterSelectionMenu();
          
          // Ensure game is not paused
          if (window.isGamePaused) {
            window.isGamePaused = false;
            if (typeof togglePause === 'function') {
              togglePause(false);
            }
          }
          
          // CRITICAL: Ensure playerControls is initialized before enabling
          if (!playerControls && typeof initializePlayerControls === 'function') {
            try {
              initializePlayerControls();
              console.log("✅ [GAME START] Player controls initialized in startGame");
            } catch (error) {
              console.error("❌ [GAME START] Failed to initialize player controls:", error);
            }
          }
          
          // Enable controls
          if (playerControls && typeof playerControls.setEnabled === 'function') {
            playerControls.setEnabled(true);
            console.log("✅ [GAME START] Player controls enabled in startGame");
          } else {
            console.error("❌ [GAME START] Player controls not available:", {
              playerControls: !!playerControls,
              hasSetEnabled: playerControls && typeof playerControls.setEnabled === 'function'
            });
          }
          
          // Request pointer lock for first-person controls
          // CRITICAL: Set flag to request pointer lock on next user interaction (browser security requires user gesture)
          const currentCameraMode = typeof getCameraMode === 'function' ? getCameraMode() : (typeof cameraMode !== 'undefined' ? cameraMode : 0);
          if (currentCameraMode === 0 && playerControls && playerControls.getPointerLockControls) {
            const pointerLockControls = playerControls.getPointerLockControls();
            if (pointerLockControls && !pointerLockControls.isLocked) {
              // Set flag to request pointer lock on next user interaction
              window.needsPointerLockAfterLoad = true;
              console.log("✅ [GAME START] Pointer lock flag set in startGame - will request on next user interaction");
              
              // Also try to request immediately (might work if triggered from user gesture)
              setTimeout(() => {
                try {
                  pointerLockControls.lock();
                  console.log("✅ [GAME START] Pointer lock requested immediately in startGame");
                } catch (err) {
                  // Expected to fail - browser requires user gesture, so we use the flag instead
                  console.log("ℹ️ [GAME START] Pointer lock will be requested on next click (browser security requirement)");
                }
              }, 200);
            } else {
              window.needsPointerLockAfterLoad = false; // Clear flag if already locked
            }
          } else {
            window.needsPointerLockAfterLoad = false; // Clear flag if conditions not met
          }
        })
        .catch((err) => {
          console.error("Failed to load player character:", err);
          // Don't block game start if character fails, but ensure menu is hidden
          hideCharacterSelectionMenu();
        });
      }, 500);
      } // End of disabled legacy character loading block
    }); // Close .then((mapData) => { ... })
  }); // Close new Promise((resolve, reject) => { ... })
  }); // Close warpToLevelWithLoading arrow function
  } // Close if (targetLevelId === LEVEL_IDS.LEVEL1)
}

// Main menu will be shown after GUI system is initialized (see initializeGUISystem)


class FloatingCheese {
  constructor(options) {
    const { texture, center, roamRadius = 80, baseHeight = 6, levelId = "CHEESE_TEMPLE_LVL1", gameFieldSize = 120, waveNumber = 1, difficulty = null } = options;
    const cheeseGeometry = new THREE.BoxGeometry(3, 3, 3);
    const material = new THREE.MeshLambertMaterial({ map: texture });
    this.mesh = new THREE.Mesh(cheeseGeometry, material);
    this.mesh.castShadow = false;
    this.mesh.receiveShadow = false;
    this.center = center.clone();
    this.baseHeight = baseHeight;
    this.roamRadius = roamRadius;
    this.gameFieldSize = gameFieldSize; // Full game field size (120x120)
    this.floatPhase = Math.random() * Math.PI * 2;
    this.floatSpeed = 2.0; // Faster bobbing
    this.moveSpeed = 12; // Increased from 7 to 12 for faster movement
    this.target = this.pickNewTarget();
    this.captureRadius = 3.5;
    this.respawnCooldown = 0;
    this.cooldownTime = 1.25;
    this.levelId = levelId;
    
    // AI Agent Behavior Properties
    this.targetChangeTimer = 0;
    this.targetChangeInterval = 2.0 + Math.random() * 2.0; // Change target every 2-4 seconds
    this.dodgeDistance = 15; // Start dodging when player is within 15 units
    this.lastPlayerPosition = null;
    this.aggressiveness = 0.3; // How much it reacts to player (0-1)
    this.smartness = 0.4; // How often it picks far/opposite side targets (0-1)
    this.lastFarTargetTime = 0; // Track when we last went to far side
    
    // 🎮 MAD MODE - Fun Level One! 🧀
    this.madMode = false;
    this.madModeTimer = 0;
    this.madModeDuration = 4.0; // Mad mode lasts 4 seconds
    this.madModeCooldown = 0;
    this.madModeCooldownTime = 15.0; // Can't trigger again for 15 seconds
    this.madModeChance = 0.18; // 18% chance to trigger when conditions are met
    this.originalMaterial = material;
    this.madModePulsePhase = 0;
    
    // Wave-based properties (Level 4)
    this.waveNumber = waveNumber || 1;
    this.difficulty = difficulty;
    this.waveColor = null;
    this.waveColorName = "yellow";
    
    // Enhanced AI variables (unpredictable behavior)
    this.unpredictabilityFactor = 0.5 + Math.random() * 0.5; // 0.5-1.0 (makes behavior less predictable)
    this.lastDirectionChange = 0;
    this.directionChangeCooldown = 0.3 + Math.random() * 0.7; // 0.3-1.0 seconds
    this.speedBurstTimer = 0;
    this.speedBurstMultiplier = 1.0;
    this.heightVariationTimer = 0;
    this.targetHeightOffset = 0;
    
    // Group coordination (spread out from other cheeses)
    this.groupAvoidanceDistance = 25; // Try to stay this far from other cheeses
    this.lastGroupCheck = 0;
    this.groupCheckInterval = 0.5; // Check every 0.5 seconds
  }

  pickNewTarget(playerPosition = null) {
    let targetX, targetZ;
    const halfField = this.gameFieldSize / 2;
    const blockSize = 1; // Assuming block size is 1 unit
    const margin = blockSize * 10; // 10 unit margin from edges
    
    // Calculate boundaries relative to center (works for both Level 1 and Level 4)
    const minX = this.center.x - halfField + margin;
    const maxX = this.center.x + halfField - margin;
    const minZ = this.center.z - halfField + margin;
    const maxZ = this.center.z + halfField - margin;
    
    // SMART AI: Sometimes go to opposite side of game field
    const timeSinceLastFarTarget = Date.now() - this.lastFarTargetTime;
    const shouldGoFar = Math.random() < this.smartness || timeSinceLastFarTarget > 8000; // Go far every 8+ seconds
    
    if (shouldGoFar) {
      // Smart behavior: Go to opposite side or far corner of game field
      const currentX = this.mesh.position.x;
      const currentZ = this.mesh.position.z;
      
      // Calculate opposite side from current position relative to center
      const oppositeX = this.center.x * 2 - currentX;
      const oppositeZ = this.center.z * 2 - currentZ;
      
      // Add randomness - not exactly opposite, but far away
      const farX = oppositeX + (Math.random() - 0.5) * this.gameFieldSize * 0.3;
      const farZ = oppositeZ + (Math.random() - 0.5) * this.gameFieldSize * 0.3;
      
      // Clamp to game field boundaries (relative to center)
      targetX = Math.max(minX, Math.min(maxX, farX));
      targetZ = Math.max(minZ, Math.min(maxZ, farZ));
      
      this.lastFarTargetTime = Date.now();
    } else if (playerPosition && Math.random() < this.aggressiveness) {
      // AI Agent Logic: React to player position (teasing behavior)
      const toPlayer = new THREE.Vector3().subVectors(playerPosition, this.center);
      const playerAngle = Math.atan2(toPlayer.z, toPlayer.x);
      const playerDist = Math.min(toPlayer.length(), this.roamRadius * 0.8);
      
      // Add some randomness to angle (not directly at player)
      const angle = playerAngle + (Math.random() - 0.5) * Math.PI * 0.8; // ±72 degrees from player direction
      const distance = playerDist * (0.5 + Math.random() * 0.5); // 50-100% of distance to player
      
      targetX = this.center.x + Math.cos(angle) * distance;
      targetZ = this.center.z + Math.sin(angle) * distance;
      
      // Clamp to game field boundaries (relative to center)
      targetX = Math.max(minX, Math.min(maxX, targetX));
      targetZ = Math.max(minZ, Math.min(maxZ, targetZ));
    } else {
      // Normal random movement - use FULL game field (relative to center)
      targetX = minX + Math.random() * (maxX - minX);
      targetZ = minZ + Math.random() * (maxZ - minZ);
    }
    
    return new THREE.Vector3(
      targetX,
      this.center.y + this.baseHeight,
      targetZ
    );
  }

  update(delta, playerPosition, onCapture) {
    this.respawnCooldown = Math.max(0, this.respawnCooldown - delta);
    this.targetChangeTimer += delta;
    this.madModeCooldown = Math.max(0, this.madModeCooldown - delta);

    // 🎮 MAD MODE SYSTEM - Fun Level One! 🧀
    // Check if we should trigger mad mode (random chance + cooldown check)
    if (!this.madMode && this.madModeCooldown <= 0 && Math.random() < this.madModeChance * delta) {
      this.enterMadMode();
    }

    // Update mad mode timer
    if (this.madMode) {
      this.madModeTimer -= delta;
      this.madModePulsePhase += delta * 8; // Fast pulsing animation
      
      // Visual feedback: pulsing glow with color variants (abstract variants)
      const pulseIntensity = 0.5 + Math.sin(this.madModePulsePhase) * 0.5;
      
      // Mad mode color variants based on wave color
      let madModeColor;
      if (this.waveColor) {
        // Use wave color as base, but make it more intense
        madModeColor = this.waveColor.clone();
        madModeColor.r = Math.min(1, madModeColor.r * 1.5);
        madModeColor.g = Math.min(1, madModeColor.g * 0.8);
        madModeColor.b = Math.min(1, madModeColor.b * 0.5);
      } else {
        // Default red-orange for non-wave cheeses (Level 1)
        madModeColor = new THREE.Color(1, 0.3, 0);
      }
      
      this.mesh.material.emissive = madModeColor;
      this.mesh.material.emissiveIntensity = pulseIntensity * 1.2; // More intense in mad mode
      
      if (this.madModeTimer <= 0) {
        this.exitMadMode();
      }
    }

    // Dynamic speed system - slow down and speed up over time
    if (!this.speedPhase) this.speedPhase = Math.random() * Math.PI * 2;
    this.speedPhase += 0.3 * delta; // Slow speed cycle
    let speedVariation = 0.4 + (Math.sin(this.speedPhase) * 0.3 + 1) * 0.3; // 0.4 to 1.0 (40% to 100% speed)
    
    // MAD MODE: Much faster speed (2.5x multiplier)
    if (this.madMode) {
      speedVariation = 1.5 + Math.sin(this.madModePulsePhase * 2) * 0.5; // 1.0 to 2.0 (100% to 200% speed, very fast!)
    }
    
    // Apply speed burst multiplier (unpredictable bursts)
    const currentMoveSpeed = this.moveSpeed * speedVariation * this.speedBurstMultiplier;

    // Jump behavior - vertical jumping motion
    if (!this.jumpPhase) this.jumpPhase = Math.random() * Math.PI * 2;
    this.jumpPhase += 1.2 * delta; // Jump cycle speed
    const jumpHeight = Math.max(0, Math.sin(this.jumpPhase)) * 4.0; // Jump up to 4 units high
    const jumpBounce = Math.sin(this.jumpPhase * 2) * 0.5; // Small bounce effect

    // Faster bobbing animation (continuous)
    this.floatPhase += this.floatSpeed * delta;
    const bob = Math.sin(this.floatPhase) * 1.5;

    const current = this.mesh.position;
    const toTarget = new THREE.Vector3().subVectors(this.target, current);
    const planar = new THREE.Vector3(toTarget.x, 0, toTarget.z);
    const distance = planar.length();

    // AI Agent: Change target more frequently for erratic movement
    // MAD MODE: Change targets MUCH more frequently (every 0.3-0.8 seconds)
    const targetChangeInterval = this.madMode ? (0.3 + Math.random() * 0.5) : this.targetChangeInterval;
    const shouldChangeTarget = distance < 1.0 || this.targetChangeTimer >= targetChangeInterval;
    
    // Enhanced AI: Update timers for unpredictable behavior
    this.lastDirectionChange += delta;
    this.speedBurstTimer = Math.max(0, this.speedBurstTimer - delta);
    this.heightVariationTimer += delta;
    this.lastGroupCheck += delta;
    
    // Speed burst system (unpredictable speed bursts)
    if (this.speedBurstTimer > 0) {
      this.speedBurstMultiplier = 1.0 + (this.speedBurstTimer * 0.5); // 1.0 to 1.5x speed
    } else {
      this.speedBurstMultiplier = 1.0;
      // Random speed burst trigger (unpredictable)
      if (Math.random() < 0.01 * delta * this.unpredictabilityFactor) {
        this.speedBurstTimer = 0.3 + Math.random() * 0.4; // 0.3-0.7 second burst
      }
    }
    
    // Height variation (smart height changes)
    if (this.heightVariationTimer > 2.0) {
      this.heightVariationTimer = 0;
      // Random height offset (unpredictable)
      this.targetHeightOffset = (Math.random() - 0.5) * 4; // -2 to +2 units
    }
    
    // AI Agent: Enhanced dodge behavior with predictive dodging
    if (playerPosition && shouldChangeTarget) {
      const distToPlayer = current.distanceTo(playerPosition);
      
      // Predictive dodging: Check if player is aiming at cheese (Level 4 only)
      let isPlayerAimingAtMe = false;
      if (this.levelId === "CHEESE_TEMPLE_LEVEL4" && camera) {
        const cameraForward = new THREE.Vector3();
        camera.getWorldDirection(cameraForward);
        const toCheese = new THREE.Vector3().subVectors(current, playerPosition);
        toCheese.normalize();
        const angleToCheese = cameraForward.angleTo(toCheese);
        isPlayerAimingAtMe = angleToCheese < 0.3; // Within 30 degrees = aiming
      }
      
      // Enhanced dodge chance (higher if player is aiming)
      const baseDodgeChance = this.madMode ? 0.9 : (0.5 + this.aggressiveness * 0.3);
      const dodgeChance = isPlayerAimingAtMe ? Math.min(0.95, baseDodgeChance + 0.2) : baseDodgeChance;
      const dodgeDistanceMultiplier = this.madMode ? (0.6 + Math.random() * 0.4) : (0.4 + Math.random() * 0.3);
      
      // Group coordination: Check distance to other cheeses (Level 4 only)
      let groupAvoidanceTarget = null;
      if (this.levelId === "CHEESE_TEMPLE_LEVEL4" && this.lastGroupCheck >= this.groupCheckInterval) {
        this.lastGroupCheck = 0;
        const otherCheeses = level4State.cheeses.filter(c => 
          c !== this && c.mesh && c.mesh.visible && c.mesh.position.distanceTo(current) < this.groupAvoidanceDistance
        );
        if (otherCheeses.length > 0) {
          // Move away from other cheeses (spread out)
          const avgOtherPos = new THREE.Vector3();
          otherCheeses.forEach(c => avgOtherPos.add(c.mesh.position));
          avgOtherPos.divideScalar(otherCheeses.length);
          const awayFromGroup = new THREE.Vector3().subVectors(current, avgOtherPos);
          awayFromGroup.normalize();
          const avoidAngle = Math.atan2(awayFromGroup.z, awayFromGroup.x);
          const avoidDistance = this.groupAvoidanceDistance * 1.5;
          groupAvoidanceTarget = new THREE.Vector3(
            this.center.x + Math.cos(avoidAngle) * avoidDistance,
            this.center.y + this.baseHeight,
            this.center.z + Math.sin(avoidAngle) * avoidDistance
          );
        }
      }
      
      if (distToPlayer < this.dodgeDistance && Math.random() < dodgeChance) {
        // Enhanced dodge: Combine player avoidance with group coordination
        const awayFromPlayer = new THREE.Vector3().subVectors(current, playerPosition);
        awayFromPlayer.normalize();
        
        // Unpredictable dodge angle (makes it harder to predict)
        const unpredictableAngle = (Math.random() - 0.5) * Math.PI * (1.0 + this.unpredictabilityFactor);
        const dodgeAngle = Math.atan2(awayFromPlayer.z, awayFromPlayer.x) + unpredictableAngle;
        const dodgeDistance = this.roamRadius * dodgeDistanceMultiplier;
        
        let dodgeTarget = new THREE.Vector3(
          this.center.x + Math.cos(dodgeAngle) * dodgeDistance,
          this.center.y + this.baseHeight,
          this.center.z + Math.sin(dodgeAngle) * dodgeDistance
        );
        
        // Blend with group avoidance if needed (50% weight)
        if (groupAvoidanceTarget) {
          dodgeTarget.lerp(groupAvoidanceTarget, 0.5);
        }
        
        this.target = dodgeTarget;
      } else if (groupAvoidanceTarget && Math.random() < 0.4) {
        // Sometimes just avoid other cheeses (40% chance)
        this.target = groupAvoidanceTarget;
      } else {
        // Normal target selection with AI behavior - use full game field
        this.target = this.pickNewTarget(playerPosition);
      }
      this.targetChangeTimer = 0;
      this.targetChangeInterval = this.madMode ? (0.3 + Math.random() * 0.5) : this.targetChangeInterval;
      this.lastPlayerPosition = playerPosition ? playerPosition.clone() : null;
    } else if (shouldChangeTarget) {
      // Pick new target across whole game field
      this.target = this.pickNewTarget(playerPosition);
      this.targetChangeTimer = 0;
      this.targetChangeInterval = this.madMode ? (0.3 + Math.random() * 0.5) : this.targetChangeInterval;
    }

    // Move towards target with dynamic speed (slow down and speed up)
    if (distance > 0.1) {
      // Additional random speed variation for more erratic movement
      // MAD MODE: Even more erratic (70-130% variation)
      const randomVariation = this.madMode ? (0.7 + Math.random() * 0.6) : (0.85 + Math.random() * 0.3);
      planar.normalize().multiplyScalar(currentMoveSpeed * randomVariation * delta);
      current.add(planar);
    }

    // Enhanced vertical movement - jumping + bobbing + smart height variation
    // MAD MODE: Bigger jumps and faster bobbing
    const jumpMultiplier = this.madMode ? 1.5 : 1.0;
    const bobMultiplier = this.madMode ? 1.3 : 1.0;
    
    // Smart height variation: Fly higher when player is aiming (Level 4 only)
    let smartHeightOffset = 0;
    if (this.levelId === "CHEESE_TEMPLE_LEVEL4" && playerPosition && camera) {
      const cameraForward = new THREE.Vector3();
      camera.getWorldDirection(cameraForward);
      const toCheese = new THREE.Vector3().subVectors(current, playerPosition);
      toCheese.normalize();
      const angleToCheese = cameraForward.angleTo(toCheese);
      if (angleToCheese < 0.3) {
        // Player is aiming - fly higher (unpredictable)
        smartHeightOffset = 3 + Math.random() * 2; // 3-5 units higher
      }
    }
    
    const totalVerticalOffset = (bob * bobMultiplier) + (jumpHeight * jumpMultiplier) + (jumpBounce * jumpMultiplier) + this.targetHeightOffset + smartHeightOffset;
    current.y = this.center.y + this.baseHeight + totalVerticalOffset;
    this.mesh.position.copy(current);

    // Capture detection
    if (this.respawnCooldown <= 0 && playerPosition) {
      const distToPlayer = current.distanceTo(playerPosition);
      if (distToPlayer <= this.captureRadius) {
        this.respawnCooldown = this.cooldownTime;
        this.target = this.pickNewTarget(playerPosition);
        if (typeof onCapture === "function") {
          onCapture();
        }
      }
    }
  }

  enterMadMode() {
    this.madMode = true;
    this.madModeTimer = this.madModeDuration;
    this.madModeCooldown = this.madModeCooldownTime;
    this.madModePulsePhase = 0;
    
    // Show HUD notification
    if (typeof window.showMadModeNotification === "function") {
      window.showMadModeNotification();
    } else {
      console.log("🧀💥 MAD MODE ACTIVATED - Fun Level One!");
    }
  }

  exitMadMode() {
    this.madMode = false;
    this.madModeTimer = 0;
    
    // Reset visual effects (restore wave color if exists)
    if (this.waveColor) {
      this.mesh.material.emissive = this.waveColor.clone();
      this.mesh.material.emissiveIntensity = 0.4 + (this.waveNumber * 0.03);
    } else {
      this.mesh.material.emissive = new THREE.Color(0, 0, 0);
      this.mesh.material.emissiveIntensity = 0;
    }
    
    console.log("🧀 Mad mode ended - cheese calmed down!");
  }
}

