// 🎮 MAD MODE NOTIFICATION - Fun Level One! 🧀
window.showMadModeNotification = function() {
  // Remove any existing notification
  const existing = document.getElementById("madModeNotification");
  if (existing) existing.remove();
  
  // Create notification element (smaller, top-right corner)
  const notification = document.createElement("div");
  notification.id = "madModeNotification";
  notification.style.position = "fixed";
  notification.style.top = "20px";
  notification.style.right = "20px";
  notification.style.zIndex = "10000";
  notification.style.padding = "10px 16px";
  notification.style.background = "linear-gradient(135deg, rgba(255, 68, 68, 0.95), rgba(255, 136, 0, 0.95))";
  notification.style.border = "2px solid #ffaa00";
  notification.style.borderRadius = "8px";
  notification.style.color = "#fff";
  notification.style.fontSize = "16px";
  notification.style.fontWeight = "bold";
  notification.style.textAlign = "center";
  notification.style.boxShadow = "0 4px 12px rgba(255, 68, 68, 0.6), inset 0 0 8px rgba(255, 255, 255, 0.2)";
  notification.style.animation = "madModePulse 0.3s ease-out";
  notification.style.backdropFilter = "blur(4px)";
  notification.style.userSelect = "none";
  notification.style.pointerEvents = "none";
  notification.textContent = "🧀💥 MAD MODE! 💥🧀";
  
  // Add pulse animation (updated for top-right corner)
  // Only add style if it doesn't exist
  let styleElement = document.getElementById("madModeNotificationStyle");
  if (!styleElement) {
    styleElement = document.createElement("style");
    styleElement.id = "madModeNotificationStyle";
    styleElement.textContent = `
    @keyframes madModePulse {
        0% { transform: scale(0.8); opacity: 0; }
        50% { transform: scale(1.05); }
        100% { transform: scale(1); opacity: 1; }
    }
    @keyframes madModeFadeOut {
        0% { opacity: 1; transform: scale(1); }
        100% { opacity: 0; transform: scale(0.9); }
    }
  `;
    document.head.appendChild(styleElement);
  }
  
  document.body.appendChild(notification);
  
  // Auto-remove after 2.5 seconds with fade out (shorter duration)
  setTimeout(() => {
    notification.style.animation = "madModeFadeOut 0.4s ease-out";
    setTimeout(() => {
      if (notification.parentNode) {
        notification.parentNode.removeChild(notification);
      }
    }, 400);
  }, 2500);
};

