function refreshDebugOverlay() {
  // Use GUI System if available (it updates automatically in update(), but this ensures immediate refresh)
  if (guiSystem && typeof guiSystem.refreshDebugOverlay === 'function') {
    guiSystem.refreshDebugOverlay();
    return;
  }
  
  // Legacy fallback
  if (!debugOverlay) return;
  const envText = isProduction ? "Production" : "Local";
  const port = window.location.port || "(default)";
  const pendingText = `Pending: ${debugState.pending}`;
  const pausedText = `Paused: ${isGamePaused ? "yes" : "no"}`;
  let lastStatus = "Last: none";
  if (debugState.lastResponse) {
    const status = debugState.lastResponse.success ? "ok" : "fail";
    const detail = debugState.lastResponse.success
      ? `total=${debugState.lastResponse.total ?? "?"}`
      : debugState.lastResponse.error || debugState.lastResponse.details?.error || "error";
    lastStatus = `Last: ${status} (${detail})`;
  }
  const cameraModeText = isFirstPerson() ? "1st Person" : (isThirdPerson() ? "3rd Person" : "Joystick View");
  
  // Get player position for XYZ display (use camera position - most accurate)
  let playerPos = { x: 0, y: 0, z: 0 };
  if (camera && camera.position) {
    playerPos = { x: camera.position.x, y: camera.position.y, z: camera.position.z };
  } else if (playerCollider && playerCollider.start && playerCollider.end) {
    // Fallback to player collider center if camera not available
    const center = new THREE.Vector3().lerpVectors(playerCollider.start, playerCollider.end, 0.5);
    playerPos = { x: center.x, y: center.y, z: center.z };
  }
  const posX = playerPos.x.toFixed(2);
  const posY = playerPos.y.toFixed(2);
  const posZ = playerPos.z.toFixed(2);
  const positionText = `Position: X: ${posX} Y: ${posY} Z: ${posZ}`;
  
  // Display debug info with XYZ position on new line below
  // Using innerHTML to support line breaks (user requested position display below camera info)
  debugOverlay.innerHTML = [
    `Env: ${envText} | Host: ${window.location.hostname}:${port}`,
    `API: ${API_BASE_URL} | Session: ${cheeseSessionId.slice(0, 8)}`,
    `Camera: ${cameraModeText} | ${pausedText} | ${pendingText} | ${lastStatus}`,
    positionText
  ].join("<br>");
}

