              slider.type = "range";
              slider.min = min.toString();
              slider.max = max.toString();
              slider.step = step.toString();
              // Get current value from phoenixBoss, currentSettings, or use default
              let currentValue = defaultValue;
              if (phoenixBoss && typeof phoenixBoss.getBehaviorDuration === 'function') {
                currentValue = phoenixBoss.getBehaviorDuration(behaviorName, durationKey) || defaultValue;
              } else if (currentSettings?.behaviorDurations?.[behaviorName]?.[durationKey] !== undefined) {
                currentValue = currentSettings.behaviorDurations[behaviorName][durationKey];
              }
              slider.value = currentValue.toString();
              slider.id = `phoenixBossDuration_${behaviorName}_${durationKey}`;
              
              // IMPROVED SLIDER STYLING - Much larger and more touch-friendly
