    // Store references for god mode toggle updates
    optionsMenu._alienSpiderBossSection = alienSpiderBossCollapsible.section;

    // Helper function to update ground controls visibility based on ground type
    function updateGroundControlsVisibility(groundType) {
      const bladeCountContainer = document.getElementById("bladeCountContainer");
      const chunkedGrassContainer = document.getElementById("chunkedGrassContainer");
      const bladeLengthContainer = document.getElementById("bladeLengthContainer"); // NEW: Blade length container
      const windSpeedContainer = document.getElementById("windSpeedContainer");
      const windStrengthContainer = document.getElementById("windStrengthContainer");
      const groundColorContainer = document.getElementById("groundColorContainer");
      const undergroundTypeContainer = document.getElementById("undergroundTypeContainer");
      const undergroundColorContainer = document.getElementById("undergroundColorContainer");
      const undergroundTextureContainer = document.getElementById("undergroundTextureContainer");
      
      if (groundType === "grass") {
        if (bladeCountContainer) bladeCountContainer.style.display = "flex";
        if (chunkedGrassContainer) chunkedGrassContainer.style.display = "flex"; // PHASE 2: Show chunked grass toggle
        if (bladeLengthContainer) bladeLengthContainer.style.display = "flex";
        if (windSpeedContainer) windSpeedContainer.style.display = "flex";
        if (windStrengthContainer) windStrengthContainer.style.display = "flex";
        const windDirectionContainer = document.getElementById("windDirectionContainer");
        if (windDirectionContainer) windDirectionContainer.style.display = "flex";
        if (groundColorContainer) groundColorContainer.style.display = "none";
        if (undergroundTypeContainer) undergroundTypeContainer.style.display = "block";
        // Underground type controls are shown; visibility of color/texture depends on selection
        if (undergroundTypeContainer) {
          const typeSelect = document.getElementById("groundUndergroundType");
          const type = typeSelect ? typeSelect.value : "color";
          if (undergroundColorContainer) undergroundColorContainer.style.display = type === "color" ? "block" : "none";
          if (undergroundTextureContainer) undergroundTextureContainer.style.display = type === "texture" ? "block" : "none";
        }
      } else if (groundType === "color") {
        if (bladeCountContainer) bladeCountContainer.style.display = "none";
        if (chunkedGrassContainer) chunkedGrassContainer.style.display = "none"; // PHASE 2: Hide chunked grass toggle
        if (bladeLengthContainer) bladeLengthContainer.style.display = "none";
        if (windSpeedContainer) windSpeedContainer.style.display = "none";
        if (windStrengthContainer) windStrengthContainer.style.display = "none";
        const windDirectionContainer = document.getElementById("windDirectionContainer");
        if (windDirectionContainer) windDirectionContainer.style.display = "none";
        const windTurbulenceContainer = document.getElementById("windTurbulenceContainer");
        if (windTurbulenceContainer) windTurbulenceContainer.style.display = "none";
        const windGustFrequencyContainer = document.getElementById("windGustFrequencyContainer");
        if (windGustFrequencyContainer) windGustFrequencyContainer.style.display = "none";
        const windGustIntensityContainer = document.getElementById("windGustIntensityContainer");
        if (windGustIntensityContainer) windGustIntensityContainer.style.display = "none";
        if (groundColorContainer) groundColorContainer.style.display = "flex";
        if (undergroundTypeContainer) undergroundTypeContainer.style.display = "none";
        if (undergroundColorContainer) undergroundColorContainer.style.display = "none";
        if (undergroundTextureContainer) undergroundTextureContainer.style.display = "none";
      } else { // blank
        if (bladeCountContainer) bladeCountContainer.style.display = "none";
        if (chunkedGrassContainer) chunkedGrassContainer.style.display = "none"; // PHASE 2: Hide chunked grass toggle
        if (bladeLengthContainer) bladeLengthContainer.style.display = "none"; // Hide blade length for blank
        if (windSpeedContainer) windSpeedContainer.style.display = "none";
        if (windStrengthContainer) windStrengthContainer.style.display = "none";
        const windDirectionContainer = document.getElementById("windDirectionContainer"); // NEW: Get wind direction container
        if (windDirectionContainer) windDirectionContainer.style.display = "none"; // NEW: Hide wind direction for blank
        if (groundColorContainer) groundColorContainer.style.display = "none";
        if (undergroundTypeContainer) undergroundTypeContainer.style.display = "none";
        if (undergroundColorContainer) undergroundColorContainer.style.display = "none";
        if (undergroundTextureContainer) undergroundTextureContainer.style.display = "none";
      }
    }
    
    // Store function for later use
    optionsMenu._updateGroundControlsVisibility = updateGroundControlsVisibility;

    // Initialize ground controls with current settings
    const groundTypeSelectEl = document.getElementById("groundTypeSelect");
    const bladeCountSliderEl = document.getElementById("groundBladeCountSlider");
