    const bladeLengthSliderEl = document.getElementById("groundBladeLengthSlider");
    const bladeLengthValueEl = document.getElementById("groundBladeLengthValue");
    const windSpeedSliderEl = document.getElementById("groundWindSpeedSlider");
    const windSpeedValueEl = document.getElementById("groundWindSpeedValue");
    const windStrengthSliderEl = document.getElementById("groundWindStrengthSlider");
    const windStrengthValueEl = document.getElementById("groundWindStrengthValue");
    const windDirectionSliderEl = document.getElementById("groundWindDirectionSlider");
