    const windTurbulenceValueEl = document.getElementById("groundWindTurbulenceValue"); // NEW: Wind turbulence value
    const windGustFrequencySliderEl = document.getElementById("groundWindGustFrequencySlider"); // NEW: Wind gust frequency slider
    const windGustFrequencyValueEl = document.getElementById("groundWindGustFrequencyValue"); // NEW: Wind gust frequency value
    const windGustIntensitySliderEl = document.getElementById("groundWindGustIntensitySlider"); // NEW: Wind gust intensity slider
    const windGustIntensityValueEl = document.getElementById("groundWindGustIntensityValue"); // NEW: Wind gust intensity value
