    const undergroundTextureInputEl = document.getElementById("groundUndergroundTexturePath");

    const currentGroundSettings = getGroundConfigForLevel(currentLevel || LEVEL_IDS.LEVEL1);
    if (currentGroundSettings) {
      if (groundTypeSelectEl) groundTypeSelectEl.value = currentGroundSettings.groundType || "grass";
      if (bladeCountSliderEl && currentGroundSettings.bladeCount !== undefined) {
        bladeCountSliderEl.value = currentGroundSettings.bladeCount;
        if (bladeCountValueEl) bladeCountValueEl.textContent = currentGroundSettings.bladeCount.toLocaleString();
      }
      // NEW: Initialize blade length slider
      if (bladeLengthSliderEl) {
        const bladeLengthMultiplier = currentGroundSettings.bladeLengthMultiplier !== undefined ? currentGroundSettings.bladeLengthMultiplier : 1.0;
        bladeLengthSliderEl.value = bladeLengthMultiplier;
        if (bladeLengthValueEl) bladeLengthValueEl.textContent = bladeLengthMultiplier.toFixed(1) + "x";
        // Apply to grass system if it exists
        if (grassSystem) {
          grassSystem.setBladeLength(bladeLengthMultiplier);
        }
      }
      if (windSpeedSliderEl && currentGroundSettings.windSpeed !== undefined) {
        windSpeedSliderEl.value = currentGroundSettings.windSpeed;
        if (windSpeedValueEl) windSpeedValueEl.textContent = parseFloat(currentGroundSettings.windSpeed).toFixed(1);
      }
      if (windStrengthSliderEl && currentGroundSettings.windStrength !== undefined) {
        windStrengthSliderEl.value = currentGroundSettings.windStrength;
        if (windStrengthValueEl) windStrengthValueEl.textContent = parseFloat(currentGroundSettings.windStrength).toFixed(2);
      }
      // Initialize wind direction slider
      if (windDirectionSliderEl) {
        const windDirectionAngle = currentGroundSettings.windDirectionAngle !== undefined ? currentGroundSettings.windDirectionAngle : 0.0;
        windDirectionSliderEl.value = windDirectionAngle;
        if (windDirectionValueEl) windDirectionValueEl.textContent = Math.round(windDirectionAngle) + "°";
        if (grassSystem) {
          grassSystem.setWindDirection(windDirectionAngle);
        }
      }
      // NEW: Initialize wind turbulence slider
      if (windTurbulenceSliderEl) {
        const windTurbulence = currentGroundSettings.windTurbulence !== undefined ? currentGroundSettings.windTurbulence : 0.2;
        windTurbulenceSliderEl.value = windTurbulence;
        if (windTurbulenceValueEl) windTurbulenceValueEl.textContent = windTurbulence.toFixed(2);
        if (grassSystem) {
          grassSystem.setWindTurbulence(windTurbulence);
        }
      }
      // NEW: Initialize wind gust frequency slider
      if (windGustFrequencySliderEl) {
        const windGustFrequency = currentGroundSettings.windGustFrequency !== undefined ? currentGroundSettings.windGustFrequency : 0.5;
        windGustFrequencySliderEl.value = windGustFrequency;
        if (windGustFrequencyValueEl) windGustFrequencyValueEl.textContent = windGustFrequency.toFixed(1) + "/s";
        if (grassSystem) {
          grassSystem.setWindGustFrequency(windGustFrequency);
        }
      }
      // NEW: Initialize wind gust intensity slider
      if (windGustIntensitySliderEl) {
        const windGustIntensity = currentGroundSettings.windGustIntensity !== undefined ? currentGroundSettings.windGustIntensity : 1.5;
        windGustIntensitySliderEl.value = windGustIntensity;
        if (windGustIntensityValueEl) windGustIntensityValueEl.textContent = windGustIntensity.toFixed(1) + "x";
        if (grassSystem) {
          grassSystem.setWindGustIntensity(windGustIntensity);
        }
      }
      if (undergroundTypeSelectEl && currentGroundSettings.undergroundType) {
        undergroundTypeSelectEl.value = currentGroundSettings.undergroundType;
      }
      if (undergroundColorInputEl && currentGroundSettings.undergroundColor !== undefined) {
        undergroundColorInputEl.value = toHex(currentGroundSettings.undergroundColor);
      }
      if (undergroundTextureInputEl && currentGroundSettings.undergroundTexturePath) {
        undergroundTextureInputEl.value = currentGroundSettings.undergroundTexturePath;
      }
      updateGroundControlsVisibility(currentGroundSettings.groundType || "grass");
    }

