async function fetchPlayerDetails() {
  if (!resolvedDiscordId) {
    const refreshedId =
      window.sessionDiscordId ||
      window.localStorage.getItem("discord_id") ||
      window.localStorage.getItem("DISCORD_ID") ||
      window.localStorage.getItem("narrrfs_last_discord_id") ||
      null;
    if (refreshedId) {
      resolvedDiscordId = refreshedId;
      console.log("🔄 [DEBUG] resolvedDiscordId refreshed from localStorage:", resolvedDiscordId);
    }
  }

  // Always fetch from API, even for local test users, to get the latest balance
  // The cached balance might be outdated, especially when switching accounts
  if (autoSeededLocalIdentity) {
    console.log("🧪 [DEBUG] Using Narrrf's account for local testing - fetching balance from API");
    // Don't skip API fetch - we want the real balance from the database
  }

  console.log("🔍 [DEBUG] fetchPlayerDetails called", {
    resolvedDiscordId,
    API_BASE_URL,
    endpoint: resolvedDiscordId
      ? `${API_BASE_URL}/api/user/details.php?user_id=${encodeURIComponent(resolvedDiscordId)}`
      : `${API_BASE_URL}/api/user/details.php (session fallback)`
  });

  if (!resolvedDiscordId) {
    console.warn("⚠️ [DEBUG] No resolvedDiscordId found. Pause menu will remain in Guest mode until credentials sync via profile page.");
    updatePausePlayerInfo();
    return;
  }

  try {
    const url = resolvedDiscordId
      ? `${API_BASE_URL}/api/user/details.php?user_id=${encodeURIComponent(resolvedDiscordId)}`
      : `${API_BASE_URL}/api/user/details.php`;
    console.log("🌐 [DEBUG] Fetching player details from:", url);

    const response = await fetch(url, {
      credentials: "include",
      headers: {
        "Content-Type": "application/json",
        "Accept": "application/json"
      }
    });

    console.log("📡 [DEBUG] API Response status:", response.status, response.statusText);

    if (!response.ok) {
    throw new Error(`HTTP error! status: ${response.status}`);
    }

    const data = await response.json();
    console.log("📦 [DEBUG] API Response data:", data);

    if (data.success && data.user) {
      resolvedDiscordId = data.user.discord_id || resolvedDiscordId;
      console.log("✅ [DEBUG] resolvedDiscordId updated:", resolvedDiscordId);

      if (data.user.username) {
        playerDisplayName = data.user.username;
        console.log("✅ [DEBUG] Player name updated:", playerDisplayName);
        const subtitle = document.getElementById("pause-subtitle");
        if (subtitle) {
          subtitle.textContent = `Take a breather, ${playerDisplayName}.`;
        }
      }
      if (typeof data.user.balance === "number") {
        currentTotalDspoinc = data.user.balance;
        console.log("✅ [DEBUG] DSPOINC balance updated:", currentTotalDspoinc);
      } else {
        console.warn("⚠️ [DEBUG] Balance not a number:", data.user.balance);
      }
      updatePausePlayerInfo();
    } else {
      console.warn("⚠️ [DEBUG] API response not successful:", data);
      playerDisplayName = "Guest";
      currentTotalDspoinc = 0;
      updatePausePlayerInfo();
    }
  } catch (error) {
    console.error("❌ [DEBUG] Error fetching player details:", error);
    console.error("❌ [DEBUG] Error details:", {
      message: error.message,
      stack: error.stack,
      name: error.name
    });
    if (autoSeededLocalIdentity || !isProduction) {
      console.info("🧪 [DEBUG] Using local fallback identity after fetch failure.");
      currentTotalDspoinc =
        currentTotalDspoinc ??
        (Number.isFinite(Number(window.localStorage.getItem("narrrfs_last_ds_balance")))
          ? Number(window.localStorage.getItem("narrrfs_last_ds_balance"))
          : 0);
      updatePausePlayerInfo();
      return;
    }
    playerDisplayName = "Guest";
    currentTotalDspoinc = 0;
    updatePausePlayerInfo();
  }
}

async function showPauseMenu() {
  // Use GUI System if available
  if (guiSystem && typeof guiSystem.showPauseMenu === 'function') {
    guiSystem.showPauseMenu();
    return;
  }
  
  // Legacy fallback
  console.log("⏸️ [DEBUG] showPauseMenu called");
  const menu = getPauseMenu();
  pointerWasLockedBeforePause = playerControls ? playerControls.getPointerLockControls().isLocked : false;
  if (playerControls) {
    playerControls.getPointerLockControls().unlock();
  }
  menu.style.display = "flex";
  isGamePaused = true;
  
  // Hide mobile joysticks when paused
  if (mobileJoystick) {
    mobileJoystick.style.display = "none";
  }
  if (mobileCameraJoystick) {
    mobileCameraJoystick.style.display = "none";
  }
  
  // Fetch player details before updating the menu
  await fetchPlayerDetails();
  
  refreshDebugOverlay();
}

function hidePauseMenu() {
  // Use GUI System if available
  if (guiSystem && typeof guiSystem.hidePauseMenu === 'function') {
    guiSystem.hidePauseMenu();
    return;
  }
  
  // Legacy fallback
  if (!pauseMenu) return;
  pauseMenu.style.display = "none";
  isGamePaused = false;

  // CRITICAL: Re-apply the currently selected camera mode so HUD, joysticks, player model, and pointer-lock state
  // always match the player's last choice after resuming.
  setCameraMode(cameraMode);
  
  // CRITICAL: Ensure player model is hidden in first-person after resume
  if (isFirstPerson() && playerCharacterModel) {
    playerCharacterModel.visible = false;
    playerCharacterModel.traverse((child) => {
      if (child.isMesh) {
        child.visible = false;
      }
    });
  }
  
  // CRITICAL: Ensure weapon is visible in first-person after resume (if in Level 4)
  if (isFirstPerson() && currentLevel === LEVEL_IDS.LEVEL4 && (level4RiddleState.step1Active || level4RiddleState.step2Active)) {
    if (weaponSystem && weaponSystem.weaponViewmodel) {
      weaponSystem.weaponViewmodel.visible = true;
      weaponSystem.weaponViewmodel.traverse((child) => {
        if (child.isMesh) {
          child.visible = true;
        }
      });
    }
  }
  
  // Show mobile joysticks when unpaused (if in landscape or desktop test enabled)
  // CRITICAL: Only show joysticks if NOT in first-person mode
  const shouldShowJoysticks = (isMobile && window.innerWidth > window.innerHeight) || window.enableDesktopJoysticks || isJoystickView();
  if (shouldShowJoysticks && !isFirstPerson()) {
    // Only show joysticks in third-person or joystick view
    if (mobileJoystick) {
      mobileJoystick.style.display = "flex";
    }
    if (mobileCameraJoystick) {
      mobileCameraJoystick.style.display = "flex";
    }
  } else {
    // Hide joysticks in first-person mode
    if (mobileJoystick) {
      mobileJoystick.style.display = "none";
    }
    if (mobileCameraJoystick) {
      mobileCameraJoystick.style.display = "none";
    }
  }
  
  refreshDebugOverlay();

  const expectsPointerLock = !isMobile && !isJoystickView();
  
  // FIX: Re-request pointer lock after resume (requires user gesture)
  // Pointer lock API requires explicit user interaction, so we need to request it
  // after the user clicks or interacts with the canvas
  if (pointerWasLockedBeforePause && expectsPointerLock) {
    // Set flag to request pointer lock on next click
    window.needsPointerLockAfterPause = true;
    
    console.log("🎮 [PAUSE] Game resumed - pointer lock will be re-enabled on next click");
    
    // Try to lock immediately if user just clicked (e.g., clicked resume button)
    // This might work in some cases, but the click handler will handle it if it fails
    setTimeout(() => {
      if (window.needsPointerLockAfterPause && !isGamePaused && playerControls && !playerControls.getPointerLockControls().isLocked) {
        try {
          // Request pointer lock (might work if triggered by user interaction)
          renderer.domElement.requestPointerLock();
        } catch (e) {
          // Lock failed - will be re-requested on next click
          console.log("🎮 [PAUSE] Pointer lock requires user gesture - will lock on next click");
        }
      }
    }, 100); // Small delay to ensure pause menu is closed
  } else if (expectsPointerLock && playerControls && !playerControls.getPointerLockControls().isLocked) {
    // Even if the pointer wasn't locked before pausing, ensure we try to lock again
    // so first-person / third-person mouse look is consistent after resuming.
    window.needsPointerLockAfterPause = true;
  } else {
    window.needsPointerLockAfterPause = false;
  }
  pointerWasLockedBeforePause = false;
}

function togglePause(forceState) {
  // CRITICAL FIX: Prevent circular calls - if called from GUI System, don't call it back
  // Check if we're in a GUI System callback context (avoid infinite loop)
  if (window._togglePauseFromGUI) {
    window._togglePauseFromGUI = false;
    // This is a direct call from GUI System - just update state and handle music
    const shouldPause = typeof forceState === "boolean" ? forceState : !isGamePaused;
    isGamePaused = shouldPause;
    if (shouldPause) {
      pauseBackgroundMusic();
    } else {
      resumeBackgroundMusic();
    }
    return;
  }
  
  // Use GUI System if available (normal call path)
  if (guiSystem && typeof guiSystem.togglePause === 'function') {
    guiSystem.togglePause(forceState);
    return;
  }
  
  // Legacy fallback
  const shouldPause = typeof forceState === "boolean" ? forceState : !isGamePaused;
  isGamePaused = shouldPause;
  if (shouldPause) {
    if (!isGamePaused) {
      pauseBackgroundMusic();
      showPauseMenu();
    }
  } else {
    if (isGamePaused) {
      hidePauseMenu();
      resumeBackgroundMusic();
    }
  }
}

