function restartLevel4() {
  // CRITICAL: Cleanup ALL levels first to ensure clean state
  cleanupAllLevels();
  
  // CRITICAL: Hide Level 1 instanced meshes (they're added directly to scene, not in a group)
  // This prevents Level 1 blocks from being visible in the distance
  scene.children.forEach(child => {
    if (child instanceof THREE.InstancedMesh && child !== collisionMesh) {
      child.visible = false;
    }
  });
  
  if (!level4State.built) {
    buildLevel4FirstShotArena();
  }
  resetLevel4Progress();
  // Reset heat/overload system
  level4State.weaponHeat = 0;
  level4State.isOverheated = false;
  level4State.lastOverheatTime = 0;
  level4State.tripleShotActive = false;
  level4State.tripleShotBulletsRemaining = 0;
  currentLevel = LEVEL_IDS.LEVEL4;
  
  // CRITICAL: Ensure group is in scene before making it visible
  if (level4State.group && !scene.children.includes(level4State.group)) {
    scene.add(level4State.group);
    console.log("✅ [LEVEL 4] Added level4State.group to scene during restart");
  }
  
  if (level4State.group) {
    level4State.group.visible = true;
  }
  
  applyLevelEnvironment(LEVEL_IDS.LEVEL4);
  setPlayerFeetPosition(level4Config.spawnPosition.clone());
  // Reset camera to first-person view (no weapon, no joysticks)
  // Weapon will only load when Step 1 becomes active
  setCameraMode(0); // 0 = first-person
  ensureBackgroundMusicForCurrentLevel(true);
  showLevel4IntroToast();
  
  // CRITICAL: Restore game state after restart
  restoreGameStateAfterWarp();
  
  console.log("🔄 [LEVEL 4] Restarted The First Shot from the beginning.");
}

function hideLevel4CompletionScreen(clearFlag = true) {
  if (level4CompletionScreen && document.body.contains(level4CompletionScreen)) {
    document.body.removeChild(level4CompletionScreen);
    level4CompletionScreen = null;
  }
  if (clearFlag) {
    level4State.completionScreenShown = false;
  }
  if (isGamePaused) {
    togglePause(false);
  }
}

function handleLevel4Collisions() {
  const origin = level4Config.origin;
  const size = level4Config.size;
  const floorY = origin.y + PLAYER_RADIUS;
  const halfSize = size / 2;
  const wallY = origin.y + level4Config.wallHeight - PLAYER_RADIUS;

  // Initialize onGround to false
  onGround = false;

  // Floor collision
  const distanceToFloor = playerCollider.start.y - floorY;
  if (distanceToFloor <= 0.08 && playerVelocity.y <= 0) {
    playerCollider.start.y = floorY;
    playerCollider.end.y = floorY + PLAYER_HEIGHT;
    playerVelocity.y = Math.max(0, playerVelocity.y);
    onGround = true;
    hasDoubleJumped = false; // Reset double jump when landing
  } else if (playerCollider.start.y < floorY) {
    playerCollider.start.y = floorY;
    playerCollider.end.y = floorY + PLAYER_HEIGHT;
    playerVelocity.y = 0;
    onGround = true;
    hasDoubleJumped = false; // Reset double jump when landing
  }

  // Wall collisions (160x160 bounds)
  if (playerCollider.start.x < origin.x - halfSize) {
    playerCollider.start.x = origin.x - halfSize;
    playerCollider.end.x = origin.x - halfSize;
    playerVelocity.x = 0;
  }
  if (playerCollider.start.x > origin.x + halfSize) {
    playerCollider.start.x = origin.x + halfSize;
    playerCollider.end.x = origin.x + halfSize;
    playerVelocity.x = 0;
  }
  if (playerCollider.start.z < origin.z - halfSize) {
    playerCollider.start.z = origin.z - halfSize;
    playerCollider.end.z = origin.z - halfSize;
    playerVelocity.z = 0;
  }
  if (playerCollider.start.z > origin.z + halfSize) {
    playerCollider.start.z = origin.z + halfSize;
    playerCollider.end.z = origin.z + halfSize;
    playerVelocity.z = 0;
  }

  // Ceiling collision
  if (playerCollider.end.y > wallY) {
    playerCollider.end.y = wallY;
    playerCollider.start.y = wallY - PLAYER_HEIGHT;
    playerVelocity.y = 0;
  }
}

async function unlockLevel4Trait(traitKey, description) {
  try {
    const discordId = localStorage.getItem("discord_id") || localStorage.getItem("DISCORD_ID") || localStorage.getItem("narrrfs_last_discord_id");
    if (!discordId) {
      console.warn("🎯 [LEVEL 4] No Discord ID found, skipping trait unlock");
      return;
    }
    const response = await fetch(`${API_BASE_URL}/api/user/unlock-trait.php`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        user_id: discordId,
        trait_name: traitKey, // API expects trait_name, not trait
        trait_value: 'true',
        description: description
      })
    });
    const result = await response.json();
    if (result.success) {
      console.log(`🎯 [LEVEL 4] Trait unlocked: ${traitKey}`);
    } else {
      console.warn(`🎯 [LEVEL 4] Trait unlock failed (${traitKey}):`, result.error);
    }
  } catch (error) {
    console.error(`🎯 [LEVEL 4] Error unlocking trait (${traitKey}):`, error);
  }
}

async function awardLevel4DspoincReward(stepId, baseReward, contextLabel = "") {
  if (!resolvedDiscordId) {
    console.warn(`🎯 [LEVEL 4] Skipping DSPOINC reward (${stepId}) — no Discord ID.`);
    return;
  }
  try {
    const payload = {
      discord_id: resolvedDiscordId,
      discord_name: playerDisplayName && playerDisplayName !== "Guest" ? playerDisplayName : null,
      riddle_id: stepId,
      level_id: "CHEESE_TEMPLE_LEVEL4",
      base_reward: baseReward,
      session_id: cheeseSessionId
    };
    const response = await fetch(RIDDLE_REWARD_ENDPOINT, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      credentials: "include",
      body: JSON.stringify(payload)
    });
    const result = await response.json().catch(() => ({ success: false, error: "Invalid JSON" }));
    if (response.ok && result.success) {
      const dsPoincAwarded = result.data?.ds_poinc_awarded || 0;
      const totalDspoinc = result.data?.total_ds_poinc;
      if (typeof totalDspoinc === "number") {
        currentTotalDspoinc = totalDspoinc;
        window.localStorage.setItem("narrrfs_last_ds_balance", String(currentTotalDspoinc));
        if (isGamePaused) updatePausePlayerInfo();
      }
      showRiddleRewardNotification(dsPoincAwarded, result.data?.multiplier || 1.0);
      console.log(`🎯 [LEVEL 4] DSPOINC reward granted (${stepId})`, {
        baseReward,
        dsPoincAwarded,
        totalDspoinc,
        contextLabel
      });
    } else if (response.status === 409) {
      console.warn(`🎯 [LEVEL 4] Reward already claimed for ${stepId}`);
      showRiddleRewardNotification(0, 1.0, true);
    } else {
      console.warn(`🎯 [LEVEL 4] DSPOINC reward failed (${stepId}):`, result.error);
    }
  } catch (error) {
    console.error(`🎯 [LEVEL 4] Error awarding DSPOINC reward (${stepId}):`, error);
  }
}

let level4ProgressHUD = null;

function createLevel4ProgressHUD() {
  // Use GUI System if available
  if (guiSystem && typeof guiSystem.createLevel4ProgressHUD === 'function') {
    guiSystem.createLevel4ProgressHUD();
    return;
  }
  
  // Legacy fallback
  if (level4ProgressHUD && document.body.contains(level4ProgressHUD)) {
    return; // Already exists
  }
  
  level4ProgressHUD = document.createElement("div");
  level4ProgressHUD.id = "level4ProgressHUD";
  Object.assign(level4ProgressHUD.style, {
    position: "fixed",
    top: "20px",
    left: "50%",
    transform: "translateX(-50%)",
    background: "rgba(5, 7, 16, 0.85)",
    border: "2px solid rgba(139, 92, 246, 0.5)",
    borderRadius: "12px",
    padding: "12px 24px",
    zIndex: "1000",
    color: "#fef3c7",
    fontFamily: "Montserrat, Arial, sans-serif",
    fontSize: "18px",
    fontWeight: "600",
    textAlign: "center",
    boxShadow: "0 4px 16px rgba(0, 0, 0, 0.5)",
    display: "none" // Hidden until Step 1 starts
  });
  document.body.appendChild(level4ProgressHUD);
  updateLevel4ProgressHUD();
}

// CRITICAL: Comprehensive cleanup function for level switching
// This ensures ALL levels are properly hidden and cleaned up before switching
function cleanupAllLevels() {
  console.log("🧹 [CLEANUP] Starting comprehensive level cleanup...");
  
  // 🚨 CRITICAL PERFORMANCE FIX: Restore shadows when leaving Level 2
  // Shadows were disabled in Level 2 for performance - restore them for other levels
  if (level2State && level2State.shadowMapWasEnabled !== undefined) {
    renderer.shadowMap.enabled = level2State.shadowMapWasEnabled;
    level2State.shadowMapWasEnabled = undefined; // Reset flag
    console.log("⚡ [CLEANUP] Shadows restored to:", renderer.shadowMap.enabled);
  }
  
  // CRITICAL: Protect Level 1 collision mesh (it's needed for Level 1 and should ALWAYS be preserved)
  // Preserve it regardless of current level, since Level 1 collision mesh is created once at game start
  // Level 5 and Level 6 collision meshes have specific names, so we can distinguish them
  const isLevel5Mesh = collisionMesh && (collisionMesh.name === 'Level5_CollisionMesh' || currentLevel === LEVEL_IDS.LEVEL5);
  const isLevel6Mesh = collisionMesh && (collisionMesh.name === 'Level6_CollisionMesh' || currentLevel === LEVEL_IDS.LEVEL6);
  const level1CollisionMesh = (collisionMesh && !isLevel5Mesh && !isLevel6Mesh && collisionMesh.geometry && collisionMesh.geometry.boundsTree) ? collisionMesh : null;
  
  // 1. Hide ALL level groups
  if (level1State && level1State.group) {
    level1State.group.visible = false;
  }
  if (level2State && level2State.group) {
    level2State.group.visible = false;
  }
  if (level3State && level3State.group) {
    level3State.group.visible = false;
  }
  if (level4State && level4State.group) {
    level4State.group.visible = false;
  }
  if (level5State && level5State.group) {
    level5State.group.visible = false;
  }
  if (level6State && level6State.group) {
    level6State.group.visible = false;
  }
  
  // 2. Cleanup Level 1 trees (remove from scene and reset state)
  if (level1State) {
    // Remove trees from scene
    if (level1State.tree && level1State.tree.parent) {
      scene.remove(level1State.tree);
      level1State.tree.traverse((child) => {
        if (child.isMesh) {
          if (child.geometry) child.geometry.dispose();
          if (child.material) {
            if (Array.isArray(child.material)) {
              child.material.forEach(mat => mat.dispose());
            } else {
              child.material.dispose();
            }
          }
        }
      });
    }
    if (level1State.tree2 && level1State.tree2.parent) {
      scene.remove(level1State.tree2);
      level1State.tree2.traverse((child) => {
        if (child.isMesh) {
          if (child.geometry) child.geometry.dispose();
          if (child.material) {
            if (Array.isArray(child.material)) {
              child.material.forEach(mat => mat.dispose());
            } else {
              child.material.dispose();
            }
          }
        }
      });
    }
    if (level1State.tree3 && level1State.tree3.parent) {
      scene.remove(level1State.tree3);
      level1State.tree3.traverse((child) => {
        if (child.isMesh) {
          if (child.geometry) child.geometry.dispose();
          if (child.material) {
            if (Array.isArray(child.material)) {
              child.material.forEach(mat => mat.dispose());
            } else {
              child.material.dispose();
            }
          }
        }
      });
    }
    if (level1State.tree4 && level1State.tree4.parent) {
      scene.remove(level1State.tree4);
      level1State.tree4.traverse((child) => {
        if (child.isMesh) {
          if (child.geometry) child.geometry.dispose();
          if (child.material) {
            if (Array.isArray(child.material)) {
              child.material.forEach(mat => mat.dispose());
            } else {
              child.material.dispose();
            }
          }
        }
      });
    }
    
    // Reset tree state
    level1State.tree = null;
    level1State.tree2 = null;
    level1State.tree3 = null;
    level1State.tree4 = null;
    level1State.treePosition = null;
    level1State.tree2Position = null;
    level1State.tree3Position = null;
    level1State.tree4Position = null;
    
    // Remove and dispose of bear trap
    if (level1State.bearTrap && level1State.bearTrap.parent) {
      scene.remove(level1State.bearTrap);
      level1State.bearTrap.traverse((child) => {
        if (child.isMesh) {
          if (child.geometry) child.geometry.dispose();
          if (child.material) {
            if (Array.isArray(child.material)) {
              child.material.forEach(mat => mat.dispose());
            } else {
              child.material.dispose();
            }
          }
        }
      });
    }
    
    // Reset bear trap state
    level1State.bearTrap = null;
    level1State.bearTrapTriggered = false;
    level1State.bearTrapDeathActive = false;
    level1State.bearTrapPosition = null;
    
    // Remove and dispose of butterfly
    if (level1State.butterfly && level1State.butterfly.parent) {
      scene.remove(level1State.butterfly);
      level1State.butterfly.traverse((child) => {
        if (child.isMesh) {
          if (child.geometry) child.geometry.dispose();
          if (child.material) {
            if (Array.isArray(child.material)) {
              child.material.forEach(mat => mat.dispose());
            } else {
              child.material.dispose();
            }
          }
        }
      });
    }
    
    // Reset butterfly state
    level1State.butterfly = null;
    level1State.butterflyMixer = null;
    level1State.butterflyPatrolTimer = 0;
    butterflyWingMeshes = []; // Clear wing meshes array
    butterflyWingFlapAngle = 0; // Reset wing flap angle
    butterflyUnpredictability = 0; // Reset unpredictability
    butterflyUnpredictabilityTimer = 0; // Reset timer
    
    // Remove and dispose of plant 1 (Phormium FBX model)
    if (level1State.plant && level1State.plant.parent) {
      scene.remove(level1State.plant);
      level1State.plant.traverse((child) => {
        if (child.isMesh) {
          if (child.geometry) child.geometry.dispose();
          if (child.material) {
            if (Array.isArray(child.material)) {
              child.material.forEach(mat => mat.dispose());
            } else {
              child.material.dispose();
            }
          }
        }
      });
    }
    
    // Remove and dispose of plant 2 (Phormium FBX model - smaller)
    if (level1State.plant2 && level1State.plant2.parent) {
      scene.remove(level1State.plant2);
      level1State.plant2.traverse((child) => {
        if (child.isMesh) {
          if (child.geometry) child.geometry.dispose();
          if (child.material) {
            if (Array.isArray(child.material)) {
              child.material.forEach(mat => mat.dispose());
            } else {
              child.material.dispose();
            }
          }
        }
      });
    }
    
    // Reset plant states
    level1State.plant = null;
    level1State.plantPosition = null;
    level1State.plant2 = null;
    level1State.plant2Position = null;
  }
  
  // 3. Cleanup Chest System (clear all chests for all levels)
  // CRITICAL: Each level ONLY loads its own chests - this ensures no chests from other levels persist
  // Each warp function also explicitly clears the target level's chests before creating new ones (extra safety layer)
  if (chestSystem) {
    console.log("🗑️ [CLEANUP] Clearing all chests from all levels to ensure clean state...");
    chestSystem.clearLevel(LEVEL_IDS.LEVEL1);
    chestSystem.clearLevel(LEVEL_IDS.LEVEL2);
    chestSystem.clearLevel(LEVEL_IDS.LEVEL3);
    chestSystem.clearLevel(LEVEL_IDS.LEVEL4);
    chestSystem.clearLevel(LEVEL_IDS.LEVEL5);
    chestSystem.clearLevel(LEVEL_IDS.LEVEL6);
    console.log("✅ [CLEANUP] All levels' chests cleared");
  }
  
  // CRITICAL: Stop Level 1 chest verification interval when leaving Level 1
  if (window.level1ChestVerificationInterval) {
    clearInterval(window.level1ChestVerificationInterval);
    window.level1ChestVerificationInterval = null;
    console.log("🛑 [CLEANUP] Stopped Level 1 chest verification interval");
  }
  
  // 4. Cleanup Level 4 specific items (HUD, weapons, bullets, particles, monsters)
  cleanupLevel4HUD();
  removeLevel4WeaponViewmodel();
  
  // CRITICAL: Hide weapon system weaponViewmodel for levels without weapons (Level 2, 3, etc.) (January 4, 2026)
  // This ensures weapon HUD/weapon models from Level 3/4 don't persist when warping to Level 2
  if (weaponSystem && weaponSystem.weaponViewmodel) {
    weaponSystem.weaponViewmodel.visible = false;
    // Also remove from camera if it's attached
    if (camera && camera.children.includes(weaponSystem.weaponViewmodel)) {
      camera.remove(weaponSystem.weaponViewmodel);
      console.log("🔫 [CLEANUP] Removed weapon system weaponViewmodel from camera (Level 2 doesn't have weapons)");
    }
    console.log("🔫 [CLEANUP] Hidden weapon system weaponViewmodel (Level 2 doesn't have weapons)");
  }
  
  // Clean up all Level 4 bullets
  if (level4Bullets && level4Bullets.length > 0) {
    level4Bullets.forEach(bullet => {
      if (bullet.mesh && bullet.mesh.parent) {
        scene.remove(bullet.mesh);
        if (bullet.mesh.geometry) bullet.mesh.geometry.dispose();
        if (bullet.mesh.material) bullet.mesh.material.dispose();
      }
    });
    level4Bullets.length = 0;
  }
  
  // Clean up Level 4 explosion particles
  if (level4State && level4State.explosionParticles) {
    level4State.explosionParticles.forEach(particle => {
      if (particle.mesh && particle.mesh.parent) {
        scene.remove(particle.mesh);
        if (particle.mesh.geometry) particle.mesh.geometry.dispose();
        if (particle.mesh.material) particle.mesh.material.dispose();
      }
    });
    level4State.explosionParticles = [];
  }
  
  // Clean up Level 4 monster projectiles
  if (level4State && level4State.monsterProjectiles) {
    level4State.monsterProjectiles.forEach(projectile => {
      if (projectile.mesh && projectile.mesh.parent) {
        scene.remove(projectile.mesh);
        if (projectile.mesh.geometry) projectile.mesh.geometry.dispose();
        if (projectile.mesh.material) projectile.mesh.material.dispose();
      }
    });
    level4State.monsterProjectiles = [];
  }
  
  // 3. Hide floating cheese (Level 1)
  if (floatingCheese && floatingCheese.mesh) {
    floatingCheese.mesh.visible = false;
  }
  
  // 4. Hide riddle progress UI
  if (typeof riddleProgressUI !== "undefined" && riddleProgressUI) {
    riddleProgressUI.style.display = "none";
  }
  
  // 5. Hide any completion screens
  if (level1CompletionScreen && document.body.contains(level1CompletionScreen)) {
    document.body.removeChild(level1CompletionScreen);
    level1CompletionScreen = null;
  }
  if (level3CompletionScreen && document.body.contains(level3CompletionScreen)) {
    document.body.removeChild(level3CompletionScreen);
    level3CompletionScreen = null;
  }
  if (level4CompletionScreen && document.body.contains(level4CompletionScreen)) {
    document.body.removeChild(level4CompletionScreen);
    level4CompletionScreen = null;
  }
  
  // CRITICAL: Ensure Level 1 collision mesh remains in scene (it's needed for Level 1)
  // The collision mesh is created once at game start and should persist
  // Restore Level 1 collision mesh if it was preserved
  if (level1CollisionMesh) {
    collisionMesh = level1CollisionMesh;
    if (!scene.children.includes(collisionMesh)) {
      console.log("🔧 [CLEANUP] Re-adding Level 1 collision mesh to scene");
      scene.add(collisionMesh);
    }
    // Verify collision mesh has valid geometry and boundsTree
    if (!collisionMesh.geometry || !collisionMesh.geometry.boundsTree) {
      console.error("❌ [CLEANUP] Level 1 collision mesh exists but has invalid geometry! This should not happen.");
    } else {
      console.log("✅ [CLEANUP] Level 1 collision mesh preserved:", {
        inScene: scene.children.includes(collisionMesh),
        hasGeometry: !!collisionMesh.geometry,
        hasBoundsTree: !!collisionMesh.geometry?.boundsTree,
        geometryVertices: collisionMesh.geometry?.attributes?.position?.count || 0
      });
    }
  } else if (collisionMesh && currentLevel === LEVEL_IDS.LEVEL1 && !scene.children.includes(collisionMesh)) {
    console.log("🔧 [CLEANUP] Re-adding Level 1 collision mesh to scene");
    scene.add(collisionMesh);
  }
  
  // 8. Dispose of Grass System (CRITICAL: Prevent double grass systems)
  if (grassSystem) {
    try {
      grassSystem.dispose();
      grassSystem = null;
      console.log("🧹 [CLEANUP] Grass system disposed.");
    } catch (error) {
      console.error("❌ [CLEANUP] Error disposing grass system:", error);
      grassSystem = null; // Force null even if dispose fails
    }
  }
  
  // 9. Hide Level 6 Boss HUD elements (Phoenix and Alien Spider health bars)
  // CRITICAL: Hide boss health bars when switching away from Level 6 (January 4, 2026)
  if (guiSystem) {
    if (guiSystem.hideBossHealthBar) {
      guiSystem.hideBossHealthBar();
      console.log("🧹 [CLEANUP] Boss health bar hidden");
    }
    if (guiSystem.hidePhoenixBehaviorDisplay) {
      guiSystem.hidePhoenixBehaviorDisplay();
      console.log("🧹 [CLEANUP] Phoenix behavior display hidden");
    }
  }
  
  console.log("✅ [CLEANUP] Comprehensive level cleanup complete");
}

function cleanupLevel4HUD() {
  // Remove progress HUD
  if (level4ProgressHUD && document.body.contains(level4ProgressHUD)) {
    document.body.removeChild(level4ProgressHUD);
    level4ProgressHUD = null;
  }
  // Remove weapon viewmodel
  removeLevel4WeaponViewmodel();
  // Remove wave countdown if it exists
  const countdownElement = document.getElementById('level4-wave-countdown');
  if (countdownElement && countdownElement.parentNode) {
    countdownElement.parentNode.removeChild(countdownElement);
  }
}

function updateLevel4ProgressHUD() {
  // Use GUI System if available
  if (guiSystem && typeof guiSystem.updateLevel4ProgressHUD === 'function') {
    guiSystem.updateLevel4ProgressHUD();
    return;
  }
  
  // Legacy fallback
  if (!level4ProgressHUD) {
    createLevel4ProgressHUD();
  }
  
  // Calculate heat percentage and status (same for both cheese and monster waves)
  const heatPercentage = Math.round((level4State.weaponHeat / level4State.maxHeat) * 100);
  const heatColor = level4State.isOverheated 
    ? "#ef4444" // Red when overheated
    : heatPercentage >= 80 
      ? "#f59e0b" // Orange at 80%+
      : heatPercentage >= 50
        ? "#eab308" // Yellow at 50%+
        : "#22c55e"; // Green when cool
  const heatStatus = level4State.isOverheated 
    ? "OVERHEATED!" 
    : heatPercentage >= 80 
      ? "CRITICAL" 
      : heatPercentage >= 50
        ? "WARNING"
        : "NORMAL";
  
  // Weapon slot information (same for both)
  const currentSlot = level4State.currentWeaponSlot;
  const weaponInfo = LEVEL4_WEAPON_SLOTS[currentSlot];
  const weaponName = weaponInfo ? weaponInfo.name : "Unknown";
  
  if (level4RiddleState.step1Active) {
    // Cheese waves progress
    const progress = level4RiddleState.cheesesCaught;
    const total = LEVEL4_CHEESES_TO_CATCH;
    const percentage = Math.floor((progress / total) * 100);
    
    // Wave information
    const isFinalWave = level4RiddleState.currentWave > LEVEL4_WAVES_COUNT;
    const waveText = isFinalWave ? "FINAL WAVE" : `Wave ${level4RiddleState.currentWave}/${LEVEL4_WAVES_COUNT + 1}`;
    const cheesesInWave = level4RiddleState.cheesesInCurrentWave;
    const cheesesNeededForWave = isFinalWave ? LEVEL4_FINAL_WAVE_CHEESES : LEVEL4_CHEESES_PER_WAVE;
    
    // Get wave color for display
    const difficulty = calculateLevel4WaveDifficulty(level4RiddleState.currentWave);
    const colorHex = `#${difficulty.color.getHexString()}`;
    
    level4ProgressHUD.innerHTML = `
      <div style="font-size: 14px; color: ${colorHex}; margin-bottom: 4px; font-weight: bold;">${waveText}</div>
      <div style="font-size: 12px; color: rgba(255,255,255,0.8); margin-bottom: 4px;">Wave Progress: ${cheesesInWave}/${cheesesNeededForWave}</div>
      <div style="font-size: 16px; margin-bottom: 6px;">🔫 Cheeses Shot: ${progress}/${total} (${percentage}%)</div>
      <div style="font-size: 12px; color: rgba(255,224,102,0.9); border-top: 1px solid rgba(255,224,102,0.3); padding-top: 6px; margin-top: 6px;">
        <div style="margin-bottom: 2px;">Weapon: <span style="color: #ffe066; font-weight: bold;">${weaponName}</span> (Slot ${currentSlot})</div>
        <div style="font-size: 10px; color: rgba(255,255,255,0.6); margin-bottom: 4px;">Press number keys (1-9) to switch weapons</div>
        <div style="margin-top: 4px; padding-top: 4px; border-top: 1px solid rgba(255,255,255,0.2);">
          <div style="font-size: 11px; color: ${heatColor}; font-weight: bold; margin-bottom: 2px;">
            🔥 Heat: ${Math.round(level4State.weaponHeat)}/${level4State.maxHeat} (${heatPercentage}%) - ${heatStatus}
          </div>
          <div style="width: 100%; height: 4px; background: rgba(0,0,0,0.3); border-radius: 2px; overflow: hidden; margin-top: 2px;">
            <div style="width: ${heatPercentage}%; height: 100%; background: ${heatColor}; transition: width 0.1s ease;"></div>
          </div>
        </div>
      </div>
    `;
    level4ProgressHUD.style.display = "block";
  } else if (level4RiddleState.step2Active) {
    // NEW: Monster waves progress
    const progress = level4RiddleState.monstersDefeated;
    const total = LEVEL4_TOTAL_MONSTERS;
    const percentage = Math.floor((progress / total) * 100);
    
    // Monster wave information
    const isFinalWave = level4RiddleState.currentMonsterWave > LEVEL4_MONSTER_WAVES_COUNT;
    const waveText = isFinalWave ? "FINAL BOSS WAVE" : `Monster Wave ${level4RiddleState.currentMonsterWave}/${LEVEL4_MONSTER_WAVES_COUNT + 1}`;
    const monstersInWave = level4RiddleState.monstersInCurrentWave;
    const monstersNeededForWave = LEVEL4_MONSTERS_PER_WAVE; // Always 3
    
    // Color for monster waves (red/orange theme)
    const colorHex = isFinalWave ? "#ff0000" : "#ff3300";
    
    level4ProgressHUD.innerHTML = `
      <div style="font-size: 14px; color: ${colorHex}; margin-bottom: 4px; font-weight: bold;">${waveText}</div>
      <div style="font-size: 12px; color: rgba(255,255,255,0.8); margin-bottom: 4px;">Wave Progress: ${monstersInWave}/${monstersNeededForWave}</div>
      <div style="font-size: 16px; margin-bottom: 6px;">🐉 Monsters Defeated: ${progress}/${total} (${percentage}%)</div>
      <div style="font-size: 12px; color: rgba(255,224,102,0.9); border-top: 1px solid rgba(255,224,102,0.3); padding-top: 6px; margin-top: 6px;">
        <div style="margin-bottom: 2px;">Weapon: <span style="color: #ffe066; font-weight: bold;">${weaponName}</span> (Slot ${currentSlot})</div>
        <div style="font-size: 10px; color: rgba(255,255,255,0.6); margin-bottom: 4px;">Press number keys (1-9) to switch weapons</div>
        <div style="margin-top: 4px; padding-top: 4px; border-top: 1px solid rgba(255,255,255,0.2);">
          <div style="font-size: 11px; color: ${heatColor}; font-weight: bold; margin-bottom: 2px;">
            🔥 Heat: ${Math.round(level4State.weaponHeat)}/${level4State.maxHeat} (${heatPercentage}%) - ${heatStatus}
          </div>
          <div style="width: 100%; height: 4px; background: rgba(0,0,0,0.3); border-radius: 2px; overflow: hidden; margin-top: 2px;">
            <div style="width: ${heatPercentage}%; height: 100%; background: ${heatColor}; transition: width 0.1s ease;"></div>
          </div>
        </div>
      </div>
    `;
    level4ProgressHUD.style.display = "block";
  } else {
    level4ProgressHUD.style.display = "none";
  }
}

function showLevel4IntroToast() {
  if (level4State.introShown) return;
  level4State.introShown = true;
  if (level4State.introToastElement && document.body.contains(level4State.introToastElement)) {
    document.body.removeChild(level4State.introToastElement);
  }
  level4State.introToastElement = showRiddleToast(
    `The First Shot — Find the hidden stone to begin.`,
    { id: "level4_intro", duration: 7000 }
  );
}

async function warpToLevel4() {
  if (currentLevel === LEVEL_IDS.LEVEL4) return;
  
  await warpToLevelWithLoading(LEVEL_IDS.LEVEL4, "Level 4", async () => {
  // CRITICAL: Cleanup ALL levels first to ensure clean state
  cleanupAllLevels();
  
  // CRITICAL: Hide Level 1 instanced meshes (they're added directly to scene, not in a group)
  // This prevents Level 1 blocks from being visible in the distance
  scene.children.forEach(child => {
    if (child instanceof THREE.InstancedMesh && child !== collisionMesh) {
      child.visible = false;
    }
  });
  
  if (!level4State.built) {
    buildLevel4FirstShotArena();
  } else {
    // CRITICAL: Recreate chests when warping back to an already-built level (January 4, 2026)
    // cleanupAllLevels() clears all chests, so we must recreate them even if level is already built
    console.log("🎁 [LEVEL 4] Level already built, recreating chests after cleanup...");
    setTimeout(async () => {
      // Load opened chests from database before creating chests
      if (resolvedDiscordId && chestSystem) {
        console.log("📥 [LEVEL 4] Loading opened chests from database...");
        await chestSystem.loadOpenedChests(resolvedDiscordId, API_BASE_URL);
      }
      // CRITICAL: Explicitly clear Level 4 chests before creating (extra safety layer)
      if (chestSystem) {
        chestSystem.clearLevel(LEVEL_IDS.LEVEL4);
      }
      createLevel4Chests();
    }, 100);
  }
  resetLevel4Progress();
  // Reset heat/overload system (same as restart for consistency)
  level4State.weaponHeat = 0;
  level4State.isOverheated = false;
  level4State.lastOverheatTime = 0;
  level4State.tripleShotActive = false;
  level4State.tripleShotBulletsRemaining = 0;
  currentLevel = LEVEL_IDS.LEVEL4;
  
  // CRITICAL: Ensure group is in scene before making it visible
  if (level4State.group && !scene.children.includes(level4State.group)) {
    scene.add(level4State.group);
    console.log("✅ [LEVEL 4] Added level4State.group to scene during warp");
  }
  
  if (level4State.group) {
    level4State.group.visible = true;
  }
  
  // CRITICAL: Await environment initialization (grass + sky systems)
  await applyLevelEnvironment(LEVEL_IDS.LEVEL4);
  
  // CRITICAL: Ensure sky system is visible after environment is applied
  if (skySystem) {
    skySystem.setVisible(true);
    console.log("🌌 [LEVEL 4] Sky system visibility ensured");
  }
  
  // CRITICAL: Initialize shadow camera helper if enabled (January 4, 2026)
  setTimeout(() => {
    initializeShadowCameraHelperAtLevelStart();
  }, 100);
  
  setPlayerFeetPosition(level4Config.spawnPosition.clone());
  
  // CRITICAL: Set camera to first-person view for weapon system
  setCameraMode(0); // 0 = first-person
  // Wait a frame for camera mode to apply
  await new Promise(resolve => setTimeout(resolve, 50));
  
  // CRITICAL: Load weapon system at Level 4 start (not just Step 1)
  // Both weapon slots should be available from the beginning
  // Slot 1: Pistol Mk I (for cheese hunting)
  // Slot 2: SF13 Sci-Fi Pistol (for monsters - triple shot)
  if (weaponSystem && typeof weaponSystem.loadWeapon === 'function') {
    console.log("🔫 [LEVEL 4] Initializing weapon system at Level 4 start...");
    
    // Load slot 1 (active weapon) - CRITICAL: Use await to ensure it loads
    console.log("🔫 [LEVEL 4] Loading weapon slot 1 (active)...");
    try {
      await weaponSystem.loadWeapon(1, null, false); // false = active weapon
      console.log("✅ [LEVEL 4] Weapon slot 1 loaded and active");
      
      // Preload slot 2 (SF13) in background so it's ready when needed
      console.log("🔫 [LEVEL 4] Preloading weapon slot 2 (SF13)...");
      weaponSystem.loadWeapon(2, null, true).then((weapon) => { // true = preload only
        if (weapon) {
          console.log("✅ [LEVEL 4] Weapon slot 2 preloaded successfully (cached, not attached)");
        } else {
          console.warn("⚠️ [LEVEL 4] Weapon slot 2 preload returned null");
        }
      }).catch(err => {
        console.error("❌ [LEVEL 4] Failed to preload weapon slot 2:", err);
      });
      console.log("✅ [LEVEL 4] Both weapon slots loading initiated (Slot 1 active, Slot 2 preloading)");
    } catch (err) {
      console.error("❌ [LEVEL 4] Failed to load weapon slot 1:", err);
    }
  } else if (typeof loadLevel4WeaponViewmodel === 'function') {
    // Legacy fallback
    console.log("🔫 [LEVEL 4] Using legacy weapon loading...");
    await loadLevel4WeaponViewmodel(null, 1);
    // Preload slot 2
    loadLevel4WeaponViewmodel(null, 2).catch(err => {
      console.warn("⚠️ [LEVEL 4] Failed to preload weapon slot 2:", err);
    });
  }
  
  // CRITICAL: Verify weapon is properly attached after loading
  if (weaponSystem && weaponSystem.weaponViewmodel) {
    await new Promise(resolve => setTimeout(resolve, 100)); // Wait for weapon to fully load
    const weapon = weaponSystem.weaponViewmodel;
    if (weaponSystem.camera && !weaponSystem.camera.children.includes(weapon)) {
      console.warn("⚠️ [LEVEL 4] Weapon not attached to camera, reattaching...");
      weaponSystem.camera.add(weapon);
    }
    weapon.visible = true;
    weapon.traverse((child) => {
      if (child.isMesh) {
        child.visible = true;
      }
    });
    console.log("✅ [LEVEL 4] Weapon attachment verified");
  }
  
  // CRITICAL: Request pointer lock for shooting (if not already locked and not in joystick view)
  if (playerControls && !playerControls.getPointerLockControls().isLocked && !isJoystickView() && !isGamePaused) {
    try {
      playerControls.getPointerLockControls().lock();
      console.log("🎯 [LEVEL 4] Pointer lock automatically requested at Level 4 start");
    } catch (err) {
      console.warn("⚠️ [LEVEL 4] Failed to request pointer lock:", err);
    }
  }
  
  // CRITICAL: Create HUD for Level 4 (will be updated when Step 1 starts)
  if (!level4ProgressHUD) {
    createLevel4ProgressHUD();
  }
  updateLevel4WeaponHUD();
  
  ensureBackgroundMusicForCurrentLevel(true);
  showLevel4IntroToast();
  
  // CRITICAL: Restore game state after warp
  restoreGameStateAfterWarp();
    
    // CRITICAL: After restoreGameStateAfterWarp(), ensure weapon is still attached and visible
    // (restoreGameStateAfterWarp() calls setCameraMode which might have removed the weapon)
    if (weaponSystem && isFirstPerson()) {
      await new Promise(resolve => setTimeout(resolve, 100)); // Wait a frame
      
      // If weapon viewmodel exists, verify and re-attach if needed
      if (weaponSystem.weaponViewmodel) {
        const weapon = weaponSystem.weaponViewmodel;
        if (!camera.children.includes(weapon)) {
          console.warn("⚠️ [LEVEL 4] Weapon was removed by restoreGameStateAfterWarp()! Re-attaching...");
          camera.add(weapon);
          weaponSystem.camera = camera; // Sync camera reference
        }
        weapon.visible = true;
        weapon.traverse((child) => {
          if (child.isMesh) {
            child.visible = true;
            // CRITICAL: Ensure material is visible
            if (child.material) {
              const mat = Array.isArray(child.material) ? child.material[0] : child.material;
              if (mat) {
                mat.visible = true;
                mat.transparent = false;
                mat.opacity = 1.0;
                mat.needsUpdate = true;
              }
            }
          }
        });
        // Re-apply transforms to ensure correct position
        if (weaponSystem._applyWeaponTransforms) {
          weaponSystem._applyWeaponTransforms(weapon, weaponSystem.getCurrentSlot() || 1);
        }
        console.log("✅ [LEVEL 4] Weapon re-attached and visible after restoreGameStateAfterWarp()", {
          weaponVisible: weapon.visible,
          isInCamera: camera.children.includes(weapon),
          position: weapon.position.toArray().map(n => n.toFixed(2))
        });
      } else {
        // Weapon was lost - reload it
        console.warn("⚠️ [LEVEL 4] Weapon viewmodel was lost! Reloading...");
        const currentSlot = weaponSystem.getCurrentSlot() || 1;
        try {
          await weaponSystem.loadWeapon(currentSlot, null, false);
          console.log("✅ [LEVEL 4] Weapon reloaded successfully");
        } catch (err) {
          console.error("❌ [LEVEL 4] Failed to reload weapon:", err);
        }
      }
    }
  
  console.log("🎯 [LEVEL 4] Warped to The First Shot arena. Weapons loaded and ready!");
  });
}

// Level 5 "The Walk" - Warp function
async function warpToLevel5() {
  await warpToLevelWithLoading(LEVEL_IDS.LEVEL5, "Level 5", async () => {
  console.log("🚶 [LEVEL 5] Warping to 'The Walk'...");
  
  // CRITICAL: Cleanup ALL levels first to ensure clean state
  cleanupAllLevels();
  
  // SIMPLIFIED: Hide EVERYTHING except Level 5 map and essential objects
  // Only show the Klagenfurt map - hide all other game elements
  let hiddenCount = 0;
  scene.children.forEach(child => {
    // Skip essential objects: camera, lights, Level 5 group, collision mesh, player character
    // CRITICAL: Also protect sky system components
    const isSkybox = child === skySystem?.skybox;
    const isClouds = child === skySystem?.clouds;
    const isStars = child === skySystem?.stars;
    const isSun = child === skySystem?.skybox?.sun;
    const isSunTarget = child === skySystem?.skybox?.sun?.target;
    
    if (child === camera || 
        child === collisionMesh ||
        child === level5State.group ||
        child === playerCharacterModel ||
        child === playerModel ||
        child.type === 'AmbientLight' ||
        child.type === 'DirectionalLight' ||
        child.type === 'HemisphereLight' ||
        child === sun ||
        isSkybox ||
        isClouds ||
        isStars ||
        isSun ||
        isSunTarget) {
      return; // Keep these visible
    }
    
    // Hide EVERYTHING else (Level 1, 2, 3, 4 objects, etc.)
    if (child.visible !== false) {
      child.visible = false;
      hiddenCount++;
    }
  });
  
  // Hide Level 1 riddle objects (cleanupAllLevels already hid level groups, but Level 1 uses scene directly)
  if (typeof riddleState !== 'undefined') {
    if (riddleState.triggerBlock && riddleState.triggerBlock.visible !== undefined) {
      riddleState.triggerBlock.visible = false;
    }
    if (riddleState.unlockableBlock && riddleState.unlockableBlock.visible !== undefined) {
      riddleState.unlockableBlock.visible = false;
    }
    if (riddleState.riddle4 && riddleState.riddle4.slevers) {
      riddleState.riddle4.slevers.forEach(slever => {
        if (slever && slever.mesh) {
          slever.mesh.visible = false;
        }
      });
    }
    if (riddleState.riddle3 && riddleState.riddle3.lever && riddleState.riddle3.lever.mesh) {
      riddleState.riddle3.lever.mesh.visible = false;
    }
  }
  
  console.log(`👁️ [LEVEL 5] Hidden ${hiddenCount} objects - only Klagenfurt map will be visible`);
  
  // Build Level 5 if not built - AWAIT the async function!
  if (!level5State.built) {
    console.log("📦 [LEVEL 5] Building level (first time)...");
    await buildLevel5TheWalk();
    console.log("✅ [LEVEL 5] Level build complete!");
  } else {
    // CRITICAL: Recreate chests when warping back to an already-built level (January 4, 2026)
    // cleanupAllLevels() clears all chests, so we must recreate them even if level is already built
    console.log("🎁 [LEVEL 5] Level already built, recreating chests after cleanup...");
    setTimeout(async () => {
      // Load opened chests from database before creating chests
      if (resolvedDiscordId && chestSystem) {
        console.log("📥 [LEVEL 5] Loading opened chests from database...");
        await chestSystem.loadOpenedChests(resolvedDiscordId, API_BASE_URL);
      }
      // CRITICAL: Explicitly clear Level 5 chests before creating (extra safety layer)
      if (chestSystem) {
        chestSystem.clearLevel(LEVEL_IDS.LEVEL5);
      }
      createLevel5Chests();
    }, 100);
  }
  
  // CRITICAL: Ensure group is in scene before making it visible
  if (!level5State.group) {
    console.error("❌ [LEVEL 5] Level 5 group is null!");
    return;
  }
  
  if (!scene.children.includes(level5State.group)) {
    scene.add(level5State.group);
    console.log("✅ [LEVEL 5] Added level5State.group to scene during warp");
  }
  
  level5State.group.visible = true;
  console.log("👁️ [LEVEL 5] Level 5 group is now visible");
  
  // Set current level BEFORE applying environment
  currentLevel = LEVEL_IDS.LEVEL5;
  console.log("🎯 [LEVEL 5] Current level set to:", currentLevel);
  
  // CRITICAL: Reset Level 5 riddle progress
  resetLevel5Progress();
  
  // CRITICAL: Await environment initialization (grass + sky systems)
  await applyLevelEnvironment(LEVEL_IDS.LEVEL5);
  
  // CRITICAL: Ensure sky system is visible after environment is applied
  if (skySystem) {
    skySystem.setVisible(true);
    console.log("🌌 [LEVEL 5] Sky system visibility ensured");
  }
  
  // CRITICAL: Initialize shadow camera helper if enabled (January 4, 2026)
  setTimeout(() => {
    initializeShadowCameraHelperAtLevelStart();
  }, 100);
  
  // FIX: Update grass system position to match detected ground level
  // This must happen AFTER applyLevelEnvironment initializes the grass system
  if (level5State.spawnPosition && grassSystem && grassSystem.groundMesh) {
    const groundY = level5State.spawnPosition.y; // This is the detected ground level (top surface)
    const currentPos = grassSystem.groundMesh.position;
    
    // Update both mesh position and options.position for consistency
    grassSystem.groundMesh.position.set(currentPos.x, groundY, currentPos.z);
    if (grassSystem.options) {
      grassSystem.options.position.y = groundY;
    }
    
    console.log(`🌱 [LEVEL 5] Updated grass position to ground level: Y=${groundY.toFixed(2)} (was ${currentPos.y.toFixed(2)})`);
    console.log(`🌱 [LEVEL 5] Grass mesh position:`, {
      x: grassSystem.groundMesh.position.x.toFixed(2),
      y: grassSystem.groundMesh.position.y.toFixed(2),
      z: grassSystem.groundMesh.position.z.toFixed(2)
    });
  } else if (level5State.spawnPosition) {
    console.warn(`⚠️ [LEVEL 5] Could not update grass position:`, {
      hasSpawnPosition: !!level5State.spawnPosition,
      spawnY: level5State.spawnPosition.y,
      hasGrassSystem: !!grassSystem,
      hasGroundMesh: !!(grassSystem && grassSystem.groundMesh),
      groundMeshType: grassSystem?.groundMesh?.userData?.isGrassMesh ? 'grass' : 'other'
    });
  }
  
  // Load background music
  loadBackgroundMusic(LEVEL_IDS.LEVEL5);
  
  // Position player at spawn
  if (level5State.spawnPosition) {
    setPlayerFeetPosition(level5State.spawnPosition.clone());
    console.log("📍 [LEVEL 5] Player positioned at:", level5State.spawnPosition);
    
    // Verify collision mesh is ready after positioning
    if (collisionMesh && collisionMesh.geometry && collisionMesh.geometry.boundsTree) {
      console.log("✅ [LEVEL 5] Collision mesh verified and ready for collision detection");
    } else {
      console.warn("⚠️ [LEVEL 5] Collision mesh not ready - ground/wall collision may not work!", {
        collisionMesh: !!collisionMesh,
        hasGeometry: !!collisionMesh?.geometry,
        hasBoundsTree: !!collisionMesh?.geometry?.boundsTree,
        meshName: collisionMesh?.name
      });
    }
  } else {
    console.warn("⚠️ [LEVEL 5] Spawn position not set, using default");
    setPlayerFeetPosition(new THREE.Vector3(0, 5, 0));
  }
  
  // CRITICAL: Set camera to first-person view for weapon system
  setCameraMode(0); // 0 = first-person
  // CRITICAL: Ensure cameraMode variable is set before restoreGameStateAfterWarp() is called
  // Wait a frame for camera mode to apply
  await new Promise(resolve => setTimeout(resolve, 50));
  
  // CRITICAL: Load weapon system at Level 5 start (both slots available from beginning)
  // Slot 1: Pistol Mk I (yellow bullets)
  // Slot 2: SF13 Sci-Fi Pistol (purple triple-shot)
  if (weaponSystem && typeof weaponSystem.loadWeapon === 'function') {
    console.log("🔫 [LEVEL 5] Initializing weapon system at Level 5 start...");
    
    // Load slot 1 (active weapon) - CRITICAL: Use await to ensure it loads
    console.log("🔫 [LEVEL 5] Loading weapon slot 1 (active)...");
    try {
      const loadedWeapon = await weaponSystem.loadWeapon(1, null, false); // false = active weapon
      console.log("✅ [LEVEL 5] Weapon slot 1 loaded and active");
      
      // CRITICAL: Verify weapon is attached and visible
      if (loadedWeapon && weaponSystem.weaponViewmodel) {
        if (!camera.children.includes(weaponSystem.weaponViewmodel)) {
          console.warn("⚠️ [LEVEL 5] Weapon loaded but not attached to camera! Re-attaching...");
          camera.add(weaponSystem.weaponViewmodel);
        }
        weaponSystem.weaponViewmodel.visible = true;
        weaponSystem.weaponViewmodel.traverse((child) => {
          if (child.isMesh) {
            child.visible = true;
          }
        });
        console.log("✅ [LEVEL 5] Weapon slot 1 verified and visible");
      }
      
      // Preload slot 2 (SF13) in background so it's ready when needed
      console.log("🔫 [LEVEL 5] Preloading weapon slot 2 (SF13)...");
      weaponSystem.loadWeapon(2, null, true).then((weapon) => { // true = preload only
        if (weapon) {
          console.log("✅ [LEVEL 5] Weapon slot 2 preloaded successfully (cached, not attached)");
        } else {
          console.warn("⚠️ [LEVEL 5] Weapon slot 2 preload returned null");
        }
      }).catch(err => {
        console.error("❌ [LEVEL 5] Failed to preload weapon slot 2:", err);
      });
      console.log("✅ [LEVEL 5] Both weapon slots loading initiated (Slot 1 active, Slot 2 preloading)");
    } catch (err) {
      console.error("❌ [LEVEL 5] Failed to load weapon slot 1:", err);
    }
  }
  
  // CRITICAL: Request pointer lock for shooting (if not already locked and not in joystick view)
  if (playerControls && !playerControls.getPointerLockControls().isLocked && !isJoystickView() && !isGamePaused) {
    try {
      playerControls.getPointerLockControls().lock();
      console.log("🎯 [LEVEL 5] Pointer lock automatically requested at Level 5 start");
    } catch (err) {
      console.warn("⚠️ [LEVEL 5] Failed to request pointer lock:", err);
    }
  }
  
  // CRITICAL: Restore game state after warp (this will call setCameraMode again, but cameraMode is already 0)
  // CRITICAL: Ensure cameraMode is set to first-person before calling restoreGameStateAfterWarp()
  restoreGameStateAfterWarp();
  
  // CRITICAL: After restoreGameStateAfterWarp(), ensure weapon is still attached and visible
  // (restoreGameStateAfterWarp() calls setCameraMode which might have removed the weapon)
  if (weaponSystem && isFirstPerson()) {
    await new Promise(resolve => setTimeout(resolve, 100)); // Wait a frame
    
    // If weapon viewmodel exists, verify and re-attach if needed
    if (weaponSystem.weaponViewmodel) {
      const weapon = weaponSystem.weaponViewmodel;
      if (!camera.children.includes(weapon)) {
      console.warn("⚠️ [LEVEL 5] Weapon was removed by restoreGameStateAfterWarp()! Re-attaching...");
        camera.add(weapon);
        weaponSystem.camera = camera; // Sync camera reference
    }
      weapon.visible = true;
      weapon.traverse((child) => {
      if (child.isMesh) {
        child.visible = true;
          // CRITICAL: Ensure material is visible
          if (child.material) {
            const mat = Array.isArray(child.material) ? child.material[0] : child.material;
            if (mat) {
              mat.visible = true;
              mat.transparent = false;
              mat.opacity = 1.0;
              mat.needsUpdate = true;
            }
          }
        }
      });
      // Re-apply transforms to ensure correct position
      if (weaponSystem._applyWeaponTransforms) {
        weaponSystem._applyWeaponTransforms(weapon, weaponSystem.getCurrentSlot() || 1);
      }
      console.log("✅ [LEVEL 5] Weapon re-attached and visible after restoreGameStateAfterWarp()", {
        weaponVisible: weapon.visible,
        isInCamera: camera.children.includes(weapon),
        position: weapon.position.toArray().map(n => n.toFixed(2))
      });
    } else {
      // Weapon was lost - reload it
      console.warn("⚠️ [LEVEL 5] Weapon viewmodel was lost! Reloading...");
      const currentSlot = weaponSystem.getCurrentSlot() || 1;
      try {
        await weaponSystem.loadWeapon(currentSlot, null, false);
        console.log("✅ [LEVEL 5] Weapon reloaded successfully");
      } catch (err) {
        console.error("❌ [LEVEL 5] Failed to reload weapon:", err);
      }
    }
  }
  
  // NOTE: Phoenix boss removed from Level 5 - now only in Level 6 (Phoenix Boss Arena)
  // Level 5 is now a clean level with all modules activated but no boss
  
  console.log("✅ [LEVEL 5] Warped to 'The Walk'. Weapons loaded and ready!");
  });
}

