function activateLevel3Portal() {
  if (level3State.portalActive || level3State.completionScreenShown) {
    console.log("🏹 [LEVEL 3] Portal already active or completion screen shown, skipping activation");
    return;
  }
  
  console.log("🏹 [LEVEL 3] Creating/activating portal at:", level3Config.portalPosition);
  
  // Create portal if it doesn't exist
  if (!level3State.portal) {
    const portalTexture = loadTexture(resolveAssetPath("textures/blocks/Portal1.png"));
    // Make portal bigger for easier visibility and entry
    const portalGeometry = new THREE.PlaneGeometry(6, 8);
    // Use MeshLambertMaterial like Level 1 portal (no blue emissive - shows original texture)
    const portalMaterial = new THREE.MeshLambertMaterial({
      map: portalTexture,
      side: THREE.DoubleSide,
      transparent: true,
      emissive: new THREE.Color(0x000000),
      emissiveIntensity: 0.0
    });
    const portal = new THREE.Mesh(portalGeometry, portalMaterial);
    portal.position.set(
      level3Config.portalPosition.x,
      level3Config.portalPosition.y,
      level3Config.portalPosition.z
    );
    // Portal rotation matches Level 1 portal style
    portal.rotation.y = Math.PI; // Face backwards (standard portal orientation)
    portal.visible = true; // Make sure it's visible when created
    level3State.group.add(portal);
    level3State.portal = portal;
    console.log("🏹 [LEVEL 3] Portal created and added to scene at:", portal.position);
  } else {
    console.log("🏹 [LEVEL 3] Portal already exists, making it visible");
  }
  
  level3State.portal.visible = true;
  level3State.portalActive = true;
  
  // Ensure level group is visible
  if (!level3State.group.visible) {
    level3State.group.visible = true;
    console.log("🏹 [LEVEL 3] Level group was hidden, making it visible");
  }
  
  // Ensure portal is in the scene and visible
  if (!level3State.group.children.includes(level3State.portal)) {
    level3State.group.add(level3State.portal);
    console.log("🏹 [LEVEL 3] Portal re-added to scene");
  }
  
  console.log("🏹 [LEVEL 3] Portal activated! Position:", level3State.portal.position, "Visible:", level3State.portal.visible, "Group visible:", level3State.group.visible);
  
  // Portal is active - completion screen will show when player approaches
  showRiddleToast("Portal activated! Approach it to continue.", { 
    id: "level3_portal_activated", 
    duration: 4000 
  });
}

