function handleLevel3Collisions() {
  const origin = level3Config.origin;
  const size = level3Config.size;
  const floorY = origin.y + PLAYER_RADIUS;
  const halfSize = size / 2;
  const minX = origin.x - halfSize;
  const maxX = origin.x + halfSize;
  const minZ = origin.z - halfSize;
  const maxZ = origin.z + halfSize;
  
  if (playerCollider.start.y < floorY) {
    playerCollider.start.y = floorY;
    playerCollider.end.y = floorY + PLAYER_HEIGHT;
    playerVelocity.y = 0;
    onGround = true;
    hasDoubleJumped = false; // Reset double jump when landing
  }
  
  const prevX = playerCollider.start.x;
  const clampedX = THREE.MathUtils.clamp(playerCollider.start.x, minX, maxX);
  playerCollider.start.x = clampedX;
  playerCollider.end.x = clampedX;
  if (prevX !== clampedX) {
    playerVelocity.x = 0;
  }
  
  const prevZ = playerCollider.start.z;
  const clampedZ = THREE.MathUtils.clamp(playerCollider.start.z, minZ, maxZ);
  playerCollider.start.z = clampedZ;
  playerCollider.end.z = clampedZ;
  if (prevZ !== clampedZ) {
    playerVelocity.z = 0;
  }
  
  if (playerCollider.start.y < floorY - 10) {
    playerCollider.start.y = floorY;
    playerCollider.end.y = floorY + PLAYER_HEIGHT;
    playerVelocity.y = 0;
  }

  // OPTIMIZATION: Only check walls near the player (reduces collision checks by ~80%)
  // This dramatically improves performance by skipping distant walls
  if (level3State.movingWalls && level3State.movingWalls.length > 0) {
    const playerPos = playerCollider.start;
    const collisionCheckRadius = 30; // Only check walls within 30 units of player
    
    level3State.movingWalls.forEach((wall) => {
      // Quick distance check - skip walls that are far away
      const dx = wall.position.x - playerPos.x;
      const dz = wall.position.z - playerPos.z;
      const distanceSq = dx * dx + dz * dz;
      
      // Only check collision for nearby walls
      if (distanceSq < collisionCheckRadius * collisionCheckRadius) {
        resolvePlayerAgainstLevel3Wall(wall);
      }
    });
  }
}

function resolvePlayerAgainstLevel3Wall(wall) {
  if (!wall || !wall.userData) return;
  const px = playerCollider.start.x;
  const pz = playerCollider.start.z;
  const halfWidth = (wall.userData.halfWidth || 0) + PLAYER_RADIUS;
  const halfDepth = (wall.userData.halfDepth || 0) + PLAYER_RADIUS;
  const minX = wall.position.x - halfWidth;
  const maxX = wall.position.x + halfWidth;
  const minZ = wall.position.z - halfDepth;
  const maxZ = wall.position.z + halfDepth;

  const insideX = px >= minX && px <= maxX;
  const insideZ = pz >= minZ && pz <= maxZ;
  if (!insideX || !insideZ) return;

  const distLeft = Math.abs(px - minX);
  const distRight = Math.abs(maxX - px);
  const distBack = Math.abs(pz - minZ);
  const distFront = Math.abs(maxZ - pz);
  const minDist = Math.min(distLeft, distRight, distBack, distFront);

  if (minDist === distLeft) {
    playerCollider.start.x = minX;
    playerCollider.end.x = minX;
    if (playerVelocity.x > 0) playerVelocity.x = 0;
  } else if (minDist === distRight) {
    playerCollider.start.x = maxX;
    playerCollider.end.x = maxX;
    if (playerVelocity.x < 0) playerVelocity.x = 0;
  } else if (minDist === distBack) {
    playerCollider.start.z = minZ;
    playerCollider.end.z = minZ;
    if (playerVelocity.z > 0) playerVelocity.z = 0;
  } else {
    playerCollider.start.z = maxZ;
    playerCollider.end.z = maxZ;
    if (playerVelocity.z < 0) playerVelocity.z = 0;
  }
}

async function unlockLevel3Trait(traitName, contextLabel = "") {
  if (!traitName) return;
  if (!resolvedDiscordId) {
    console.warn(`🧩 [LEVEL 3] Trait ${traitName} skipped (no Discord ID)`);
    return;
  }
  try {
    const response = await fetch(`${API_BASE_URL}/api/user/unlock-trait.php`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        user_id: resolvedDiscordId,
        trait_name: traitName,
        trait_value: "true"
      })
    });
    const result = await response.json();
    if (result.success) {
      console.log(`🧩 [LEVEL 3] Trait unlocked (${traitName})`, contextLabel);
      if (traitName === LEVEL3_STEP0_TRAIT) level3RiddleState.step0TraitUnlocked = true;
    } else {
      console.warn(`🧩 [LEVEL 3] Trait unlock failed (${traitName}):`, result.error);
    }
  } catch (error) {
    console.error(`🧩 [LEVEL 3] Error unlocking trait (${traitName}):`, error);
  }
}

async function awardLevel3DspoincReward(stepId, baseReward, contextLabel = "") {
  if (!resolvedDiscordId) {
    console.warn(`🧀 [LEVEL 3] Skipping DSPOINC reward (${stepId}) — no Discord ID.`);
    return;
  }
  try {
    const payload = {
      discord_id: resolvedDiscordId,
      discord_name: playerDisplayName && playerDisplayName !== "Guest" ? playerDisplayName : null,
      riddle_id: stepId,
      level_id: "CHEESE_TEMPLE_LEVEL3",
      base_reward: baseReward,
      session_id: cheeseSessionId
    };
    const response = await fetch(RIDDLE_REWARD_ENDPOINT, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      credentials: "include",
      body: JSON.stringify(payload)
    });
    const result = await response.json().catch(() => ({ success: false, error: "Invalid JSON" }));
    if (response.ok && result.success) {
      const dsPoincAwarded = result.data?.ds_poinc_awarded || 0;
      const totalDspoinc = result.data?.total_ds_poinc;
      if (typeof totalDspoinc === "number") {
        currentTotalDspoinc = totalDspoinc;
        window.localStorage.setItem("narrrfs_last_ds_balance", String(currentTotalDspoinc));
        if (isGamePaused) updatePausePlayerInfo();
      }
      showRiddleRewardNotification(dsPoincAwarded, result.data?.multiplier || 1.0);
      console.log(`🧀 [LEVEL 3] DSPOINC reward granted (${stepId})`, {
        baseReward,
        dsPoincAwarded,
        totalDspoinc,
        contextLabel
      });
    } else if (response.status === 409) {
      console.warn(`🧀 [LEVEL 3] Reward already claimed for ${stepId}`);
      showRiddleRewardNotification(0, 1.0, true);
    } else {
      console.warn(`🧀 [LEVEL 3] DSPOINC reward failed (${stepId}):`, result.error);
    }
  } catch (error) {
    console.error(`🧀 [LEVEL 3] Error awarding DSPOINC reward (${stepId}):`, error);
  }
}

function showLevel3IntroToast() {
  if (level3State.introShown) return;
  level3State.introShown = true;
  if (level3State.introToastElement && document.body.contains(level3State.introToastElement)) {
    document.body.removeChild(level3State.introToastElement);
  }
  level3State.introToastElement = showRiddleToast(
    `The Hunt for the Cheese Monsters — Find the hidden stone to begin. Hunt 5 monsters in Step 1, then 5 more in Step 2!`,
    { id: "level3_intro", duration: 7000 }
  );
}

async function warpToLevel3() {
  if (currentLevel === LEVEL_IDS.LEVEL3) {
    console.log("⚠️ [LEVEL 3] Already in Level 3, skipping warp");
    return;
  }
  
  await warpToLevelWithLoading(LEVEL_IDS.LEVEL3, "Level 3", async () => {
  console.log("🚀 [LEVEL 3] Starting warp to Level 3...");
  
  try {
    // CRITICAL: Cleanup ALL levels first to ensure clean state
    cleanupAllLevels();
    console.log("✅ [LEVEL 3] Cleanup complete");
    
    // CRITICAL: Hide Level 1 instanced meshes (they're added directly to scene, not in a group)
    // This prevents Level 1 blocks from being visible in the distance
    scene.children.forEach(child => {
      if (child instanceof THREE.InstancedMesh && child !== collisionMesh) {
        child.visible = false;
      }
    });
    
    // Hide game over screen if showing (same as restart)
    hideLevel3GameOverScreen();
    
    // Build level if not already built
    if (!level3State.built) {
      console.log("🔨 [LEVEL 3] Building Level 3 arena...");
      try {
        buildLevel3HuntArena();
        console.log("✅ [LEVEL 3] Arena built successfully, built flag:", level3State.built);
      } catch (buildError) {
        console.error("❌ [LEVEL 3] CRITICAL ERROR building arena:", buildError);
        throw buildError; // Re-throw to prevent continuing with broken level
      }
    } else {
      console.log("✅ [LEVEL 3] Arena already built, skipping build");
      // CRITICAL: Recreate chests when warping back to an already-built level (January 4, 2026)
      // cleanupAllLevels() clears all chests, so we must recreate them even if level is already built
      console.log("🎁 [LEVEL 3] Level already built, recreating chests after cleanup...");
      setTimeout(async () => {
        // Load opened chests from database before creating chests
        if (resolvedDiscordId && chestSystem) {
          console.log("📥 [LEVEL 3] Loading opened chests from database...");
          await chestSystem.loadOpenedChests(resolvedDiscordId, API_BASE_URL);
        }
        // CRITICAL: Explicitly clear Level 3 chests before creating (extra safety layer)
        if (chestSystem) {
          chestSystem.clearLevel(LEVEL_IDS.LEVEL3);
        }
        createLevel3Chests();
      }, 100);
    }
    
    // Verify level was built successfully
    if (!level3State.built) {
      console.error("❌ [LEVEL 3] Level 3 was not built successfully! Attempting to rebuild...");
      level3State.built = false; // Force rebuild
      buildLevel3HuntArena();
      if (!level3State.built) {
        console.error("❌ [LEVEL 3] CRITICAL: Failed to build Level 3 after retry!");
        return; // Exit if still not built
      }
    }
    
    resetLevel3Progress();
    currentLevel = LEVEL_IDS.LEVEL3;
    console.log("✅ [LEVEL 3] Current level set to LEVEL3");
    
    // CRITICAL: Ensure group is in scene before making it visible
    if (!scene.children.includes(level3State.group)) {
      scene.add(level3State.group);
      console.log("✅ [LEVEL 3] Added level3State.group to scene during warp");
    }
    
    // Verify group exists
    if (!level3State.group) {
      console.error("❌ [LEVEL 3] CRITICAL: level3State.group is missing!");
      return;
    }
    
    level3State.group.visible = true;
    console.log("✅ [LEVEL 3] Group made visible");
    
    // CRITICAL: Await environment initialization (grass + sky systems)
    await applyLevelEnvironment(LEVEL_IDS.LEVEL3);
    
    // CRITICAL: Ensure sky system is visible after environment is applied
    if (skySystem) {
      skySystem.setVisible(true);
      console.log("🌌 [LEVEL 3] Sky system visibility ensured");
    }
    
    // CRITICAL: Initialize shadow camera helper if enabled (January 4, 2026)
    setTimeout(() => {
      initializeShadowCameraHelperAtLevelStart();
    }, 100);
    
    setPlayerFeetPosition(level3Config.spawnPosition.clone());
    // Reset camera to first-person view (no weapon, no joysticks)
    setCameraMode(0); // 0 = first-person
  ensureBackgroundMusicForCurrentLevel(true);
  showLevel3IntroToast();
  const totalMonsters = LEVEL3_MONSTERS_PER_STEP * 2; // 10 total monsters (5 in Step 1 + 5 in Step 2)
  console.log(`🏹 [LEVEL 3] Entered THE HUNT. Find the hidden cheese stone to begin hunting ${totalMonsters} monsters!`);
  
  // CRITICAL: Restore game state after restart
  restoreGameStateAfterWarp();
  
  console.log("✅ [LEVEL 3] Restart complete!");
  } catch (error) {
    console.error("❌ [LEVEL 3] CRITICAL ERROR during warp:", error);
    console.error("❌ [LEVEL 3] Error stack:", error.stack);
  }
  });
}

function createLevel2TriggerBlock() {
    const blockSize = 1;
  const geometry = new THREE.BoxGeometry(blockSize, blockSize, blockSize);
  const texture = loadTexture(resolveAssetPath("textures/blocks/yellow-cheese.png"));
  const material = new THREE.MeshLambertMaterial({
    map: texture,
    emissive: new THREE.Color(0xffe066),
    emissiveIntensity: 0.25
  });
  const block = new THREE.Mesh(geometry, material);
  block.scale.set(1.4, 0.35, 1.4);
  
  // Position block so its top is at floor level (origin.y = 0)
  // Block height = 0.35 (scaled), so center should be at 0.35/2 = 0.175
  // Position slightly above floor so texture is visible: center at 0.2, top at 0.375
  const blockHeight = blockSize * 0.35; // Scaled height = 0.35
  const floorY = level2Config.origin.y; // Floor is at y: 0
  const blockCenterY = floorY + (blockHeight / 2) + 0.05; // Center at 0.225, top at 0.4 (slightly above floor)
  
  block.position.set(level2Config.origin.x - 12, blockCenterY, level2Config.origin.z - 22);
  block.castShadow = false;
  block.receiveShadow = false;
  block.visible = false; // collider only; visualStone handles presentation
  block.userData.isLevel2Trigger = true;
  level2State.group.add(block);
  level2RiddleState.triggerBlock = block;

  const visualMaterial = material.clone();
  const visualStone = new THREE.Mesh(geometry.clone(), visualMaterial);
  visualStone.scale.copy(block.scale);
  visualStone.position.copy(block.position);
  visualStone.castShadow = false;
  visualStone.receiveShadow = false;
  visualStone.visible = true;
  visualStone.userData.restY = visualStone.position.y;
  visualStone.userData.pressedY = visualStone.position.y - 0.2;
  visualStone.userData.lerpSpeed = 6;
  level2State.group.add(visualStone);
  level2RiddleState.triggerBlockVisual = visualStone;
  level2RiddleState.triggerBlockTargetY = visualStone.position.y;
  
  console.log("✅ [LEVEL 2] Trigger block and visual stone created");
}

