// ============================================================================
// RIDDLE FUNCTIONS - Level 1 Riddle System
// ============================================================================

function createTriggerBlock(mapData, blockSize) {
  console.log("🧩 [RIDDLE] createTriggerBlock called with blockSize:", blockSize);
  
  // Position: HIDDEN LOCATION - far corner behind centered platform, requires exploration
  // Level is 120x120, spawn is at x: 60, z: 15, y: 2
  // Center platform is around x: 60, z: 60
  // Place trigger block in a far corner behind the centered platform - very hidden
  // Use x: 20, z: 100 (far corner, behind platform, requires significant exploration)
  // This position is in a corner area, far from spawn, hidden behind structures
  const triggerX = 20 * blockSize + blockSize / 2; // Far corner - behind centered platform (x: 60)
  
  // Ground level calculation:
  // Ground blocks are at y: 0 in map data, so their center is at 0 * blockSize + blockSize/2 = 0.5
  // Block top is at center + blockSize/2 = 0.5 + 0.5 = 1.0 (ground level)
  // We want the trigger block to be SLIGHTLY ABOVE GROUND LEVEL so texture is visible
  // Block is scaled 1.5x, so actual height is 1.5 units
  // Block center at y: 0.35, top at y: 1.1 (slightly above floor at y: 1.0)
  // This ensures the texture is visible and not hidden by the floor
  const floorTopY = 0 * blockSize + blockSize; // Floor top = 1.0 (y: 0 block center 0.5 + half height 0.5)
  const blockScale = 1.5; // Block is scaled 1.5x for MASSIVE visibility
  // Position block slightly ABOVE floor so texture is visible (tiny bit above)
  const blockHeight = blockSize * blockScale; // Actual block height = 1.5
  const triggerY = floorTopY - (blockHeight / 2) + 0.1; // Block center at y: 0.35, top at y: 1.1 (slightly above floor)
  
  const triggerZ = 100 * blockSize + blockSize / 2; // Far corner - behind centered platform (z: 15, platform at z: 60)
  
  console.log("🧩 [RIDDLE] Creating trigger block at position:", { x: triggerX, y: triggerY, z: triggerZ });
  
  const blockGeometry = new THREE.BoxGeometry(blockSize, blockSize, blockSize);
  
  // FIXED: Use resolveAssetPath for texture loading
  const blockTexture = loadTexture(resolveAssetPath("textures/blocks/yellow-cheese.png"));
  console.log("🧩 [RIDDLE] Loading yellow-cheese.png texture:", blockTexture ? "✅ Loaded" : "❌ Failed");
  
  // Use yellow-cheese texture - show texture correctly without yellow overlay
  // FIX: Remove emissive to show texture correctly (emissive will be added dynamically for pulsing)
  const blockMaterial = new THREE.MeshStandardMaterial({ 
    map: blockTexture, // yellow-cheese.png texture
    color: 0xffffff, // White color to show texture properly (not yellow tint)
    // FIX: Remove emissive from base material - emissive will be added dynamically for pulsing glow
    emissive: new THREE.Color(0x000000), // Black (no base glow)
    emissiveIntensity: 0.0, // No base emissive - texture shows correctly
    transparent: false,
    roughness: 0.5, // Slight roughness for texture visibility
    metalness: 0.0 // Not metallic
  });
  
  // Make block MASSIVELY visible - 1.5x larger with yellow-cheese.png texture
  // Player can stand on it naturally when block top is at y: 1.0 (ground level, same as floor)
  const block = new THREE.Mesh(blockGeometry, blockMaterial);
  
  // Verify texture after block creation
  if (blockTexture) {
    console.log("🧩 [RIDDLE] ✅ yellow-cheese.png texture applied to block material");
    console.log("🧩 [RIDDLE] Texture details:", {
      image: blockTexture.image ? "✅ Has image" : "❌ No image",
      width: blockTexture.image?.width,
      height: blockTexture.image?.height,
      needsUpdate: blockTexture.needsUpdate
    });
  } else {
    console.warn("🧩 [RIDDLE] ⚠️ Block texture is null - using fallback color");
  }
  block.scale.set(1.5, 1.5, 1.5); // 50% larger for MASSIVE visibility
  block.position.set(triggerX, triggerY, triggerZ);
  block.visible = true; // MUST be visible - players need to see it to find it
  block.castShadow = false;
  block.receiveShadow = false;
  
  // Make sure it's not being culled
  block.frustumCulled = false;
  
  // Also make sure it renders on top
  block.renderOrder = 999;
  
  // Add userData to identify this block
  block.userData.isRiddleTrigger = true;
  block.userData.riddleId = 'CHEESE_TEMPLE_RIDDLE_01';
  block.userData.triggerStep = 0;
  
  // Ensure the block is added to the scene and visible
  block.matrixAutoUpdate = true;
  block.updateMatrix();
  
  // CRITICAL: Ensure block is added to scene (this is the collider)
  scene.add(block);
  riddleState.triggerBlock = block;
  block.visible = false; // Hide collider block (we'll use visual clone)
  
  // Visual clone for animation (same pattern as Level 2, 3, 4)
  const visualMaterial = blockMaterial.clone();
  const visualBlock = new THREE.Mesh(blockGeometry.clone(), visualMaterial);
  visualBlock.scale.copy(block.scale);
  visualBlock.position.copy(block.position);
  visualBlock.userData.restY = visualBlock.position.y;
  visualBlock.userData.pressedY = visualBlock.position.y - 0.3; // Sink 0.3 units when pressed (increased from 0.2 for better visibility)
  
  // Force visibility settings
  visualBlock.castShadow = false;
  visualBlock.receiveShadow = false;
  visualBlock.frustumCulled = false; // Ensure it's always rendered
  visualBlock.renderOrder = 999; // Render on top
  
  console.log("🧩 [RIDDLE] Visual block created with animation data:", {
    restY: visualBlock.userData.restY.toFixed(3),
    pressedY: visualBlock.userData.pressedY.toFixed(3),
    currentY: visualBlock.position.y.toFixed(3),
    sinkAmount: 0.3,
    lerpSpeed: visualBlock.userData.lerpSpeed,
    visible: visualBlock.visible,
    inScene: scene.children.includes(visualBlock)
  });
  visualBlock.userData.lerpSpeed = 6;
  scene.add(visualBlock);
  riddleState.triggerBlockVisual = visualBlock;
  riddleState.triggerBlockTargetY = visualBlock.userData.restY;
  
  // Force visibility - make absolutely sure visual is visible
  visualBlock.visible = true;
  
  // Force visibility check
  console.log("🧩 [RIDDLE] Hidden trigger block created at:", {
    x: triggerX.toFixed(2),
    y: triggerY.toFixed(2),
    z: triggerZ.toFixed(2),
    texture: "yellow-cheese.png",
    colliderVisible: block.visible,
    visualVisible: visualBlock.visible,
    colliderInScene: scene.children.includes(block),
    visualInScene: scene.children.includes(visualBlock),
    position: { x: block.position.x, y: block.position.y, z: block.position.z },
    visualPosition: { x: visualBlock.position.x, y: visualBlock.position.y, z: visualBlock.position.z },
    material: block.material ? "exists" : "missing",
    geometry: block.geometry ? "exists" : "missing",
    materialMap: block.material?.map ? "exists" : "missing"
  });
  
  // Double-check visibility after a short delay
  setTimeout(() => {
    if (riddleState.triggerBlock && riddleState.triggerBlockVisual) {
      // Ensure visual is visible, collider is hidden
      riddleState.triggerBlock.visible = false;
      riddleState.triggerBlockVisual.visible = true;
      
      // Make sure both are still in the scene
      if (!scene.children.includes(riddleState.triggerBlock)) {
        scene.add(riddleState.triggerBlock);
      }
      if (!scene.children.includes(riddleState.triggerBlockVisual)) {
        scene.add(riddleState.triggerBlockVisual);
      }
      
      console.log("🧩 [RIDDLE] Trigger block visibility verified:", {
        colliderVisible: riddleState.triggerBlock.visible,
        visualVisible: riddleState.triggerBlockVisual.visible,
        colliderInScene: scene.children.includes(riddleState.triggerBlock),
        visualInScene: scene.children.includes(riddleState.triggerBlockVisual)
      });
    } else {
      console.error("🧩 [RIDDLE ERROR] Trigger block or visual is null after creation!");
    }
  }, 100);
  
  // Also check in the next frame
  requestAnimationFrame(() => {
    if (riddleState.triggerBlock && riddleState.triggerBlockVisual) {
      riddleState.triggerBlock.visible = false;
      riddleState.triggerBlockVisual.visible = true;
      if (!scene.children.includes(riddleState.triggerBlock)) {
        scene.add(riddleState.triggerBlock);
      }
      if (!scene.children.includes(riddleState.triggerBlockVisual)) {
        scene.add(riddleState.triggerBlockVisual);
      }
    }
  });
  
  // Debug log for hidden block location
  console.log("🧩 [RIDDLE] Hidden trigger block created at coordinates:", {
    x: triggerX,
    y: triggerY,
    z: triggerZ,
    "Navigate to": "Far corner behind centered platform (x: 20, z: 100) - requires significant exploration",
    "Spawn location": "x: 60, z: 15, y: 2",
    "Center platform": "Approx x: 60, z: 60",
    "Distance from spawn": `~${Math.sqrt(Math.pow(20-60, 2) + Math.pow(100-15, 2)).toFixed(1)} units`,
    "Location": "Far corner area, behind centered platform, hidden in corner"
  });
}

function createUnlockableBlock(spawnData, blockSize) {
  // Position: HIDDEN LOCATION - far from spawn and center, players must explore to find it
  // Place it at x: 100, z: 100 (far from spawn, different from trigger block at 110, 110)
  // Height: One block above ground (y: 2) so it's visible but hidden in the back
  const blockX = 100 * blockSize + blockSize / 2; // Far from spawn = 100.5
  const blockY = 2 * blockSize + blockSize / 2; // One block above ground = 2.5 (top at y: 3.0)
  const blockZ = 100 * blockSize + blockSize / 2; // Far from spawn = 100.5
  
  // Debug: Log spawn and calculated positions
  console.log("🧩 [RIDDLE] Creating unlockable block:", {
    spawnData: { x: spawnData.x, y: spawnData.y, z: spawnData.z },
    calculatedPosition: { x: blockX, y: blockY, z: blockZ },
    blockSize: blockSize
  });
  
  const blockGeometry = new THREE.BoxGeometry(blockSize, blockSize, blockSize);
  // FIXED: Use resolveAssetPath for texture loading
  const blockTexture = loadTexture(resolveAssetPath("textures/blocks/cheese-stone.png"));
  const blockMaterial = new THREE.MeshLambertMaterial({ 
    map: blockTexture,
    // FIX: Remove emissive to show texture correctly (no yellow overlay)
    emissive: new THREE.Color(0x000000), // Black (no glow)
    emissiveIntensity: 0.0, // No emissive glow - show texture as-is
    transparent: false // Ensure block is fully opaque
  });
  
  const block = new THREE.Mesh(blockGeometry, blockMaterial);
  block.position.set(blockX, blockY, blockZ);
  // CRITICAL FIX: Unlockable block should be visible at Level 1 start
  // It becomes available after the player finds the trigger block (Step 0) and aims at it (Step 1)
  // But at game start, it should be visible so players can find it
  block.visible = true; // Visible at Level 1 start - players need to find it
  block.castShadow = false;
  block.receiveShadow = false;
  
  // Add userData for raycast detection
  block.userData.isRiddleBlock = true;
  block.userData.isUnlockableBlock = true;
  block.userData.riddleId = 'CHEESE_TEMPLE_RIDDLE_01';
  block.userData.triggerStep = 2;
  
  // Ensure block matrix is updated for proper raycasting
  block.matrixAutoUpdate = true;
  block.updateMatrix();
  block.updateMatrixWorld(true); // Force world matrix update
  
  scene.add(block);
  riddleState.unlockableBlock = block;
  
  // Store original position for Riddle #2 (movable block)
  riddleState.riddle2.unlockableBlockOriginalPosition = new THREE.Vector3(blockX, blockY, blockZ);
  
  // Mark block as movable for Riddle #2
  block.userData.isMovable = true;
  block.userData.isRiddle2Movable = true;
  
  console.log("🧩 [RIDDLE] Unlockable block created and added to scene:", {
    position: { x: blockX.toFixed(2), y: blockY.toFixed(2), z: blockZ.toFixed(2) },
    spawnY: spawnData.y,
    calculatedY: spawnData.y + 1,
    inScene: scene.children.includes(block),
    visible: block.visible
  });
}

// Create blinking oak stone for Riddle #2
function createRiddle2OakStone(spawnData, blockSize) {
  // Position: Middle platform (near spawn, same Y level as ground)
  // Place it at spawn position but offset by 3 blocks in X direction for visibility (not overlapping with spawn)
  const oakX = (spawnData.x + 3) * blockSize + blockSize / 2; // 3 blocks to the right of spawn
  const oakY = 1 * blockSize + blockSize / 2; // Ground level (y: 1.5, top at y: 2.0)
  const oakZ = spawnData.z * blockSize + blockSize / 2; // Same Z as spawn
  
  console.log("🧩 [RIDDLE #2] Creating blinking oak stone:", {
    spawnData: { x: spawnData.x, y: spawnData.y, z: spawnData.z },
    calculatedPosition: { x: oakX, y: oakY, z: oakZ },
    blockSize: blockSize
  });
  
  const oakGeometry = new THREE.BoxGeometry(blockSize, blockSize, blockSize);
  // FIXED: Use resolveAssetPath for texture loading
  const oakTexture = loadTexture(resolveAssetPath("textures/blocks/oak-planks.png"));
  const oakMaterial = new THREE.MeshLambertMaterial({ 
    map: oakTexture,
    // FIX: Remove emissive to show texture correctly (emissive will be added dynamically for blinking)
    emissive: new THREE.Color(0x000000), // Black (no base glow)
    emissiveIntensity: 0.0, // Start with no glow (will blink dynamically)
    transparent: false
  });
  
  const oakStone = new THREE.Mesh(oakGeometry, oakMaterial);
  oakStone.position.set(oakX, oakY, oakZ);
  oakStone.visible = false; // Hidden until Riddle #1 is complete (will be shown when Riddle #1 completes)
  oakStone.castShadow = false;
  oakStone.receiveShadow = false;
  
  // Add userData for Riddle #2
  oakStone.userData.isRiddleBlock = true;
  oakStone.userData.isRiddle2OakStone = true;
  oakStone.userData.riddleId = 'CHEESE_TEMPLE_RIDDLE_02';
  
  // Ensure matrix is updated
  oakStone.matrixAutoUpdate = true;
  oakStone.updateMatrix();
  oakStone.updateMatrixWorld(true);
  
  scene.add(oakStone);
  riddleState.riddle2.oakStone = oakStone;
  
  console.log("🧩 [RIDDLE #2] Blinking oak stone created and added to scene:", {
    position: { x: oakX.toFixed(2), y: oakY.toFixed(2), z: oakZ.toFixed(2) },
    inScene: scene.children.includes(oakStone),
    visible: oakStone.visible
  });
}

// Create lever for Riddle #3
