// Create 3 levers for Riddle #4 (Hidden Secret Riddle)
function createRiddle4Levers(spawnData, blockSize) {
  // Position: On a wall, spaced apart horizontally (side by side)
  // Move 10 blocks to the LEFT from x: 20 to x: 10 to reach the actual wall
  // Space them horizontally: lever1 at z: 95, lever2 at z: 100, lever3 at z: 105
  // Y position: y: 2.5 (same height for all, horizontal line)
  // Position them slightly forward from the wall so they're visible and clickable
  const wallX = 10 * blockSize + blockSize / 2; // Wall position (10 blocks left from x: 20 to reach wall)
  const leverY = 2 * blockSize + blockSize / 2; // y: 2.5 (same height for all levers)
  // Position levers slightly forward from wall (z: 100.2) so they're clearly visible
  const leverZ = 100 * blockSize + blockSize / 2 + 0.2; // z: 100.7 (slightly forward from wall at z: 100.5)
  
  console.log("🧩 [RIDDLE #4] Creating 3 secret levers on wall (horizontal):", {
    spawnData: { x: spawnData.x, y: spawnData.y, z: spawnData.z },
    wallX: wallX,
    leverY: leverY,
    leverZ: leverZ,
    blockSize: blockSize
  });
  
  // Create Lever 1 (left)
  const lever1Z = leverZ - 5 * blockSize; // z: 95.7 (5 blocks to the left)
  const lever1 = createRiddle4Lever(wallX, leverY, lever1Z, blockSize, 1);
  riddleState.riddle4.lever1 = lever1;
  
  // Create Lever 2 (middle)
  const lever2Z = leverZ; // z: 100.7 (middle position)
  const lever2 = createRiddle4Lever(wallX, leverY, lever2Z, blockSize, 2);
  riddleState.riddle4.lever2 = lever2;
  
  // Create Lever 3 (right)
  const lever3Z = leverZ + 5 * blockSize; // z: 105.7 (5 blocks to the right)
  const lever3 = createRiddle4Lever(wallX, leverY, lever3Z, blockSize, 3);
  riddleState.riddle4.lever3 = lever3;
  
  console.log("🧩 [RIDDLE #4] All 3 secret levers created and added to scene (horizontal line on wall at x: 10)");
}

// Helper function to create a single Riddle #4 lever
function createRiddle4Lever(x, y, z, blockSize, leverNumber) {
  // Lever geometry: width 0.8, height 0.6, depth 0.3 (flattened against wall)
  const leverGeometry = new THREE.BoxGeometry(blockSize * 0.8, blockSize * 0.6, blockSize * 0.3);
  // FIXED: Use resolveAssetPath for texture loading
  const leverTextureOff = loadTexture(resolveAssetPath("textures/blocks/slever1.png"));
  const leverMaterial = new THREE.MeshLambertMaterial({ 
    map: leverTextureOff,
    emissive: new THREE.Color(0x000000), // Black (no base glow)
    emissiveIntensity: 0.0, // No base emissive - texture shows correctly
    transparent: false
  });
  
  const lever = new THREE.Mesh(leverGeometry, leverMaterial);
  lever.position.set(x, y, z);
  // Rotate lever to face outward from wall (if on z: 0 wall, rotate 180 degrees on Y axis)
  // Actually, levers should face the player, so if wall is at z: 0, lever should face positive Z
  // No rotation needed - default orientation faces positive Z which is correct for z: 0 wall
  lever.visible = true; // Always visible (unlike Riddle #3 lever)
  lever.castShadow = false;
  lever.receiveShadow = false;
  
  // Add userData for Riddle #4
  lever.userData.isRiddleBlock = true;
  lever.userData.isRiddle4Lever = true;
  lever.userData.riddleId = 'CHEESE_TEMPLE_RIDDLE_04';
  lever.userData.leverNumber = leverNumber; // 1, 2, or 3
  lever.userData.leverState = 'off'; // off or on
  
  // Store off and on textures
  lever.userData.textureOff = leverTextureOff;
  // FIXED: Use resolveAssetPath for texture loading
  lever.userData.textureOn = loadTexture(resolveAssetPath("textures/blocks/slever2.png"));
  
  // Ensure matrix is updated
  lever.matrixAutoUpdate = true;
  lever.updateMatrix();
  lever.updateMatrixWorld(true);
  
  scene.add(lever);
  
  console.log(`🧩 [RIDDLE #4] Lever ${leverNumber} created:`, {
    position: { x: x.toFixed(2), y: y.toFixed(2), z: z.toFixed(2) },
    inScene: scene.children.includes(lever),
    visible: lever.visible
  });
  
  return lever;
}

function verifyAndFixLevel1ChestPositions() {
  if (!chestSystem || currentLevel !== LEVEL_IDS.LEVEL1) {
    return; // Only run in Level 1
  }
  
  const level1Chests = chestSystem.getChestsForLevel(LEVEL_IDS.LEVEL1);
  
  level1Chests.forEach((chest, chestId) => {
    if (chest.mesh) {
      // CRITICAL: Skip chest_003 entirely - it's on the tower top at Y=29
      if (chestId === 'chest_003') {
        console.log(`✅ [LEVEL 1] Chest ${chestId} on tower top - skipping all position verification`, {
          currentPosition: { x: chest.mesh.position.x, y: chest.mesh.position.y, z: chest.mesh.position.z },
          note: "Tower chest at Y=29 (custom elevation)"
        });
        return; // Skip all verification for tower chest
      }
      
      // Get expected position from chest config (ground-level chests only)
      const expectedX = chest.position.x;
      const expectedZ = chest.position.z;
      const boundingBoxBottom = chest.mesh.userData.boundingBoxBottom;
      const expectedY = chest.mesh.userData.calculatedY;
      
      // Check if X or Z position is wrong
      if (Math.abs(chest.mesh.position.x - expectedX) > 0.1 || Math.abs(chest.mesh.position.z - expectedZ) > 0.1) {
        console.warn(`🔧 [LEVEL 1] Chest ${chestId} X/Z position wrong, fixing:`, {
          currentX: chest.mesh.position.x,
          expectedX: expectedX,
          currentZ: chest.mesh.position.z,
          expectedZ: expectedZ
        });
        chest.mesh.position.x = expectedX;
        chest.mesh.position.z = expectedZ;
      }
      
      // Check if Y position is wrong
      // CRITICAL: Skip chest_003 - it's on the tower top at Y=29, NOT at ground level
      if (chestId !== 'chest_003' && boundingBoxBottom !== undefined && expectedY !== undefined) {
        // CRITICAL: Recalculate bounding box in world space to verify actual position
        // The stored boundingBoxBottom is in model space, but we need to verify in world space
        const worldBox = new THREE.Box3().setFromObject(chest.mesh);
        const worldMinY = worldBox.min.y; // Actual bottom Y in world space
        
        // Check if chest bottom is at 1.0 in world space (ground level only)
        if (Math.abs(worldMinY - 1.0) > 0.1) {
          console.warn(`🔧 [LEVEL 1] Chest ${chestId} bottom Y not at 1.0 (world space), adjusting:`, {
            currentWorldBottomY: worldMinY,
            targetBottomY: 1.0,
            currentPositionY: chest.mesh.position.y,
            storedBoundingBoxBottom: boundingBoxBottom,
            adjustment: 1.0 - worldMinY
          });
          
          // Calculate adjustment needed
          const adjustment = 1.0 - worldMinY;
          chest.mesh.position.y += adjustment;
          
          // Update stored calculatedY
          chest.mesh.userData.calculatedY = chest.mesh.position.y;
          chest.mesh.updateMatrixWorld(true);
          
          // Verify after adjustment
          const newWorldBox = new THREE.Box3().setFromObject(chest.mesh);
          const newWorldMinY = newWorldBox.min.y;
          console.log(`✅ [LEVEL 1] Chest ${chestId} Y position adjusted:`, {
            newWorldBottomY: newWorldMinY,
            newPositionY: chest.mesh.position.y,
            matchesBearTrap: Math.abs(newWorldMinY - 1.0) < 0.01
          });
        } else {
          // Position is correct, but verify stored values match
          if (Math.abs(chest.mesh.position.y - expectedY) > 0.1) {
            console.warn(`🔧 [LEVEL 1] Chest ${chestId} Y position lost (but bottom is correct), restoring:`, {
              currentY: chest.mesh.position.y,
              expectedY: expectedY,
              requestedY: 1.0,
              worldBottomY: worldMinY,
              difference: Math.abs(chest.mesh.position.y - expectedY)
            });
            chest.mesh.position.y = expectedY;
            chest.mesh.updateMatrixWorld(true);
          }
        }
      } else if (chestId !== 'chest_003') {
        // If userData is missing, recalculate Y position (skip chest_003 - it's on tower top)
        console.warn(`🔧 [LEVEL 1] Chest ${chestId} missing userData, recalculating Y position...`);
        const box = new THREE.Box3().setFromObject(chest.mesh);
        const size = box.getSize(new THREE.Vector3());
        const min = box.min;
        const max = box.max;
        
        if (size.y > 0 && min.y !== undefined) {
          // Use min.y directly (this is the Y coordinate of the bottom in model space)
          const boundingBoxBottom = min.y;
          const calculatedY = 1.0 - boundingBoxBottom;
          
          chest.mesh.position.y = calculatedY;
          chest.mesh.userData.boundingBoxBottom = boundingBoxBottom;
          chest.mesh.userData.calculatedY = calculatedY;
          chest.mesh.userData.requestedY = 1.0;
          chest.mesh.userData.originalMinY = min.y;
          chest.mesh.userData.originalMaxY = max.y;
          chest.mesh.updateMatrixWorld(true);
          
          console.log(`✅ [LEVEL 1] Chest ${chestId} Y position recalculated:`, {
            modelMinY: min.y,
            modelMaxY: max.y,
            boundingBoxBottom: boundingBoxBottom,
            calculatedY: calculatedY,
            finalBottomY: calculatedY + boundingBoxBottom
          });
        }
      } else {
        // chest_003 is on tower top - don't recalculate its Y position!
        console.log(`✅ [LEVEL 1] Chest ${chestId} on tower top - skipping Y position verification`, {
          currentY: chest.mesh.position.y,
          note: "Tower chest should stay at Y=29 (custom position)"
        });
      }
      
      // Ensure visibility and position
      chest.mesh.visible = true;
      chest.mesh.frustumCulled = false;
      chest.mesh.updateMatrixWorld(true);
      
      // Ensure all children are visible
      chest.mesh.traverse((child) => {
        if (child.isMesh) {
          child.visible = true;
          child.frustumCulled = false;
        }
      });
    }
  });
  
  console.log("✅ [LEVEL 1] Chest position verification complete");
}

// ============================================================================
// GAME LOOP - ANIMATE FUNCTION
// ============================================================================

function animate() {
  requestAnimationFrame(animate);

  if (stats) stats.begin();

  const delta = Math.min(clock.getDelta(), 0.1);
  
  if (delta > 0.2) {
    if (stats) stats.end();
    return;
  }

  if (playerControls) {
    playerControls.update(delta);
  }
  
  if (playerModelModule && playerModelModule.isLoaded()) {
    playerModelModule.update(delta);
  }
  
  if (guiSystem) {
    guiSystem.update(delta);
  }
  
  if (playerCharacterMixer && (useGLTFCharacter || window.currentCharacterAnimation === 'death')) {
    try {
      const animationDelta = Math.min(delta, 0.1);
      playerCharacterMixer.update(animationDelta);
    } catch (error) {
      // Silent fail
    }
  }

  if (!isGamePaused) {
    if (isClimbing) {
      // No gravity when climbing
    } else if (!godMode) {
      playerVelocity.y -= 30 * delta;
    } else {
      const currentMovement = playerControls ? playerControls.getMovementState() : movement;
      const flySpeed = 20;
      if (currentMovement.flyUp) {
        playerVelocity.y += flySpeed * delta;
      }
      if (currentMovement.flyDown) {
        playerVelocity.y -= flySpeed * delta;
      }
      if (!currentMovement.flyUp && !currentMovement.flyDown) {
        playerVelocity.y *= Math.exp(-8 * delta);
      }
    }

    const currentMovement = playerControls ? playerControls.getMovementState() : movement;
    const damping = Math.exp(-4 * delta) - 1;
    if (godMode && (currentMovement.flyUp || currentMovement.flyDown)) {
      const yVelocity = playerVelocity.y;
      playerVelocity.addScaledVector(playerVelocity, damping);
      playerVelocity.y = yVelocity;
    } else {
      playerVelocity.addScaledVector(playerVelocity, damping);
    }

    // Movement calculation
    if (currentMovement && (currentMovement.forward || currentMovement.backward || currentMovement.left || currentMovement.right)) {
      const moveSpeed = godMode ? 12 : 6; // Fixed: Much slower movement speed (was 168/96, now 12/6)
      const sprintMultiplier = currentMovement.sprint ? 1.75 : 1;
      const effectiveSpeed = moveSpeed * sprintMultiplier;
      
      const forwardVector = getForwardVector();
      const sideVector = getSideVector();
      
      playerVelocity.x = 0;
      playerVelocity.z = 0;
      
      if (currentMovement.forward) {
        playerVelocity.x += forwardVector.x * effectiveSpeed;
        playerVelocity.z += forwardVector.z * effectiveSpeed;
      }
      if (currentMovement.backward) {
        playerVelocity.x -= forwardVector.x * effectiveSpeed;
        playerVelocity.z -= forwardVector.z * effectiveSpeed;
      }
      if (currentMovement.left) {
        playerVelocity.x -= sideVector.x * effectiveSpeed;
        playerVelocity.z -= sideVector.z * effectiveSpeed;
      }
      if (currentMovement.right) {
        playerVelocity.x += sideVector.x * effectiveSpeed;
        playerVelocity.z += sideVector.z * effectiveSpeed;
      }
    }
    
    // Update player collisions and physics
    if (typeof playerCollisions === 'function') {
      playerCollisions();
    }
    
    // Update player position based on velocity
    playerCollider.start.addScaledVector(playerVelocity, delta);
    playerCollider.end.addScaledVector(playerVelocity, delta);
  }
  
  // Update camera position (handles both first-person and third-person modes)
  if (typeof updateCameraPosition === 'function') {
    updateCameraPosition(delta);
  } else if (camera && playerCollider) {
    // Fallback: simple first-person camera positioning
    if (isFirstPerson()) {
      camera.position.copy(playerCollider.end);
    }
  }
  
  // Update player model/character
  if (typeof updatePlayerCharacter === 'function') {
    updatePlayerCharacter(delta);
  } else if (playerModel && typeof playerModel.update === 'function') {
    playerModel.update(delta);
  } else if (playerModelModule && typeof playerModelModule.update === 'function') {
    playerModelModule.update(delta);
  }
  
  // Update footstep sound state (must be called after movement updates)
  if (typeof updateFootstepSoundState === 'function') {
    updateFootstepSoundState();
  }
  
  // Update floating cheese entity (Level 1 cheese hunting)
  if (floatingCheese && floatingCheese.mesh) {
    const playerPosition = new THREE.Vector3().lerpVectors(playerCollider.start, playerCollider.end, 0.5);
    floatingCheese.update(delta, playerPosition, awardCheesePoints);
  }
  
  // Update weapon system
  if (weaponSystem && typeof weaponSystem.update === 'function') {
    weaponSystem.update(delta);
  }
  
  // Update sky system
  if (skySystem && typeof skySystem.update === 'function') {
    skySystem.update(delta);
  }
  
  // Update grass system
  if (grassSystem && typeof grassSystem.update === 'function') {
    grassSystem.update(delta);
  }
  
  // Update level-specific systems
  if (currentLevel === LEVEL_IDS.LEVEL3) {
    if (typeof updateLevel3Monsters === 'function') {
      updateLevel3Monsters(delta);
    }
  }
  
  if (currentLevel === LEVEL_IDS.LEVEL6) {
    if (typeof level6State !== 'undefined' && level6State.phoenixBoss && typeof level6State.phoenixBoss.update === 'function') {
      level6State.phoenixBoss.update(delta);
    }
    if (typeof level6State !== 'undefined' && level6State.alienSpiderBoss && typeof level6State.alienSpiderBoss.update === 'function') {
      level6State.alienSpiderBoss.update(delta);
    }
  }
  
  // Render the scene
  if (renderer && scene && camera) {
    renderer.render(scene, camera);
  }
  
  if (stats) stats.end();
}

// Start the game loop
animate();